import { describeImage } from "@/lib/decide";
import { SubqError } from "@/lib/subq";

// Snap's look at an image as it's attached: what kind, light or dark, any text. Shown on the attachment.

export async function POST(request: Request) {
  const body = (await request.json()) as { name: string; note?: string; mediaType: string; base64: string };
  try {
    const tags = await describeImage({ ...body, note: body.note ?? "", signal: request.signal });
    return Response.json(tags);
  } catch (e) {
    const message = e instanceof SubqError ? e.message : "Snap couldn't look at that image.";
    return Response.json({ error: message }, { status: e instanceof SubqError && e.status ? e.status : 500 });
  }
}

import { fetchFiles, GithubError } from "@/lib/github";

// The text of a batch of chosen files. The dialog asks in batches, so it can show how far along it is.

export async function POST(request: Request) {
  const body = (await request.json()) as { owner: string; repo: string; ref: string; paths: string[] };
  try {
    return Response.json({ files: await fetchFiles(body, request.signal) });
  } catch (e) {
    const known = e instanceof GithubError;
    return Response.json({ error: known ? e.message : "Couldn't reach GitHub." }, { status: known ? e.status : 502 });
  }
}

import { GithubError, listRepo } from "@/lib/github";

// What's in a repository: the files this chat can read, with their sizes, before any of them is fetched.

export async function POST(request: Request) {
  const { repo } = (await request.json()) as { repo: string };
  try {
    return Response.json(await listRepo(repo ?? "", request.signal));
  } catch (e) {
    const known = e instanceof GithubError;
    return Response.json({ error: known ? e.message : "Couldn't reach GitHub." }, { status: known ? e.status : 502 });
  }
}

import { PageError, readPage } from "@/lib/page";

// A web page as text, for adding to a chat.

export async function POST(request: Request) {
  const { url } = (await request.json()) as { url: string };
  try {
    return Response.json(await readPage(url ?? "", request.signal));
  } catch (e) {
    return Response.json({ error: e instanceof PageError ? e.message : "Couldn't read that page." }, { status: 400 });
  }
}

import { parsePartialJson } from "ai";
import { decideTurn } from "@/lib/decide";
import { withPdfText } from "@/lib/pdf";
import { extraKey, replySchema, writerMessages } from "@/lib/prompt";
import { SubqError, write, writer } from "@/lib/subq";
import type { TurnEvent, TurnRequest } from "@/lib/types";

// One turn, streamed as NDJSON: Snap's decision the moment it lands, then the writer's reply as it grows.

const PARTIAL_EVERY_MS = 50;

/**
 * House style, enforced rather than hoped for: no em dashes in anything the writer produces (prose or the
 * component's strings). "a — b" and "a—b" both become "a, b"; a number range keeps a hyphen.
 */
function tidy<T>(value: T): T {
  if (typeof value === "string")
    return value
      .replace(/(\d)\s*[—–]\s*(\d)/g, "$1-$2") // ranges keep a plain hyphen: 2019-2020
      .replace(/\s*[—–]\s*/g, ", ")
      .replace(/^\s+/, "") as T;
  if (Array.isArray(value)) return value.map(tidy) as T;
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, tidy(v)])) as T;
  return value;
}

const explain = (e: unknown) => (e instanceof SubqError ? e.message : "Something went wrong talking to SubQ. Try again.");

export async function POST(request: Request) {
  // PDFs are read into text first, so Snap and every writer see them like any other document.
  const req = await withPdfText((await request.json()) as TurnRequest);
  const signal = request.signal;
  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    async start(controller) {
      const send = (event: TurnEvent) => {
        if (!signal.aborted) controller.enqueue(encoder.encode(`${JSON.stringify(event)}\n`));
      };
      const fail = (stage: "decide" | "write", e: unknown) => {
        if (signal.aborted) return;
        console.error(e);
        send({ type: "error", stage, message: explain(e) });
      };

      let decision;
      try {
        decision = await decideTurn(req, signal);
        send({ type: "decision", decision });
      } catch (e) {
        fail("decide", e);
        controller.close();
        return;
      }

      const schema = replySchema(decision);
      const shape = async (raw: string) => {
        if (!schema) return { text: tidy(raw) };
        const { value } = await parsePartialJson(raw);
        const v = (value ?? {}) as { text?: string; data?: unknown } & Record<string, unknown>;
        const extras = decision.extras?.length ? decision.extras.map((id) => tidy(v[extraKey(id)])) : undefined;
        return { text: tidy(v.text ?? ""), data: tidy(v.data), ...(extras && { extras }) };
      };

      const started = performance.now();
      let last = 0;
      // Partials are parsed one after another so they reach the browser in order.
      let queue = Promise.resolve();
      try {
        const raw = await write({
          messages: writerMessages(req, decision, writer()),
          schema,
          signal,
          onText: (soFar) => {
            const now = performance.now();
            if (now - last < PARTIAL_EVERY_MS) return;
            last = now;
            queue = queue.then(async () => send({ type: "partial", ...(await shape(soFar)) }));
          },
        });
        await queue;
        send({ type: "done", ...(await shape(raw)), writeMs: Math.round(performance.now() - started), writer: writer().model });
      } catch (e) {
        fail("write", e);
      }
      controller.close();
    },
  });

  return new Response(stream, {
    headers: { "Content-Type": "application/x-ndjson; charset=utf-8", "Cache-Control": "no-store" },
  });
}

"use client";

import Link from "next/link";
import { useState } from "react";
import { ArtifactsContext, Block, ChatActionsContext } from "@/components/blocks";
import { ChevronLeftIcon } from "@/components/icons";
import { Prose } from "@/components/prose";
import { type BlockId, blockIds, blocks } from "@/lib/blocks";
import { extraSamples, samples } from "@/lib/samples";
import type { Artifact } from "@/lib/types";

// Every component Snap can pick, with what it's told about each and a working example: tick, sort, answer, edit,
// it all works here as it would in a reply. Examples are samples, shown as samples: no decision line.

const slugs = ["folder-maker", "handdrawn-frames", "dia-gradient", "video-cube", "axolotl-pond", "pixel-art"];
const artifacts: Record<string, Artifact> = Object.fromEntries(
  slugs.map((s, i) => [
    `a${i + 1}`,
    { id: `a${i + 1}`, kind: "image", name: s.replace(/-/g, " "), mediaType: "image/webp", src: `/demo/${s}.webp`, bytes: 0 },
  ]),
);

/** One live example with its own state, as a reply would have. */
function Sample({ id, initial }: { id: BlockId; initial: unknown }) {
  const [data, setData] = useState(initial);
  const [answer, setAnswer] = useState<string>();
  return (
    <ChatActionsContext value={{ send: setAnswer, busy: false, compose: () => {} }}>
      <Block id={id} data={data} settled answer={answer} onChange={setData} />
    </ChatActionsContext>
  );
}

export function Catalog() {
  return (
    <ArtifactsContext value={artifacts}>
      <main className="mx-auto flex w-full max-w-[760px] flex-col gap-14 px-5 pt-8 pb-24">
        <header className="flex flex-col gap-3">
          <Link
            href="/"
            className="focus-ring -ms-1.5 flex h-8 w-fit items-center gap-1 rounded-[10px] ps-1 pe-2.5 text-[13px] text-fg-4 hover:bg-white/[0.05] hover:text-fg"
          >
            <ChevronLeftIcon size={15} />
            Chat
          </Link>
          <h1 className="text-[22px] font-medium tracking-[-0.02em] text-fg">What Snap chooses from</h1>
          <p className="max-w-[60ch] text-[14px] text-pretty text-fg-4">
            Every turn, Snap weighs all {blockIds.length} and picks the one that fits, or up to three when you ask for several things at once. Under each name is exactly what Snap is told about it. Each example
            works: try them.
          </p>
          <nav aria-label="Components" className="flex flex-wrap gap-1 pt-1">
            {blockIds.map((id) => (
              <a key={id} href={`#${id}`} className="focus-ring h-7 rounded-[8px] bg-surface px-2 text-[12px] leading-7 text-fg-3 hover:bg-surface-hover hover:text-fg">
                {blocks[id].label}
              </a>
            ))}
          </nav>
        </header>
        {blockIds.map((id, i) => (
          <section key={id} id={id} className="flex scroll-mt-6 flex-col gap-3">
            <div className="flex flex-col gap-1">
              <h2 className="text-[15px] font-medium text-fg">
                <span className="text-fg-5 tabular-nums">{i + 1}.</span> {blocks[id].label}
              </h2>
              <p className="text-[13px] text-pretty text-fg-4">{blocks[id].snap}</p>
            </div>
            {id === "text" ? (
              <Prose text="Plain prose when structure wouldn't help: a short answer, an opinion, an explanation. **Bold**, `code` and simple lists are all it needs." />
            ) : (
              <Sample id={id} initial={samples[id]} />
            )}
            {extraSamples
              .filter((e) => e.id === id)
              .map((e) => (
                <div key={e.title} className="flex flex-col gap-2 pt-3">
                  <p className="text-[12px] text-fg-5">{e.title}</p>
                  <Sample id={e.id} initial={e.data} />
                </div>
              ))}
          </section>
        ))}
      </main>
    </ArtifactsContext>
  );
}

import type { Metadata } from "next";
import { Catalog } from "./catalog";

export const metadata: Metadata = {
  title: "Components · what Snap chooses from",
  description: "Every component SubQ Snap can pick to show an answer, with an example of each.",
};

export default function Page() {
  return <Catalog />;
}

@import "tailwindcss";

/* Anish's lab, in the dark: plain, minimal, rounded. The light text is the accent; colour only means something.
   Text steps (fg to fg-5) all clear 4.5:1 on the page; fg-6 is for separators only. */
:root {
  color-scheme: dark;
  --background: #0e0e0e;
  --foreground: #969696;
  --sidebar: #141414;
  --surface: #1a1a1a;
  --surface-hover: #212121;
  /* filled controls on the page: user bubbles, chips, the meter */
  --control: #1f1f1f;
  --control-hover: #282828;
  /* cards, the composer, popovers: a step up from the page */
  --raised: #171717;
  --fg: #ededed;
  --fg-2: #c9c9c9;
  --fg-3: #a8a8a8;
  --fg-4: #969696;
  --fg-5: #7c7c7c;
  --fg-6: #474747;
  --accent: #ededed;
  --accent-fg: #0e0e0e;
  --line: rgb(255 255 255 / 0.08);
  --line-strong: rgb(255 255 255 / 0.2);
  /* keyboard focus: near-white, 14:1 or more against the page, the controls and the raised surface */
  --focus: #ededed;
  /* Chart series, in this order and never cycled: the dataviz reference's dark steps, validated on --raised
     (#171717). The first three pass all-pairs (bars and lines cap at three); five are for split bars only. */
  --series-1: #3987e5;
  --series-2: #d95926;
  --series-3: #199e70;
  --series-4: #c98500;
  --series-5: #d55181;
  /* status, never a series: always with an icon and words */
  --good: #0ca30c;
  --bad: #e66767;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-sidebar: var(--sidebar);
  --color-surface: var(--surface);
  --color-surface-hover: var(--surface-hover);
  --color-control: var(--control);
  --color-control-hover: var(--control-hover);
  --color-raised: var(--raised);
  --color-fg: var(--fg);
  --color-fg-2: var(--fg-2);
  --color-fg-3: var(--fg-3);
  --color-fg-4: var(--fg-4);
  --color-fg-5: var(--fg-5);
  --color-fg-6: var(--fg-6);
  --color-accent: var(--accent);
  --color-accent-fg: var(--accent-fg);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-focus: var(--focus);
  --color-series-1: var(--series-1);
  --color-series-2: var(--series-2);
  --color-series-3: var(--series-3);
  --color-series-4: var(--series-4);
  --color-series-5: var(--series-5);
  --color-good: var(--good);
  --color-bad: var(--bad);
  --font-sans: var(--font-public-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-jetbrains), ui-monospace, monospace;
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  /* On dark, depth is a hairline of light at the edge plus a deeper drop, not a soft grey shadow. */
  --shadow-surface: 0 0 0 1px rgb(255 255 255 / 0.07), 0 1px 2px -1px rgb(0 0 0 / 0.5), 0 2px 6px 0 rgb(0 0 0 / 0.35);
  --shadow-faint: 0 0 0 1px rgb(255 255 255 / 0.06), 0 1px 2px 0 rgb(0 0 0 / 0.3);
  --shadow-popover: 0 0 0 1px rgb(255 255 255 / 0.09), 0 4px 8px -2px rgb(0 0 0 / 0.5), 0 12px 28px -4px rgb(0 0 0 / 0.6);
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scrollbar-gutter: stable;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
}

button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: #3a3a3a;
  color: #ffffff;
}

/* Loading placeholders: a soft sheen passing over the surface. Still under reduced motion. */
@keyframes skeleton-sheen {
  from {
    background-position: 150% 0;
  }
  to {
    background-position: -50% 0;
  }
}

@utility skeleton {
  background-color: var(--color-surface);
  background-image: linear-gradient(100deg, transparent 30%, rgb(255 255 255 / 0.05) 50%, transparent 70%);
  background-size: 200% 100%;
  animation: skeleton-sheen 1.6s ease-in-out infinite;
  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
}

/* The keyboard focus ring for custom controls: 2px solid, 2px out. Forced colors fall back to Highlight. */
@utility focus-ring {
  outline: none;
  &:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
  }
  @media (forced-colors: active) {
    &:focus-visible {
      outline-color: Highlight;
    }
  }
}

/* Text fields keep their fill on focus and ease in a soft two-layer ring (3:1 or more against page and fill). */
@utility field-focus {
  box-shadow: var(--shadow-surface), 0 0 0 2px rgb(237 237 237 / 0), 0 0 0 5px rgb(255 255 255 / 0);
  &:focus-within {
    box-shadow: var(--shadow-surface), 0 0 0 2px rgb(237 237 237 / 0.4), 0 0 0 5px rgb(255 255 255 / 0.05);
  }
}

/* A row that scrolls sideways without showing a scrollbar (suggestions on a phone). */
@utility no-scrollbar {
  scrollbar-width: none;
  &::-webkit-scrollbar {
    display: none;
  }
}

/* Streaming text: the caret that trails the words while the writer is still going. */
@keyframes caret-blink {
  50% {
    opacity: 0;
  }
}

@utility caret {
  &::after {
    content: "";
    display: inline-block;
    width: 2px;
    height: 1em;
    margin-inline-start: 2px;
    vertical-align: -0.15em;
    border-radius: 1px;
    background: currentColor;
    animation: caret-blink 1s steps(1) infinite;
  }
}

/* A slider in the house style: a 4px track filled up to the thumb (--fill, 0% to 100%), a round thumb that grows a
   touch while held, and the focus ring on the thumb. Used by the Calculator. */
@utility range {
  appearance: none;
  height: 20px;
  background: transparent;
  cursor: pointer;
  &::-webkit-slider-runnable-track {
    height: 4px;
    border-radius: 999px;
    background: linear-gradient(to right, var(--accent) var(--fill, 0%), rgb(255 255 255 / 0.1) var(--fill, 0%));
  }
  &::-moz-range-track {
    height: 4px;
    border-radius: 999px;
    background: linear-gradient(to right, var(--accent) var(--fill, 0%), rgb(255 255 255 / 0.1) var(--fill, 0%));
  }
  &::-webkit-slider-thumb {
    appearance: none;
    margin-top: -6px;
    width: 16px;
    height: 16px;
    border-radius: 999px;
    background: var(--accent);
    box-shadow: 0 0 0 3px var(--raised), 0 1px 3px rgb(0 0 0 / 0.5);
    transition: scale 150ms var(--ease-out);
  }
  &::-moz-range-thumb {
    width: 16px;
    height: 16px;
    border: 0;
    border-radius: 999px;
    background: var(--accent);
    box-shadow: 0 0 0 3px var(--raised), 0 1px 3px rgb(0 0 0 / 0.5);
  }
  &:active::-webkit-slider-thumb {
    scale: 1.15;
  }
  &:focus-visible {
    outline: none;
  }
  &:focus-visible::-webkit-slider-thumb {
    box-shadow: 0 0 0 3px var(--raised), 0 0 0 5px var(--focus);
  }
  &:focus-visible::-moz-range-thumb {
    box-shadow: 0 0 0 3px var(--raised), 0 0 0 5px var(--focus);
  }
}

import type { Metadata } from "next";
import { JetBrains_Mono, Public_Sans } from "next/font/google";
