/* eslint-disable @typescript-eslint/no-explicit-any -- streamed data is checked field by field inside each block */
type View = {
  View: (p: { data: any; settled: boolean; answer?: string; onChange?: (d: unknown) => void }) => React.ReactNode;
  Skeleton: () => React.ReactNode;
  /** Enough has arrived to show the real thing instead of its skeleton. */
  ready: (d: any) => boolean;
  /** The block as plain text, for Copy under the reply and in the card's top bar. */
  text?: (d: any) => string;
  /** The component's own icon in the card's top bar. */
  icon: ComponentType<{ size?: number; className?: string }>;
  /** A short detail beside the name in the top bar: "5 rows", "3 questions", "hero.tsx". */
  meta?: (d: any) => string | undefined;
};

const count = (n: number | undefined, one: string, many = `${one}s`) => (n ? `${n} ${n === 1 ? one : many}` : undefined);
const CHART_KIND: Record<string, string> = { line: "Line", area: "Area", bar: "Bar", stacked: "Stacked bars", ranked: "Ranked", pie: "Pie", split: "Split" };

const views: Record<Exclude<BlockId, "text">, View> = {
  comparison: { View: Comparison, Skeleton: ComparisonSkeleton, ready: (d) => !!d?.options?.length, text: comparisonText, icon: EyeIcon, meta: (d) => count(d?.options?.length, "option") },
  gallery: { View: Gallery, Skeleton: GallerySkeleton, ready: (d) => !!d?.items?.length, icon: ImageIcon, meta: (d) => count(d?.items?.length, "item") },
  timeline: { View: Timeline, Skeleton: TimelineSkeleton, ready: (d) => !!d?.events?.length, text: timelineText, icon: ForwardIcon, meta: (d) => count(d?.events?.length, "event") },
  checklist: { View: Checklist, Skeleton: ChecklistSkeleton, ready: (d) => !!d?.items?.length || !!d?.title, text: checklistText, icon: ChecklistIcon },
  decision: { View: Verdict, Skeleton: VerdictSkeleton, ready: (d) => !!d?.verdict, text: decisionText, icon: CheckIcon },
  table: { View: Table, Skeleton: TableSkeleton, ready: (d) => !!d?.columns?.length, text: tableText, icon: SpacesIcon, meta: (d) => count(d?.rows?.length, "row") },
  steps: { View: Steps, Skeleton: StepsSkeleton, ready: (d) => !!d?.steps?.length, text: stepsText, icon: ClipboardIcon, meta: (d) => count(d?.steps?.length, "step") },
  chart: { View: Chart, Skeleton: ChartSkeleton, ready: (d) => !!d?.labels?.length && !!d?.series?.[0]?.values?.length, text: chartText, icon: PollIcon, meta: (d) => CHART_KIND[d?.kind] },
  stats: { View: Stats, Skeleton: StatsSkeleton, ready: (d) => !!d?.items?.[0]?.value, text: statsText, icon: BoltIcon },
  map: { View: MapBlock, Skeleton: MapSkeleton, ready: (d) => typeof d?.places?.[0]?.lng === "number", text: mapText, icon: GlobeIcon, meta: (d) => (d?.route ? count(d?.places?.length, "stop") : count(d?.places?.length, "place")) },
  code: { View: Code, Skeleton: CodeSkeleton, ready: (d) => !!d?.code, text: (d) => d?.code ?? "", icon: TabIcon, meta: (d) => d?.filename || d?.language },
  calendar: {
    View: Calendar,
    Skeleton: CalendarSkeleton,
    ready: (d) => /^\d{4}-\d{2}-\d{2}$/.test(d?.events?.[0]?.date ?? "") && !!d?.events?.[0]?.title,
    text: calendarText, icon: CalendarIcon, meta: (d) => count(d?.events?.length, "event") },
  options: { View: Options, Skeleton: OptionsSkeleton, ready: (d) => !!d?.options?.length, icon: ChatIcon, meta: (d) => (d?.multiple ? "Pick any" : "Pick one") },
  matrix: { View: Matrix, Skeleton: MatrixSkeleton, ready: (d) => typeof d?.items?.[0]?.y === "number", text: matrixText, icon: TargetIcon, meta: (d) => count(d?.items?.length, "item") },
  tree: { View: Tree, Skeleton: TreeSkeleton, ready: (d) => !!d?.items?.length, text: treeText, icon: FolderIcon, meta: (d) => (d?.kind === "files" ? "Files" : "Outline") },
  recipe: { View: Recipe, Skeleton: RecipeSkeleton, ready: (d) => !!d?.ingredients?.length, text: recipeText, icon: BucketIcon, meta: (d) => (d?.prep || d?.cook ? [d.prep && `prep ${d.prep}`, d.cook && `cook ${d.cook}`].filter(Boolean).join(", ") : undefined) },
  quiz: { View: Quiz, Skeleton: () => <QuizSkeleton />, ready: (d) => !!d?.questions?.[0]?.choices?.length, text: quizText, icon: SparkleIcon, meta: (d) => count(d?.questions?.length, "question") },
  itinerary: { View: Itinerary, Skeleton: ItinerarySkeleton, ready: (d) => !!d?.days?.[0]?.items?.length, text: itineraryText, icon: PlaneIcon, meta: (d) => count(d?.days?.length, "day") },
  proscons: { View: ProsCons, Skeleton: ProsConsSkeleton, ready: (d) => !!d?.pros?.length || !!d?.cons?.length, text: prosConsText, icon: HeartIcon, meta: (d) => (d?.pros || d?.cons ? `${d?.pros?.length ?? 0} for, ${d?.cons?.length ?? 0} against` : undefined) },
  scorecard: { View: Scorecard, Skeleton: ScorecardSkeleton, ready: (d) => typeof d?.criteria?.[0]?.score === "number", text: scorecardText, icon: StarIcon, meta: (d) => count(d?.criteria?.length, "criterion", "criteria") },
  draft: { View: Draft, Skeleton: DraftSkeleton, ready: (d) => !!d?.body, text: draftText, icon: MailIcon, meta: (d) => ({ email: "Email", message: "Message", post: "Post" })[d?.kind as string] },
  links: { View: Links, Skeleton: LinksSkeleton, ready: (d) => /^https?:\/\/.+\..+/.test(d?.items?.[0]?.url ?? ""), text: linksText, icon: LinkIcon, meta: (d) => count(d?.items?.length, "link") },
  rewrite: { View: Rewrite, Skeleton: RewriteSkeleton, ready: (d) => !!d?.revised, text: rewriteText, icon: MarkerIcon },
  breakdown: { View: Breakdown, Skeleton: BreakdownSkeleton, ready: (d) => typeof d?.items?.[0]?.amount === "number", text: breakdownText, icon: WalletIcon, meta: (d) => count(d?.items?.length, "item") },
  calculator: {
    View: Calculator,
    Skeleton: CalculatorSkeleton,
    ready: (d) => typeof d?.inputs?.[0]?.max === "number" && !!d?.outputs?.[0]?.formula,
    text: calculatorText,
    icon: CalculatorIcon,
    meta: (d) => count(d?.inputs?.length, "input"),
  },
  timer: {
    View: Timer,
    Skeleton: TimerSkeleton,
    ready: (d) => typeof d?.phases?.[0]?.seconds === "number",
    text: timerText,
    icon: TimerIcon,
    meta: (d) => {
      const s = (d?.phases ?? []).reduce((t: number, p: { seconds?: number }) => t + (p?.seconds ?? 0), 0) * Math.max(1, d?.rounds ?? 1);
      return s ? `${Math.round(s / 60)} min in all` : undefined;
    },
  },
  flashcards: { View: Flashcards, Skeleton: FlashcardsSkeleton, ready: (d) => !!d?.cards?.[0]?.back, text: flashcardsText, icon: BookmarkIcon, meta: (d) => count(d?.cards?.length, "card") },
  compare: {
    View: Compare,
    Skeleton: CompareSkeleton,
    ready: (d) => !!d?.before && !!d?.after,
    text: compareText,
    icon: ViewfinderIcon,
    meta: (d) => (d?.before_label && d?.after_label ? `${d.before_label} and ${d.after_label}` : undefined),
  },
};
/* eslint-enable @typescript-eslint/no-explicit-any */

/** Whether a component's data arrived complete enough to show. */
export function blockReady(id: BlockId, data: unknown) {
  return id === "text" || (!!data && views[id].ready(data));
}

/** A component as plain text, for copying a whole reply. */
export function blockText(id: BlockId, data: unknown) {
  if (id === "text" || !data) return "";
  const v = views[id];
  return v.ready(data) ? (v.text?.(data) ?? "") : "";
}

/**
 * The component Snap chose. Its skeleton holds the shape from the moment the decision lands; the real thing
 * blur-fades in over it once the writer's first items arrive. Text needs no block.
 */
export function Block({
  id,
  data,
  settled,
  answer,
  onChange,
}: {
  id: BlockId;
  data: unknown;
  settled: boolean;
  answer?: string;
  onChange?: (data: unknown) => void;
}) {
  // the slot the view's own tools are portalled into; a state setter so the view re-renders once it exists
  const [slot, setSlot] = useState<HTMLElement | null>(null);
  if (id === "text") return null;
  const { View, Skeleton, ready, icon: Icon, meta, text } = views[id];
  const show = ready(data);
  // Finished with nothing to show: say nothing rather than leave a skeleton behind.
  if (settled && !show) return null;
  const detail = show ? meta?.(data) : undefined;
  return (
    <div className="rounded-[20px] bg-raised shadow-surface">
      {/* The top bar every component shares: what it is, a detail, its own tools, and Copy, always in one place. */}
      <div className="flex h-11 items-center justify-between gap-3 ps-4 pe-2">
        <span className="flex min-w-0 items-center gap-2 text-[12px]">
          <Icon size={14} className="shrink-0 text-fg-4" />
          <span className="shrink-0 font-medium text-fg-3">{blocks[id].label}</span>
          {detail && (
            <>
              <span aria-hidden className="text-fg-6">
                ·
              </span>
              <Swap value={detail} className="truncate text-fg-5 tabular-nums" />
            </>
          )}
        </span>
        <div className="flex shrink-0 items-center gap-0.5">
          <div ref={setSlot} className="flex items-center gap-0.5" />
          <AnimatePresence initial={false}>
            {settled && show && text && (
              <motion.span
                className="flex"
                initial={{ opacity: 0, filter: "blur(4px)" }}
                animate={{ opacity: 1, filter: "blur(0px)", transition: { duration: 0.2, ease: easeOut } }}
              >
                <CopyAction showLabel={false} label={`Copy ${blocks[id].label.toLowerCase()}`} text={() => text(data)} />
              </motion.span>
            )}
          </AnimatePresence>
        </div>
      </div>
      <div className="grid px-2 pb-2">
        <ToolsSlot value={slot}>
          <AnimatePresence initial={false}>
            <motion.div
              key={show ? "view" : "skeleton"}
              className="col-start-1 row-start-1 min-w-0"
              initial={{ opacity: 0, filter: "blur(4px)" }}
              animate={{ opacity: 1, filter: "blur(0px)" }}
              exit={{ opacity: 0, transition: { duration: 0.12 } }}
              transition={{ duration: 0.3, ease: easeOut }}
            >
              {show ? <View data={data} settled={settled} answer={answer} onChange={onChange} /> : <Skeleton />}
            </motion.div>
          </AnimatePresence>
        </ToolsSlot>
      </div>
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { useId, useState } from "react";
import { ArrowUpRightIcon } from "@/components/icons";
import type { ItineraryData } from "@/lib/blocks";
import { easeOut, glide } from "@/lib/motion";
import { Action, Arrive, Bar, BlockHeader, type BlockProps } from "./shared";

// A plan by day. Short plans list every day; longer ones get a row of day tabs (arrow keys move between them, the
// day slides the way you went). Each stop: the time in its own column, what, where (opens in Maps), a note.

export function Itinerary({ data }: BlockProps<ItineraryData>) {
  const days = (data.days ?? []).filter((d) => d?.label);
  const [tab, setTab] = useState(0);
  const id = useId();
  const [dir, setDir] = useState(1);
  const tabbed = days.length > 2;
  const go = (i: number) => {
    setDir(i > tab ? 1 : -1);
    setTab(Math.max(0, Math.min(days.length - 1, i)));
  };
  const shown = tabbed ? [days[Math.min(tab, days.length - 1)]] : days;

  return (
    <div className="flex flex-col gap-3 px-2 py-1">
      <BlockHeader title={data.title} />
      {tabbed && (
        <div role="tablist" aria-label="Days" className="no-scrollbar -mx-1 flex gap-1 overflow-x-auto px-1">
          {days.map((d, i) => (
            <button
              key={i}
              type="button"
              role="tab"
              aria-selected={i === tab}
              tabIndex={i === tab ? 0 : -1}
              onClick={() => go(i)}
              onKeyDown={(e) => {
                if (e.key === "ArrowRight") go(tab + 1);
                if (e.key === "ArrowLeft") go(tab - 1);
              }}
              className={`focus-ring relative h-8 shrink-0 rounded-[10px] px-3 text-[13px] whitespace-nowrap transition-colors duration-200 ${
                i === tab ? "text-fg" : "text-fg-4 hover:text-fg-2"
              }`}
            >
              {/* the selected day's fill slides from tab to tab */}
              {i === tab && (
                <motion.span layoutId={`${id}-day`} transition={glide} className="absolute inset-0 rounded-[10px] bg-control shadow-[inset_0_0_0_1px_var(--line)]" />
              )}
              <span className="relative font-medium">{d?.label}</span>
            </button>
          ))}
        </div>
      )}
      <div className="overflow-hidden">
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.div
            key={tabbed ? tab : "all"}
            className="flex flex-col gap-5"
            initial={tabbed ? { opacity: 0, x: dir * 16 } : false}
            animate={{ opacity: 1, x: 0, transition: { duration: 0.25, ease: easeOut } }}
            exit={{ opacity: 0, x: dir * -16, transition: { duration: 0.12, ease: easeOut } }}
          >
            {shown.map((d, di) => (
              <section key={di} className="flex flex-col gap-1">
                {!tabbed && <h4 className="text-[12px] font-medium text-fg-3">{d?.label}</h4>}
                <ol className="flex flex-col">
                  {(d?.items ?? []).map((it, i) => (
                    <Arrive as="li" key={i} className="group grid grid-cols-[4.25rem_1fr_auto] items-start gap-x-3 rounded-[8px] py-2">
                      <span className="pt-px text-[12px] text-fg-4 tabular-nums">{it?.time}</span>
                      <span className="flex min-w-0 flex-col gap-0.5">
                        <span className="text-[14px] text-fg">{it?.title}</span>
                        {(it?.place || it?.note) && (
                          <span className="text-[12px] text-pretty text-fg-4">
                            {it?.place}
                            {it?.place && it?.note && " · "}
                            {it?.note}
                          </span>
                        )}
                      </span>
                      {it?.place ? (
                        <Action
                          showLabel={false}
                          label={`Open ${it.place} in Maps`}
                          icon={<ArrowUpRightIcon size={13} />}
                          href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(it.place)}`}
                        />
                      ) : (
                        <span />
                      )}
                    </Arrive>
                  ))}
                </ol>
              </section>
            ))}
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

export const itineraryText = (d: BlockProps<ItineraryData>["data"]) =>
  [d.title, ...(d.days ?? []).flatMap((day) => ["", day?.label, ...(day?.items ?? []).map((i) => `${i?.time}  ${i?.title}${i?.place ? `, ${i.place}` : ""}${i?.note ? ` (${i.note})` : ""}`)])]
    .filter((x) => x !== undefined)
    .join("\n");

export function ItinerarySkeleton() {
  return (
    <div className="flex flex-col gap-3 px-2 py-1">
      <Bar className="h-3.5 w-1/3" />
      <div className="flex gap-1">
        {[0, 1, 2].map((i) => (
          <Bar key={i} className="h-8 w-16" />
        ))}
      </div>
      {[0, 1, 2, 3].map((i) => (
        <div key={i} className="flex gap-3">
          <Bar className="h-3 w-12" />
          <Bar className="h-3 w-1/2" />
        </div>
      ))}
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";
import { CheckIcon } from "@/components/icons";
import { inline } from "@/components/prose";
import type { ChecklistData, StepsData, TimelineData } from "@/lib/blocks";
import { easeOut, iconSwap, rowPress, tap } from "@/lib/motion";
import { Arrive, Bar, BlockHeader, type BlockProps, MoreToggle, Swap } from "./shared";

const FOLD = 6;

/** Rows that open and close with a "Show more": height and opacity, quick out. */
const fold = {
  initial: { opacity: 0, height: 0 },
  animate: { opacity: 1, height: "auto", transition: { duration: 0.28, ease: easeOut } },
  exit: { opacity: 0, height: 0, transition: { duration: 0.18, ease: easeOut } },
};

/**
 * A round check. Pressing it gives a slight squeeze (the row itself doesn't scale); the fill fades in and the tick
 * draws itself, so a change of state is never a jump.
 */
function Check({ done }: { done: boolean }) {
  return (
    <span
      className={`relative flex size-[18px] shrink-0 items-center justify-center rounded-full transition-[background-color,box-shadow,scale] duration-150 ease-out group-active:scale-90 ${
        done ? "bg-accent text-accent-fg shadow-[inset_0_0_0_1.5px_var(--color-accent)]" : "bg-transparent shadow-[inset_0_0_0_1.5px_var(--color-line-strong)]"
      }`}
    >
      <svg viewBox="0 0 18 18" className="size-3" aria-hidden>
        <motion.path
          d="M4.4 9.6l3 3 6.2-6.4"
          fill="none"
          stroke="currentColor"
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={false}
          animate={{ pathLength: done ? 1 : 0, opacity: done ? 1 : 0 }}
          transition={{ duration: done ? 0.22 : 0.12, ease: easeOut }}
        />
      </svg>
    </span>
  );
}

/** A thin bar of how much is done. */
function Progress({ done, total }: { done: number; total: number }) {
  return (
    <div className="h-1 overflow-hidden rounded-full bg-white/[0.08]" role="progressbar" aria-valuenow={done} aria-valuemax={total} aria-label="Done">
      <motion.div
        className="h-full origin-left rounded-full bg-accent"
        initial={false}
        animate={{ scaleX: total ? done / total : 0 }}
        transition={{ duration: 0.35, ease: easeOut }}
      />
    </div>
  );
}

/** Done text: dims and strikes through gradually (the line fades in) rather than switching. */
const struck = (done: boolean) =>
  `line-through transition-[color,text-decoration-color] duration-200 ease-out ${done ? "text-fg-4 decoration-fg-6" : "text-fg decoration-transparent"}`;

/* ---------- timeline ---------- */

export function Timeline({ data }: BlockProps<TimelineData>) {
  const events = data.events ?? [];
  const [all, setAll] = useState(false);
  const shown = all ? events : events.slice(0, FOLD);
  return (
    <div className="flex flex-col gap-1 px-2 py-1">
      <ol className="flex flex-col">
        <AnimatePresence initial={false}>
          {shown.map((e, i) => {
            const item = (
              // when | dot and rail | what: dates line up in their own column so the timeline scans like a schedule
              <div className="grid grid-cols-[minmax(3.5rem,auto)_12px_minmax(0,1fr)] gap-x-3 pb-4">
                <span className="pt-[1px] text-end text-[12px] leading-5 whitespace-nowrap text-fg-4 tabular-nums">{e?.when}</span>
                <div className="relative flex justify-center pt-[6px]">
                  <span className={`relative z-10 size-2 rounded-full ring-4 ring-raised ${i === events.length - 1 ? "bg-accent" : "bg-fg-4"}`} />
                  {/* the rail runs from under this dot to the next one, across the gap between items */}
                  {i < shown.length - 1 && <span aria-hidden className="absolute top-[14px] -bottom-[22px] left-[5.5px] w-px bg-line" />}
                </div>
                <div className="flex min-w-0 flex-col gap-0.5">
                  <h3 className="text-[14px] leading-5 font-medium text-fg">{e?.title}</h3>
                  {e?.detail && <p className="text-[13px] leading-snug text-pretty text-fg-3">{inline(e.detail)}</p>}
                </div>
              </div>
            );
            return i < FOLD ? (
              <Arrive as="li" key={i}>
                {item}
              </Arrive>
            ) : (
              <motion.li key={i} {...fold} className="overflow-hidden">
                {item}
              </motion.li>
            );
          })}
        </AnimatePresence>
      </ol>
      <MoreToggle hidden={events.length - FOLD} open={all} onToggle={() => setAll((a) => !a)} />
    </div>
  );
}

export const timelineText = (d: BlockProps<TimelineData>["data"]) => (d.events ?? []).map((e) => `${e?.when}: ${e?.title}. ${e?.detail ?? ""}`).join("\n");

export function TimelineSkeleton() {
  return (
    <div className="flex flex-col gap-5 px-2 py-1">
      {[0, 1, 2, 3].map((i) => (
        <div key={i} className="flex gap-3">
          <div className="skeleton mt-[3px] size-2 shrink-0 rounded-full" />
          <div className="flex flex-1 flex-col gap-1.5">
            <Bar className="h-2.5 w-16" />
            <Bar className="h-3.5 w-2/5" />
            <Bar className="h-3 w-4/5" />
          </div>
        </div>
      ))}
    </div>
  );
}

/* ---------- checklist: tick things off; it's saved with the conversation ---------- */

export function Checklist({ data, settled, onChange }: BlockProps<ChecklistData>) {
  const items = data.items ?? [];
  const done = items.filter((i) => i?.done).length;
  const live = settled && !!onChange;
  const toggle = (i: number) => {
    if (!live) return;
    onChange!({ ...data, items: items.map((it, j) => (j === i ? { ...it, done: !it?.done } : it)) });
  };
  return (
    <div className="flex flex-col gap-3 px-2 py-1">
      <BlockHeader title={data.title} meta={items.length > 0 && <Swap value={`${done} of ${items.length} done`} />} />
      {items.length > 0 && <Progress done={done} total={items.length} />}
      <ul className="-mx-1 flex flex-col">
        {items.map((item, i) => (
          <Arrive as="li" key={i}>
            <button
              type="button"
              role="checkbox"
              aria-checked={!!item?.done}
              disabled={!live}
              onClick={() => toggle(i)}
              className={`group focus-ring flex w-full items-start gap-2.5 rounded-[10px] px-1.5 py-1.5 text-start enabled:hover:bg-white/[0.04] ${rowPress}`}
            >
              <span className="mt-px">
                <Check done={!!item?.done} />
              </span>
              <span className="flex min-w-0 flex-1 flex-wrap items-baseline justify-between gap-x-3">
                <span className={`text-[14px] leading-snug ${struck(!!item?.done)}`}>{item?.text}</span>
                {item?.note && <span className="text-[12px] text-fg-4">{item.note}</span>}
              </span>
            </button>
          </Arrive>
        ))}
      </ul>
    </div>
  );
}

export const checklistText = (d: BlockProps<ChecklistData>["data"]) =>
  [d.title, ...(d.items ?? []).map((i) => `- [${i?.done ? "x" : " "}] ${i?.text}${i?.note ? ` (${i.note})` : ""}`)].filter(Boolean).join("\n");

export function ChecklistSkeleton() {
  return (
    <div className="flex flex-col gap-3 px-2 py-1">
      <Bar className="h-3.5 w-1/3" />
      <Bar className="h-1 w-full" />
      {[0, 1, 2, 3, 4].map((i) => (
        <div key={i} className="flex items-center gap-2.5">
          <div className="skeleton size-[18px] shrink-0 rounded-full" />
          <Bar className={`h-3 ${["w-1/2", "w-2/5", "w-3/5", "w-1/3", "w-1/2"][i]}`} />
        </div>
      ))}
    </div>
  );
}

/* ---------- steps: numbered, and each can be marked done as you go ---------- */

type StepsState = StepsData & { done?: number[] };

export function Steps({ data, settled, onChange }: BlockProps<StepsState>) {
  const steps = data.steps ?? [];
  const done = new Set((data.done ?? []).filter((n): n is number => typeof n === "number"));
  const live = settled && !!onChange;
  const toggle = (i: number) => {
    if (!live) return;
    const next = new Set(done);
    if (next.has(i)) next.delete(i);
    else next.add(i);
    onChange!({ ...data, done: [...next] });
  };
  return (
    <div className="flex flex-col gap-3 px-2 py-1">
      <AnimatePresence initial={false}>
        {done.size > 0 && (
          <motion.div {...fold}>
            <div className="flex items-center gap-3">
              <div className="flex-1">
                <Progress done={done.size} total={steps.length} />
              </div>
              <Swap value={`${done.size} of ${steps.length} done`} className="shrink-0 text-[12px] text-fg-4 tabular-nums" />
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <ol className="-mx-1 flex flex-col">
        {steps.map((s, i) => {
          const isDone = done.has(i);
          return (
            <Arrive as="li" key={i} className="relative flex gap-3 rounded-[10px] px-1.5 py-2">
              {/* the rail between numbers; it brightens where two done steps meet */}
              {i < steps.length - 1 && (
                <span
                  aria-hidden
                  className={`absolute top-[36px] -bottom-[4px] left-[17.5px] w-px transition-colors duration-300 ${isDone && done.has(i + 1) ? "bg-fg-4" : "bg-line"}`}
                />
              )}
              <motion.button
                type="button"
                role="checkbox"
                aria-checked={isDone}
                aria-label={`Step ${i + 1} done`}
                disabled={!live}
                whileTap={live ? tap : undefined}
                onClick={() => toggle(i)}
                className={`focus-ring flex size-6 shrink-0 items-center justify-center rounded-full text-[12px] font-medium tabular-nums transition-colors duration-200 ease-out ${
                  isDone ? "bg-accent text-accent-fg" : "bg-control text-fg-2 enabled:hover:bg-control-hover"
                }`}
              >
                <AnimatePresence mode="popLayout" initial={false}>
                  <motion.span key={isDone ? "done" : "n"} {...iconSwap} className="flex">
                    {isDone ? <CheckIcon size={13} /> : i + 1}
                  </motion.span>
                </AnimatePresence>
              </motion.button>
              <div className="flex min-w-0 flex-col gap-0.5 pt-0.5">
                <h3 className={`text-[14px] font-medium transition-colors duration-200 ease-out ${isDone ? "text-fg-4" : "text-fg"}`}>{s?.title}</h3>
                {s?.detail && <p className="text-[13px] leading-relaxed text-pretty text-fg-3">{inline(s.detail)}</p>}
              </div>
            </Arrive>
          );
        })}
      </ol>
    </div>
  );
}

export const stepsText = (d: BlockProps<StepsData>["data"]) => (d.steps ?? []).map((s, i) => `${i + 1}. ${s?.title}\n   ${s?.detail ?? ""}`).join("\n");

export function StepsSkeleton() {
  return (
    <div className="flex flex-col gap-4 px-2 py-2">
      {[0, 1, 2, 3].map((i) => (
        <div key={i} className="flex gap-3">
          <div className="skeleton size-6 shrink-0 rounded-full" />
          <div className="flex flex-1 flex-col gap-1.5 pt-1">
            <Bar className="h-3.5 w-2/5" />
            <Bar className="h-3 w-4/5" />
