"use client";

import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";
import { CheckIcon, RotateIcon, XIcon } from "@/components/icons";
import type { QuizData } from "@/lib/blocks";
import { easeOut, iconSwap, press } from "@/lib/motion";
import { Action, Bar, BlockHeader, type BlockProps } from "./shared";

// One question at a time. Pick an answer and it's marked straight away (right in the accent, a wrong pick crossed
// out, the right one shown) with the reason under it; Next moves on. At the end, the score and each question to
// look back at. Number keys pick, Enter goes on. Answers are saved with the conversation.

type QuizState = QuizData & { picks?: (number | null)[] };

const slide = {
  initial: { opacity: 0, x: 16, filter: "blur(4px)" },
  animate: { opacity: 1, x: 0, filter: "blur(0px)", transition: { duration: 0.25, ease: easeOut } },
  exit: { opacity: 0, x: -16, filter: "blur(4px)", transition: { duration: 0.12, ease: easeOut } },
};

export function Quiz({ data, settled, onChange }: BlockProps<QuizState>) {
  const questions = (data.questions ?? []).filter((q) => q?.question && (q.choices?.length ?? 0) > 1);
  const picks = questions.map((_, i) => (typeof data.picks?.[i] === "number" ? (data.picks[i] as number) : null));
  // Where the reader is: picked up from saved answers once, then moved only by them (Next, Try again, a review
  // link). Deriving it from "the first unanswered question" skipped past the explanation the moment you answered.
  const [at, setAt] = useState<number | null>(null);
  const firstOpen = picks.findIndex((p) => p === null);
  const index = at ?? (firstOpen === -1 ? questions.length : firstOpen);
  const done = index >= questions.length;
  const score = picks.filter((p, i) => p !== null && p === questions[i]?.answer).length;

  const save = (next: (number | null)[]) => onChange?.({ ...data, picks: next });
  const pick = (c: number) => {
    if (!settled || picks[index] !== null) return;
    const next = [...picks];
    next[index] = c;
    setAt(index); // stay on this question to show why
    save(next);
  };
  const restart = () => {
    save(questions.map(() => null));
    setAt(0);
  };

  if (!settled) {
    return (
      <div className="flex flex-col gap-2 px-2 py-1">
        <BlockHeader title={data.title} meta={`${questions.length} questions`} />
        <QuizSkeleton bare />
      </div>
    );
  }

  const q = questions[index];
  const picked = picks[index];
  return (
    <div
      className="flex flex-col gap-3 px-2 py-1 outline-none"
      tabIndex={-1}
      onKeyDown={(e) => {
        if (done) return;
        const n = Number(e.key);
        if (n >= 1 && n <= (q?.choices?.length ?? 0)) pick(n - 1);
        if (e.key === "Enter" && picked !== null) setAt(index + 1);
      }}
    >
      <BlockHeader title={data.title} meta={done ? `${score} of ${questions.length}` : `${index + 1} of ${questions.length}`}>
        {done && <Action label="Try again" icon={<RotateIcon size={13} />} onClick={restart} />}
      </BlockHeader>
      {/* one dot per question: answered right, answered wrong, current, still to come */}
      <div className="flex gap-1" aria-hidden>
        {questions.map((qq, i) => (
          <span
            key={i}
            className={`h-1 flex-1 rounded-full transition-colors duration-200 ${
              picks[i] === null ? (i === index ? "bg-fg-4" : "bg-white/[0.08]") : picks[i] === qq?.answer ? "bg-accent" : "bg-bad/70"
            }`}
          />
        ))}
      </div>

      <AnimatePresence mode="popLayout" initial={false}>
        {done ? (
          <motion.div key="done" {...slide} className="flex flex-col gap-3">
            <p className="text-[22px] leading-tight font-medium tracking-[-0.02em] text-fg">
              {score} of {questions.length} right
              <span className="ms-2 text-[14px] font-normal text-fg-4">
                {score === questions.length ? "All of them." : score >= questions.length * 0.7 ? "Good going." : "Worth another go."}
              </span>
            </p>
            <ol className="flex flex-col gap-1">
              {questions.map((qq, i) => {
                const right = picks[i] === qq?.answer;
                return (
                  <li key={i}>
                    <button
                      type="button"
                      onClick={() => setAt(i)}
                      className="focus-ring flex w-full items-start gap-2 rounded-[8px] px-1.5 py-1 text-start text-[13px] hover:bg-white/[0.04]"
                    >
                      {right ? <CheckIcon size={14} className="mt-0.5 shrink-0 text-good" aria-label="Right" /> : <XIcon size={14} className="mt-0.5 shrink-0 text-bad" aria-label="Wrong" />}
                      <span className="text-fg-2">{qq?.question}</span>
                    </button>
                  </li>
                );
              })}
            </ol>
          </motion.div>
        ) : (
          <motion.div key={index} {...slide} className="flex flex-col gap-3">
            <p className="text-[16px] leading-snug font-medium text-pretty text-fg">{q?.question}</p>
            <ul className="flex flex-col gap-1.5">
              {(q?.choices ?? []).map((c, ci) => {
                const answered = picked !== null;
                const isRight = ci === q?.answer;
                const isPicked = ci === picked;
                const state = !answered ? "idle" : isRight ? "right" : isPicked ? "wrong" : "other";
                return (
                  <li key={ci}>
                    <motion.button
                      type="button"
                      disabled={answered}
                      onClick={() => pick(ci)}
                      className={`focus-ring flex w-full items-center gap-3 rounded-[12px] px-3 py-2.5 text-start text-[14px] transition-[background-color,box-shadow,opacity,color] duration-200 ease-out enabled:active:bg-control ${
                        state === "idle"
                          ? "bg-surface hover:bg-surface-hover"
                          : state === "right"
                            ? "bg-control text-fg shadow-[inset_0_0_0_1px_var(--line-strong)]"
                            : state === "wrong"
                              ? "bg-surface text-fg-4 line-through decoration-fg-6"
                              : "bg-surface opacity-45"
                      }`}
                    >
                      <span
                        className={`flex size-6 shrink-0 items-center justify-center rounded-[7px] text-[12px] font-medium transition-colors duration-200 ease-out ${
                          state === "right" ? "bg-accent text-accent-fg" : "bg-white/[0.06] text-fg-3"
                        }`}
                      >
                        {/* the letter turns into the verdict with the icon swap: scale and blur, no jump */}
                        <AnimatePresence mode="popLayout" initial={false}>
                          <motion.span key={state === "right" || state === "wrong" ? state : "letter"} {...iconSwap} className="flex">
                            {state === "right" ? <CheckIcon size={13} /> : state === "wrong" ? <XIcon size={13} /> : String.fromCharCode(65 + ci)}
                          </motion.span>
                        </AnimatePresence>
                      </span>
                      <span className="text-fg-2">{c}</span>
                    </motion.button>
                  </li>
                );
              })}
            </ul>
            <AnimatePresence>
              {picked !== null && (
                <motion.div
                  className="flex flex-col gap-3"
                  initial={{ opacity: 0, filter: "blur(4px)" }}
                  animate={{ opacity: 1, filter: "blur(0px)", transition: { duration: 0.22, ease: easeOut } }}
                >
                  <p className="text-[13px] leading-relaxed text-pretty text-fg-3">
                    <span className="text-fg">{picked === q?.answer ? "Right. " : "Not quite. "}</span>
                    {q?.explain}
                  </p>
                  <motion.button
                    type="button"
                    whileTap={press}
                    onClick={() => setAt(index + 1)}
                    className="focus-ring h-8 w-fit rounded-[10px] bg-accent px-3 text-[13px] font-medium text-accent-fg"
                  >
                    {index === questions.length - 1 ? "See score" : "Next"}
                  </motion.button>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export const quizText = (d: BlockProps<QuizData>["data"]) =>
  (d.questions ?? [])
    .map((q, i) => `${i + 1}. ${q?.question}\n${(q?.choices ?? []).map((c, j) => `   ${String.fromCharCode(65 + j)}) ${c}`).join("\n")}\n   Answer: ${String.fromCharCode(65 + (q?.answer ?? 0))}`)
    .join("\n\n");

export function QuizSkeleton({ bare }: { bare?: boolean }) {
  return (
    <div className={`flex flex-col gap-3 ${bare ? "" : "px-2 py-1"}`}>
      {!bare && <Bar className="h-3.5 w-1/3" />}
      <Bar className="h-1 w-full" />
      <Bar className="h-4 w-3/4" />
      {[0, 1, 2].map((i) => (
        <div key={i} className="skeleton h-11 rounded-[12px]" />
      ))}
    </div>
  );
}

"use client";

import { useState } from "react";
import { MinusIcon, PlusIcon, TimerIcon, UsersIcon } from "@/components/icons";
import type { RecipeData } from "@/lib/blocks";
import { Action, Arrive, Bar, BlockHeader, type BlockProps, CopyAction, finite, Swap } from "./shared";

// A recipe you can cook from: change the servings and every amount scales (spoons and cups in kitchen fractions,
// grams to sensible round numbers); tick ingredients off as you gather them; the method is numbered.

const FRACTIONS: [number, string][] = [
  [0.125, "⅛"],
  [0.25, "¼"],
  [1 / 3, "⅓"],
  [0.5, "½"],
  [2 / 3, "⅔"],
  [0.75, "¾"],
];
const KITCHEN = /^(cups?|tbsp|tsp|tablespoons?|teaspoons?|)$/i;

/** 1.5 cups → "1½", 333 g → "335", 0 → "to taste". */
function amount(v: number, unit: string) {
  if (!v) return "";
  if (KITCHEN.test(unit.trim())) {
    const whole = Math.floor(v);
    const rest = v - whole;
    const [frac, glyph] = FRACTIONS.reduce((best, f) => (Math.abs(f[0] - rest) < Math.abs(best[0] - rest) ? f : best), [0, ""] as [number, string]);
    if (Math.abs(frac - rest) < 0.07) return whole ? `${whole}${glyph}` : glyph || "0";
    if (rest > 0.93) return `${whole + 1}`;
    return +v.toFixed(1) + "";
  }
  if (v >= 100) return `${Math.round(v / 5) * 5}`;
  if (v >= 10) return `${Math.round(v)}`;
  return `${+v.toFixed(1)}`;
}

type RecipeState = RecipeData & { got?: number[] };

export function Recipe({ data, settled, onChange }: BlockProps<RecipeState>) {
  const base = finite(data.servings) && data.servings > 0 ? data.servings : 1;
  const [servings, setServings] = useState<number | null>(null);
  const n = servings ?? base;
  const factor = n / base;
  const got = new Set((data.got ?? []).filter((x): x is number => typeof x === "number"));
  const ingredients = (data.ingredients ?? []).filter((i) => i?.item);
  const steps = (data.steps ?? []).filter((s): s is string => !!s);

  const toggle = (i: number) => {
    if (!settled || !onChange) return;
    const next = new Set(got);
    if (next.has(i)) next.delete(i);
    else next.add(i);
    onChange({ ...data, got: [...next] });
  };

  const line = (i: (typeof ingredients)[number]) => {
    const a = amount((i?.amount ?? 0) * factor, i?.unit ?? "");
    return { qty: a ? `${a}${i?.unit ? ` ${i.unit}` : ""}` : "to taste", item: i?.item ?? "" };
  };

  return (
    <div className="flex flex-col gap-4 px-2 py-1">
      <BlockHeader title={data.title}>
        <CopyAction label="Shopping list" text={() => [`${data.title} (serves ${n})`, ...ingredients.map((i) => `- ${line(i).qty} ${line(i).item}`)].join("\n")} />
      </BlockHeader>
      <div className="flex flex-wrap items-center gap-2 text-[12px] text-fg-3">
        {data.prep && (
          <span className="flex h-7 items-center gap-1.5 rounded-[8px] bg-surface px-2">
            <TimerIcon size={13} className="text-fg-5" /> Prep {data.prep}
          </span>
        )}
        {data.cook && (
          <span className="flex h-7 items-center gap-1.5 rounded-[8px] bg-surface px-2">
            <TimerIcon size={13} className="text-fg-5" /> Cook {data.cook}
          </span>
        )}
        {/* servings: the one control that changes everything below it */}
        <span className="flex h-7 items-center gap-0.5 rounded-[8px] bg-surface ps-2 pe-0.5">
          <UsersIcon size={13} className="me-1 text-fg-5" />
          <span className="min-w-[4.5rem] text-fg-2 tabular-nums">
            Serves <Swap value={n} className="text-fg" />
          </span>
          <Action showLabel={false} label="Fewer servings" icon={<MinusIcon size={13} />} onClick={() => setServings(Math.max(1, n - 1))} />
          <Action showLabel={false} label="More servings" icon={<PlusIcon size={13} />} onClick={() => setServings(Math.min(48, n + 1))} />
        </span>
        {servings !== null && servings !== base && (
          <button type="button" onClick={() => setServings(null)} className="focus-ring rounded-[6px] px-1 text-fg-5 hover:text-fg-2">
            Reset to {base}
          </button>
        )}
      </div>

      <div className="grid gap-5 sm:grid-cols-[minmax(0,2fr)_minmax(0,3fr)]">
        <section className="flex flex-col gap-1.5">
          <h4 className="text-[12px] text-fg-4">
            Ingredients{got.size > 0 && <span className="tabular-nums"> · {got.size} of {ingredients.length} ready</span>}
          </h4>
          <ul className="-mx-1.5 flex flex-col">
            {ingredients.map((ing, i) => {
              const { qty, item } = line(ing);
              const on = got.has(i);
              return (
                <Arrive as="li" key={i}>
                  <button
                    type="button"
                    role="checkbox"
                    aria-checked={on}
                    disabled={!settled || !onChange}
                    onClick={() => toggle(i)}
                    className={`focus-ring flex w-full items-baseline gap-2.5 rounded-[8px] px-1.5 py-1 text-start text-[13px] transition-[background-color,opacity] duration-200 ease-out enabled:hover:bg-white/[0.04] enabled:active:bg-white/[0.07] ${on ? "opacity-45" : ""}`}
                  >
                    {/* the amount blur-swaps when the servings change; the strike fades in when it's ticked */}
                    <Swap
                      value={qty}
                      className={`w-16 shrink-0 text-end text-fg tabular-nums line-through transition-[text-decoration-color] duration-200 ${on ? "decoration-fg-5" : "decoration-transparent"}`}
                    />
                    <span className={`text-fg-2 line-through transition-[text-decoration-color] duration-200 ${on ? "decoration-fg-6" : "decoration-transparent"}`}>{item}</span>
                  </button>
                </Arrive>
              );
            })}
          </ul>
        </section>
        <section className="flex flex-col gap-1.5">
          <h4 className="text-[12px] text-fg-4">Method</h4>
          <ol className="flex flex-col gap-2.5">
            {steps.map((s, i) => (
              <Arrive as="li" key={i} className="flex gap-2.5 text-[14px] leading-relaxed text-fg-2">
                <span className="w-4 shrink-0 text-end font-medium text-fg tabular-nums">{i + 1}</span>
                <span className="text-pretty">{s}</span>
              </Arrive>
            ))}
          </ol>
        </section>
      </div>
    </div>
  );
}

export const recipeText = (d: BlockProps<RecipeData>["data"]) =>
  [
    `${d.title} (serves ${d.servings})`,
    ...(d.ingredients ?? []).map((i) => `- ${i?.amount ? `${i.amount} ${i.unit ?? ""} ` : ""}${i?.item}`),
    "",
    ...(d.steps ?? []).map((s, i) => `${i + 1}. ${s}`),
  ].join("\n");

export function RecipeSkeleton() {
  return (
    <div className="flex flex-col gap-4 px-2 py-1">
      <Bar className="h-3.5 w-1/3" />
      <div className="flex gap-2">
        <Bar className="h-7 w-24" />
        <Bar className="h-7 w-24" />
        <Bar className="h-7 w-32" />
      </div>
      <div className="grid gap-5 sm:grid-cols-[2fr_3fr]">
        <div className="flex flex-col gap-2.5">
          {[0, 1, 2, 3, 4].map((i) => (
            <Bar key={i} className="h-3 w-4/5" />
          ))}
        </div>
        <div className="flex flex-col gap-2.5">
          {[0, 1, 2].map((i) => (
            <Bar key={i} className="h-3 w-full" />
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { createContext, useContext, useEffect, useRef, useState, useSyncExternalStore, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { CheckIcon, ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon, CopyIcon, XIcon } from "@/components/icons";
import type { Streaming } from "@/lib/blocks";
import { easeOut, glide, iconSwap, press } from "@/lib/motion";
import type { Artifact } from "@/lib/types";

/** The conversation's artifacts, so a block can show an image Snap pulled back by id. */
export const ArtifactsContext = createContext<Record<string, Artifact>>({});
export const useArtifact = (id?: string) => {
  const all = useContext(ArtifactsContext);
  return id ? all[id] : undefined;
};

/** A piece of a block arriving while the writer streams: out of a small blur, no movement. */
export function Arrive({
  children,
  className,
  as = "div",
  reorder,
}: {
  children: ReactNode;
  className?: string;
  as?: "div" | "li" | "tr";
  /** Glide to a new place when the list is re-ordered (sorting), instead of jumping there. */
  reorder?: boolean;
}) {
  const Tag = motion[as];
  return (
    <Tag
      className={className}
      layout={reorder ? "position" : undefined}
      initial={{ opacity: 0, filter: "blur(4px)" }}
      animate={{ opacity: 1, filter: "blur(0px)" }}
      transition={{ duration: 0.3, ease: easeOut, layout: glide }}
    >
      {children}
    </Tag>
  );
}

/** An artifact image at its own aspect, or the surface in its place until it exists. */
export function ArtifactImage({ id, className = "" }: { id?: string; className?: string }) {
  const a = useArtifact(id);
  if (!a?.src) return <div className={`aspect-[40/21] bg-surface ${className}`} />;
  return (
    // eslint-disable-next-line @next/next/no-img-element -- data URLs and tiny local stills, nothing for next/image to do
    <img
      src={a.src}
      alt={a.caption ?? a.name}
      // a hairline of light round every image, so a bright picture doesn't bleed into the dark card
      className={`aspect-[40/21] w-full bg-surface object-cover outline-1 -outline-offset-1 outline-white/10 ${className}`}
    />
  );
}

/** Placeholder bars in a block's own shape. */
export const Bar = ({ className }: { className: string }) => <div className={`skeleton rounded-[6px] ${className}`} />;

/** A box's width as it lays out, for drawings that size themselves to their column. 0 until measured. */
export function useWidth<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [width, setWidth] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => setWidth(Math.round(entry.contentRect.width)));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, width] as const;
}

/** Chart series colours, in their fixed order. */
export const SERIES = ["var(--series-1)", "var(--series-2)", "var(--series-3)", "var(--series-4)", "var(--series-5)"];

/** What a block can do in the conversation: Options sends the answer the user taps. */
export const ChatActionsContext = createContext<{ send: (text: string) => void; busy: boolean; compose: (text: string) => void }>({
  send: () => {},
  busy: false,
  compose: () => {},
});

/** Numbers that have fully arrived: streaming JSON can leave a value half-written. */
export const finite = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);

/* ---------- what every block view receives ---------- */

export type BlockProps<T> = {
  data: Streaming<T>;
  /** Finished streaming: interactions that need the whole thing (sorting, quizzes) can start. */
  settled: boolean;
  /** What the user sent next, for blocks that ask something (Options). */
  answer?: string;
  /** Saves a change the user made (a ticked item) back into the conversation. */
  onChange?: (data: unknown) => void;
};

/* ---------- small controls, one look across every block ---------- */

/** A quiet 28px action inside a block: icon, optional label, the soft wash on hover. */
export function Action({
  icon,
  label,
  onClick,
  href,
  pressed,
  showLabel = true,
}: {
  icon: ReactNode;
  label: string;
  onClick?: () => void;
  href?: string;
  pressed?: boolean;
  showLabel?: boolean;
}) {
  const className = `focus-ring flex h-7 shrink-0 items-center gap-1.5 rounded-[8px] text-[12px] transition-colors ${
    !showLabel ? "w-7 justify-center" : icon ? "ps-1.5 pe-2" : "px-2"
  } ${pressed ? "bg-control text-fg" : "text-fg-4 hover:bg-white/[0.06] hover:text-fg"}`;
  if (href) {
    return (
      <motion.a href={href} target="_blank" rel="noreferrer" whileTap={press} className={className} aria-label={showLabel ? undefined : label}>
        {icon}
        {showLabel && label}
      </motion.a>
    );
  }
  return (
    <motion.button type="button" whileTap={press} onClick={onClick} aria-pressed={pressed} aria-label={showLabel ? undefined : label} className={className}>
      {icon}
      {showLabel && label}
    </motion.button>
  );
}

/** Copies text; the icon blur-swaps to a check for a moment. */
export function CopyAction({ text, label = "Copy", showLabel = true }: { text: () => string; label?: string; showLabel?: boolean }) {
  const [done, setDone] = useState(false);
  return (
    <Action
      label={done ? "Copied" : label}
      showLabel={showLabel}
      onClick={async () => {
        await navigator.clipboard.writeText(text()).catch(() => {});
        setDone(true);
        setTimeout(() => setDone(false), 1400);
      }}
      icon={
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span key={done ? "done" : "copy"} {...iconSwap} className="flex">
            {done ? <CheckIcon size={14} /> : <CopyIcon size={14} />}
          </motion.span>
        </AnimatePresence>
      }
    />
  );
}

/** Where a block's own tools go: the card's top bar, beside Copy, so every card keeps them in one place. */
export const ToolsSlot = createContext<HTMLElement | null>(null);

/** A view's tools (Table view, Add to calendar, Collapse all...), drawn into the card's top bar. */
export function Tools({ children }: { children: ReactNode }) {
  const slot = useContext(ToolsSlot);
  return slot ? createPortal(children, slot) : <div className="-me-1 flex items-center justify-end gap-0.5">{children}</div>;
}

/** A block's own title row in its body; any actions passed in go up to the card's top bar. */
export function BlockHeader({ title, meta, children }: { title?: ReactNode; meta?: ReactNode; children?: ReactNode }) {
  return (
    <>
      {(title || meta) && (
        <div className="flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-0.5">
          {title && <h3 className="text-[15px] leading-snug font-medium tracking-[-0.01em] text-fg">{title}</h3>}
          {meta && <span className="text-[12px] text-fg-4 tabular-nums">{meta}</span>}
        </div>
      )}
      {children && <Tools>{children}</Tools>}
    </>
  );
}

/** "Show 6 more" under a long list, and "Show less" to fold it back. */
export function MoreToggle({ hidden, open, onToggle, noun = "" }: { hidden: number; open: boolean; onToggle: () => void; noun?: string }) {
  if (hidden <= 0) return null;
  return (
    <motion.button
      type="button"
      whileTap={press}
      onClick={onToggle}
      className="focus-ring flex h-7 w-fit items-center gap-1 rounded-[8px] ps-2 pe-1.5 text-[12px] text-fg-4 hover:bg-white/[0.06] hover:text-fg"
    >
      {open ? "Show less" : `Show ${hidden} more${noun ? ` ${noun}` : ""}`}
      <ChevronDownIcon size={14} className={`transition-transform duration-200 ease-out ${open ? "rotate-180" : ""}`} />
    </motion.button>
  );
}

/** Saves text as a file; the object URL outlives the click so the download isn't cancelled. */
export function saveFile(name: string, type: string, content: string) {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/** Today as YYYY-MM-DD in the reader's time zone; "" on the server so nothing mismatches on hydration. */
const subscribeDay = (cb: () => void) => {
  const t = setInterval(cb, 60_000);
  return () => clearInterval(t);
};
const localDay = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
};
export const useToday = () => useSyncExternalStore(subscribeDay, localDay, () => "");

/* ---------- the image viewer ---------- */

/**
 * Full-size images over a dark wash, centred (a modal, so it scales from the centre): arrows and ←/→ move,
 * Escape, the wash or × closes, and focus returns to what opened it.
 */
export function Lightbox({ ids, index, onIndex, onClose }: { ids: string[]; index: number | null; onIndex: (i: number) => void; onClose: () => void }) {
  const all = useContext(ArtifactsContext);
  const open = index !== null;
  useEffect(() => {
    if (!open) return;
    const back = document.activeElement as HTMLElement | null;
    const key = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowRight") onIndex(((index ?? 0) + 1) % ids.length);
      if (e.key === "ArrowLeft") onIndex(((index ?? 0) - 1 + ids.length) % ids.length);
    };
    document.addEventListener("keydown", key);
    return () => {
      document.removeEventListener("keydown", key);
      back?.focus();
    };
  }, [open, index, ids.length, onClose, onIndex]);

  if (typeof document === "undefined") return null;
  const a = open ? all[ids[index]] : undefined;
  return createPortal(
    <AnimatePresence>
      {open && a?.src && (
        <motion.div
          role="dialog"
          aria-modal
          aria-label={a.name}
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 p-4 sm:p-10"
          onClick={onClose}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1, transition: { duration: 0.2, ease: easeOut } }}
          exit={{ opacity: 0, transition: { duration: 0.15, ease: easeOut } }}
        >
          <motion.figure
            key={a.id}
            className="flex max-h-full max-w-5xl flex-col items-center gap-3"
            onClick={(e) => e.stopPropagation()}
            initial={{ opacity: 0, scale: 0.97, filter: "blur(4px)" }}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)", transition: { duration: 0.22, ease: easeOut } }}
          >
            {/* eslint-disable-next-line @next/next/no-img-element -- data URLs and local stills */}
            <img src={a.src} alt={a.caption ?? a.name} className="max-h-[78vh] w-auto rounded-[16px] object-contain" />
            <figcaption className="max-w-[60ch] text-center text-[13px] text-fg-3">{a.caption ?? a.name}</figcaption>
          </motion.figure>
          <div className="absolute top-4 right-4 flex gap-1" onClick={(e) => e.stopPropagation()}>
            {ids.length > 1 && (
              <>
                <Action showLabel={false} label="Previous image" icon={<ChevronLeftIcon size={16} />} onClick={() => onIndex((index - 1 + ids.length) % ids.length)} />
                <span className="flex h-7 items-center px-1 text-[12px] text-fg-4 tabular-nums">
                  {index + 1} / {ids.length}
                </span>
                <Action showLabel={false} label="Next image" icon={<ChevronRightIcon size={16} />} onClick={() => onIndex((index + 1) % ids.length)} />
              </>
            )}
            <Action showLabel={false} label="Close" icon={<XIcon size={16} />} onClick={onClose} />
          </div>
        </motion.div>
      )}
    </AnimatePresence>,
    document.body,
  );
}

/**
 * A value that changes in place (a scaled amount, a count, a total): the old one blurs out as the new one blurs in,
 * in the same spot. No movement, so a column of numbers doesn't jitter.
 */
export function Swap({ value, className }: { value: ReactNode; className?: string }) {
  const key = typeof value === "string" || typeof value === "number" ? String(value) : undefined;
  return (
    // inline, so the value reads and copies as part of its sentence; the outgoing one is popped out of the flow
    <span className={`relative inline-block ${className ?? ""}`}>
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={key}
          className="inline-block"
          initial={{ opacity: 0, filter: "blur(3px)" }}
          animate={{ opacity: 1, filter: "blur(0px)", transition: { duration: 0.18, ease: easeOut } }}
          exit={{ opacity: 0, filter: "blur(3px)", transition: { duration: 0.1, ease: easeOut } }}
        >
          {value}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

