import { SourceDialog, type Incoming, type SourceKind } from "./sources/source-dialog";
import { CONTEXT_BUDGET, ContextMeter } from "./context-meter";
import { DropZone } from "./drop-zone";
import { AssistantMessage, UserMessage } from "./message";
import { SIDEBAR_WIDTH, Sidebar, useWide } from "./sidebar";
import { DocPanel, DocViewerContext, panelDefault } from "./viewer/doc-panel";

const fade = {
  initial: { opacity: 0, filter: "blur(4px)" },
  animate: { opacity: 1, filter: "blur(0px)", transition: { duration: 0.25, ease: easeOut } },
  exit: { opacity: 0, filter: "blur(4px)", transition: { duration: 0.12, ease: easeOut } },
};

const nearBottom = () => window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 160;

export function Chat() {
  const chat = useChat();
  const { conv, loaded, busy } = chat;
  const [attached, setAttached] = useState<string[]>([]);
  const [source, setSource] = useState<SourceKind | null>(null);
  // closing it leaves you in the message box: with a repository added, the next thing is the question
  const closeSource = useCallback(() => {
    setSource(null);
    requestAnimationFrame(() => document.getElementById("composer")?.focus());
  }, []);
  const [notice, setNotice] = useState<string | null>(null);
  const [draft, setDraft] = useState("");
  const [flash, setFlash] = useState<string | null>(null);
  // A new session (demo, new chat, restore) renders in place; only messages added after that rise in.
  const [session, setSession] = useState(0);
  const pinned = useRef(true);
  // The sidebar stays open beside the chat on a wide screen and is a closed drawer on a phone.
  const wide = useWide();
  const [docked, setDocked] = useState(true);
  const [drawer, setDrawer] = useState(false);
  const sidebarOpen = wide ? docked : drawer;
  const closeSidebar = useCallback(() => (wide ? setDocked(false) : setDrawer(false)), [wide]);
  const openSidebar = () => (wide ? setDocked(true) : setDrawer(true));

  // The document panel on the right: which artifact is open, how wide the reader has made it, and who opened it
  // (focus goes back there on close).
  const [docId, setDocId] = useState<string | null>(null);
  const [docWidth, setDocWidth] = useState(0);
  const [resizing, setResizing] = useState(false);
  const opener = useRef<HTMLElement | null>(null);
  const openDoc = useCallback((id: string) => {
    opener.current = document.activeElement as HTMLElement | null;
    setDocWidth((w) => w || panelDefault());
    setDocId(id);
  }, []);
  const closeDoc = useCallback(() => {
    setDocId(null);
    requestAnimationFrame(() => opener.current?.focus({ preventScroll: true }));
  }, []);

  const replace = (next: typeof conv) => {
    setDocId(null);
    chat.replace(next);
    setAttached([]);
    setSession((s) => s + 1);
    setDrawer(false);
    pinned.current = true;
  };
  const newChat = () => replace(empty());
  const openDemo = async () => replace(await demoConversation());
  const openCodebase = async () => replace(await codebaseConversation());
  const openSaved = async (id: string) => {
    if (id === conv.id) return setDrawer(false);
    setDocId(null);
    await chat.open(id);
    setAttached([]);
    setSession((s) => s + 1);
    setDrawer(false);
    pinned.current = true;
  };

  useEffect(() => {
    const onScroll = () => {
      pinned.current = nearBottom();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Follow the reply as it grows, unless the reader has scrolled up.
  const last = conv.messages[conv.messages.length - 1];
  useLayoutEffect(() => {
    if (pinned.current) window.scrollTo({ top: document.documentElement.scrollHeight });
  }, [session, conv.messages.length, last?.text, last?.data, last?.turn?.status]);

  useEffect(() => {
    if (!notice) return;
    const t = setTimeout(() => setNotice(null), 5000);
    return () => clearTimeout(t);
  }, [notice]);

  const { attach, artifactId } = chat;
  const onFiles = useCallback(
    async (files: File[]) => {
      const first = Number(artifactId().slice(1));
      const results = await Promise.all(files.map((f, i) => readFile(f, `a${first + i}`)));
      for (const r of results) {
        if ("error" in r) setNotice(r.error);
        else {
          setAttached((a) => [...a, r.id]);
          attach(r, "");
        }
      }
    },
    [attach, artifactId],
  );

  /** A repository's files, or a web page, arriving from the dialog: documents, waiting in the composer. */
  const addSource = useCallback(
    (incoming: Incoming) => {
      const first = Number(artifactId().slice(1));
      const made = incoming.files.map((f, i): Artifact => {
        const ext = f.name.split(".").pop()?.toLowerCase() ?? "";
        const mediaType = incoming.source.kind === "page" ? "text/markdown" : (TEXT_TYPES[ext] ?? "text/plain");
        return { id: `a${first + i}`, kind: "doc", name: f.name, mediaType, text: f.text, bytes: f.text.length, source: incoming.source };
      });
      made.forEach((a) => attach(a, ""));
      setAttached((a) => [...a, ...made.map((m) => m.id)]);
    },
    [attach, artifactId],
  );

  /** Puts text in the composer and the cursor after it (Options' "Something else…"). */
  const compose = (text: string) => {
    setDraft(text);
    requestAnimationFrame(() => {
      const field = document.getElementById("composer") as HTMLTextAreaElement | null;
      field?.focus();
      field?.setSelectionRange(text.length, text.length);
    });
  };

  const send = (text: string) => {
    pinned.current = true;
    chat.send(text, attached);
    setAttached([]);
  };

  const recall = (id: string) => {
    document.getElementById(`msg-${id}`)?.scrollIntoView({ behavior: "smooth", block: "center" });
    setFlash(id);
    setTimeout(() => setFlash((f) => (f === id ? null : f)), 1800);
  };

  const asked = new Set(conv.messages.map((m) => m.text));
  const isDemo = conv.messages.some((m) => m.seeded);
  const suggestions = (conv.suggestions ?? (isDemo ? demoSuggestions : [])).filter((s) => !asked.has(s));
  const lastSeeded = conv.messages.findLastIndex((m) => m.seeded);
  const indexOf = new Map(conv.messages.map((m, i) => [m.id, i]));
  const isEmpty = loaded && !conv.messages.length;

  const composer = (
    // One composer that glides from the middle of an empty chat down to its place under the thread.
    <motion.div layoutId="composer" transition={{ duration: 0.45, ease: easeOut }} className="relative flex flex-col gap-2">
      <AnimatePresence>
        {notice && (
          <motion.p {...fade} role="status" className="px-1 text-[13px] text-fg-3">
            {notice}
          </motion.p>
        )}
      </AnimatePresence>
      <Composer
        text={draft}
        onText={setDraft}
        attachments={attached.map((id) => conv.artifacts[id]).filter(Boolean)}
        busy={busy}
        suggestions={busy ? [] : suggestions}
        onSend={send}
        onFiles={onFiles}
        onSource={setSource}
        onRemove={(id) => {
          setAttached((a) => a.filter((x) => x !== id));
          chat.detach(id);
        }}
      />
    </motion.div>
  );

  return (
    <ArtifactsContext value={conv.artifacts}>
      <ChatActionsContext value={{ send, busy, compose }}>
      <DocViewerContext value={{ open: openDoc, openId: docId }}>
      <Sidebar
        open={sidebarOpen}
        onClose={closeSidebar}
        list={chat.list}
        activeId={conv.id}
        onSelect={openSaved}
        onNew={newChat}
        onDemo={openDemo}
        onCodebase={openCodebase}
        onDelete={chat.remove}
        instant={!loaded}
      />
      {/* With the sidebar closed, its controls wait at the window's edge, where it folds away to. */}
      <AnimatePresence initial={false}>
        {loaded && !sidebarOpen && (
          <motion.div {...fade} className="fixed top-5 left-4 z-40 flex h-9 items-center gap-0.5 rounded-[12px] bg-control p-[3px]">
            <motion.button
              type="button"
              whileTap={press}
              onClick={openSidebar}
              aria-label="Open the sidebar"
              className="focus-ring flex size-[30px] items-center justify-center rounded-[9px] text-fg-2 hover:bg-white/[0.08] hover:text-fg"
            >
              <SidebarIcon size={17} />
            </motion.button>
            <motion.button
              type="button"
              whileTap={press}
              onClick={newChat}
              aria-label="New chat"
              className="focus-ring flex size-[30px] items-center justify-center rounded-[9px] text-fg-2 hover:bg-white/[0.08] hover:text-fg"
            >
              <PlusIcon size={16} />
            </motion.button>
          </motion.div>
        )}
      </AnimatePresence>
      <div
        className={`flex min-h-dvh flex-col ${loaded && !resizing ? "transition-[padding] duration-300 ease-out" : ""}`}
        style={{ paddingInlineStart: wide && docked ? SIDEBAR_WIDTH : 0, paddingInlineEnd: wide && docId ? docWidth : 0 }}
      >
        {/* Sticky so the sidebar and the meter stay in reach in a long chat; a solid fade, never a backdrop blur. */}
        <header
          className={`sticky top-0 z-30 mx-auto flex h-[76px] w-full max-w-[760px] items-center justify-between gap-3 bg-linear-to-b from-background via-background via-70% to-background/0 px-5 ${
            sidebarOpen ? "" : "max-[1100px]:ps-[104px]"
          }`}
        >
          <div className="flex min-w-0 items-center gap-3">
            <AnimatePresence mode="popLayout" initial={false}>
              {conv.messages.length > 0 && (
                <motion.h1 key={conv.id} {...fade} className="truncate text-[15px] text-fg">
                  {conv.title}
                </motion.h1>
              )}
            </AnimatePresence>
          </div>
          <AnimatePresence initial={false}>
            {conv.messages.length > 0 && (
              <motion.div {...fade} className="shrink-0">
                <ContextMeter conv={conv} tokens={chat.tokens} measured={chat.measured} />
              </motion.div>
            )}
          </AnimatePresence>
        </header>

        {isEmpty ? (
          <main className="mx-auto flex w-full max-w-[680px] flex-1 flex-col justify-center gap-6 px-5 pb-[12vh]">
            <motion.div {...riseIn()} className="flex flex-col items-center gap-1.5 text-center">
              <h1 className="text-[22px] font-medium tracking-[-0.02em] text-fg">Ask anything.</h1>
              <p className="text-[14px] text-pretty text-fg-4">Snap keeps all of it in context and picks how each answer looks.</p>
            </motion.div>
            {composer}
            <motion.div {...riseIn(0.08)} className="flex justify-center">
              <motion.button
                type="button"
                whileTap={press}
                onClick={openDemo}
                className="focus-ring flex h-8 items-center gap-1.5 rounded-[10px] px-2.5 text-[13px] text-fg-4 hover:bg-white/[0.05] hover:text-fg"
              >
                <SparkleIcon size={14} />
                Try the demo conversation
              </motion.button>
            </motion.div>
          </main>
        ) : (
          <>
            <main className="mx-auto flex w-full max-w-[760px] flex-1 flex-col px-5">
              {/* Mounted once storage has answered, so a restored conversation is simply there. */}
              {loaded && (
                <ol key={session} className="flex flex-col gap-7 pt-2 pb-6">
                  <AnimatePresence initial={false}>
                    {conv.messages.map((m, i) => (
                      <motion.li
                        key={m.id}
                        id={`msg-${m.id}`}
                        {...riseIn()}
                        // Each message is its own stacking context (its blur), so one with an open popover is lifted above the rest.
                        className={`group/msg relative -mx-3 scroll-mt-24 rounded-[20px] px-3 py-1.5 transition-colors duration-700 has-[[aria-expanded=true]]:z-40 ${flash === m.id ? "bg-white/[0.05]" : ""}`}
                      >
                        {m.role === "user" ? (
                          <UserMessage message={m} artifacts={conv.artifacts} />
                        ) : (
                          <AssistantMessage
                            message={m}
                            recallNumber={m.turn?.decision?.recall ? (indexOf.get(m.turn.decision.recall) ?? -2) + 1 : undefined}
                            onRecall={recall}
                            onRetry={chat.retry}
                            onData={chat.setData}
                            busy={busy}
                            answer={conv.messages[i + 1]?.role === "user" ? conv.messages[i + 1].text : undefined}
                          />
                        )}
                        {i === lastSeeded && (
                          <p className="mt-7 flex items-center gap-3 text-[12px] text-fg-5">
                            <span className="h-px flex-1 bg-line" />
                            Demo history above, written by hand. Snap takes it from here.
                            <span className="h-px flex-1 bg-line" />
                          </p>
                        )}
                      </motion.li>
                    ))}
                  </AnimatePresence>
                </ol>
              )}
            </main>
            {loaded && (
              <div className="sticky bottom-0 z-30 mx-auto w-full max-w-[760px] px-5 pb-4">
                <div aria-hidden className="pointer-events-none absolute inset-x-0 -top-8 bottom-0 bg-linear-to-b from-background/0 via-background via-35% to-background" />
                {composer}
              </div>
            )}
          </>
        )}
        <DropZone onFiles={onFiles} />
      </div>
      <DocPanel
        artifact={docId ? (conv.artifacts[docId] ?? null) : null}
        wide={wide}
        width={docWidth}
        onWidth={setDocWidth}
        onClose={closeDoc}
        onResizing={setResizing}
      />
      </DocViewerContext>
      </ChatActionsContext>
      <SourceDialog
        open={source}
        onClose={closeSource}
        onAdd={addSource}
        // what's free: Snap's context, less this chat, less what's already waiting in the composer
        freeTokens={CONTEXT_BUDGET - chat.tokens - tokensOf(attached.reduce((n, id) => n + (conv.artifacts[id]?.text?.length ?? 0), 0)) - 6000}
        freeFiles={MAX_FILES - Object.keys(conv.artifacts).length}
      />
    </ArtifactsContext>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { useContext, useRef, type KeyboardEvent } from "react";
import { BranchIcon, GlobeIcon, NoteIcon, PaperclipIcon, ReturnIcon, XIcon } from "@/components/icons";
import { ACCEPT } from "@/lib/files";
import { easeOut, iconSwap, press, rowPress } from "@/lib/motion";
import { tokensOf } from "@/lib/sources";
import type { Artifact } from "@/lib/types";
import { Popover } from "./popover";
import type { SourceKind } from "./sources/source-dialog";
import { DocViewerContext } from "./viewer/doc-panel";

const KINDS: Record<string, string> = {
  ui_screenshot: "Screenshot",
  chart: "Chart",
  photo: "Photo",
  illustration: "Illustration",
  document: "Page",
  diagram: "Diagram",
  other: "Image",
};

const chip = {
  initial: { opacity: 0, scale: 0.96, filter: "blur(4px)" },
  animate: { opacity: 1, scale: 1, filter: "blur(0px)", transition: { duration: 0.22, ease: easeOut } },
  exit: { opacity: 0, scale: 0.96, filter: "blur(4px)", transition: { duration: 0.12, ease: easeOut } },
};

function Attachment({ artifact, onRemove }: { artifact: Artifact; onRemove: () => void }) {
  const t = artifact.tags;
  const viewer = useContext(DocViewerContext);
  return (
    <motion.li layout="position" {...chip} className="flex h-12 items-center gap-2 rounded-[12px] bg-surface p-1 pe-1.5">
      {artifact.kind === "image" ? (
        // eslint-disable-next-line @next/next/no-img-element -- a local data URL
        <img src={artifact.src} alt="" className="size-10 rounded-[8px] object-cover" />
      ) : (
        // a document can be checked in the panel before it's sent
        <button
          type="button"
          onClick={() => viewer.open(artifact.id)}
          aria-label={`Open ${artifact.name}`}
          className="focus-ring flex size-10 items-center justify-center rounded-[8px] bg-raised text-fg-4 transition-colors hover:text-fg"
        >
          <NoteIcon size={18} />
        </button>
      )}
      <div className="flex min-w-0 flex-col">
        <span className="max-w-[9rem] truncate text-[12px] text-fg">{artifact.name}</span>
        <span className="relative h-4 text-[11px] text-fg-4 tabular-nums">
          <AnimatePresence mode="popLayout" initial={false}>
            {artifact.kind === "doc" ? (
              <motion.span key="doc" className="block">
                {/* a PDF's text isn't read until it's sent, so it shows its size, never a guessed token count */}
                {artifact.text != null ? `${short(Math.max(1, Math.round(artifact.text.length / 4)))} tokens` : `PDF · ${artifact.bytes >= 1048576 ? `${(artifact.bytes / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(artifact.bytes / 1024))} KB`}`}
              </motion.span>
            ) : t ? (
              <motion.span key="tags" {...chip} className="block whitespace-nowrap">
                Snap: {KINDS[t.kind] ?? "Image"}, {t.dark > 0.5 ? "dark" : "light"}
                {t.hasText > 0.5 ? ", text" : ""} · {t.ms}ms
              </motion.span>
            ) : (
              <motion.span key="looking" {...chip} className="block">
                Snap is looking
              </motion.span>
            )}
          </AnimatePresence>
        </span>
      </div>
      <motion.button
        type="button"
        onClick={onRemove}
        whileTap={press}
        aria-label={`Remove ${artifact.name}`}
        className="focus-ring flex size-6 shrink-0 items-center justify-center rounded-[8px] text-fg-4 hover:bg-white/[0.08] hover:text-fg"
      >
        <XIcon size={14} />
      </motion.button>
    </motion.li>
  );
}

const short = (n: number) => (n >= 1000 ? `${(n / 1000).toFixed(n >= 100_000 ? 0 : 1)}k` : `${n}`);

/** A whole repository (or anything else that arrived as many files) as one chip: what it is, how much it is. */
function Bundle({ artifacts, onRemove }: { artifacts: Artifact[]; onRemove: () => void }) {
  const source = artifacts[0].source!;
  const tokens = tokensOf(artifacts.reduce((n, a) => n + (a.text?.length ?? 0), 0));
  return (
    <motion.li layout="position" {...chip} className="flex h-12 items-center gap-2 rounded-[12px] bg-surface p-1 pe-1.5">
      <span className="flex size-10 items-center justify-center rounded-[8px] bg-raised text-fg-4">{source.kind === "github" ? <BranchIcon size={18} /> : <GlobeIcon size={18} />}</span>
      <div className="flex min-w-0 flex-col">
        <span className="max-w-[12rem] truncate text-[12px] text-fg">{source.label}</span>
        <span className="h-4 text-[11px] whitespace-nowrap text-fg-4 tabular-nums">
          {artifacts.length} files · {short(tokens)} tokens
        </span>
      </div>
      <motion.button
        type="button"
        onClick={onRemove}
        whileTap={press}
        aria-label={`Remove ${source.label}`}
        className="focus-ring flex size-6 shrink-0 items-center justify-center rounded-[8px] text-fg-4 hover:bg-white/[0.08] hover:text-fg"
      >
        <XIcon size={14} />
      </motion.button>
    </motion.li>
  );
}

const MENU = "focus-ring flex h-9 w-full items-center gap-2.5 rounded-[10px] px-2 text-start text-[13px] text-fg-2 hover:bg-white/[0.06] hover:text-fg";

export function Composer({
  attachments,
  busy,
  suggestions,
  onSend,
  onFiles,
  onSource,
  onRemove,
  text,
  onText,
}: {
  /** Open the dialog that brings in a repository or a web page. */
  onSource: (kind: SourceKind) => void;
  /** The draft lives with the chat, so it survives the composer moving and other parts can fill it in. */
  text: string;
  onText: (text: string) => void;
  attachments: Artifact[];
  busy: boolean;
  suggestions: string[];
  onSend: (text: string) => void;
  onFiles: (files: File[]) => void;
  onRemove: (id: string) => void;
}) {
  const field = useRef<HTMLTextAreaElement>(null);
  const picker = useRef<HTMLInputElement>(null);
  const canSend = !busy && (text.trim().length > 0 || attachments.length > 0);
  // files that came in together (a repository) show as one chip
  const bundles = new Map<string, Artifact[]>();
  for (const a of attachments) if (a.source) bundles.set(a.source.label, [...(bundles.get(a.source.label) ?? []), a]);
  for (const [label, list] of bundles) if (list.length < 2) bundles.delete(label);
  const loose = attachments.filter((a) => !a.source || !bundles.has(a.source.label));

  const submit = (value = text) => {
    if (busy || (!value.trim() && !attachments.length)) return;
    onSend(value.trim());
    onText("");
    field.current?.focus();
  };

  const onKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      submit();
    }
  };

  return (
    <div className="flex flex-col gap-2.5">
      <AnimatePresence initial={false}>
        {suggestions.length > 0 && !text && (
          <motion.ul {...chip} className="no-scrollbar -mx-5 flex gap-1.5 overflow-x-auto px-5" aria-label="Try asking">
            {suggestions.map((s) => (
              <li key={s}>
                <motion.button
                  type="button"
                  whileTap={press}
                  disabled={busy}
                  onClick={() => submit(s)}
                  className="focus-ring h-8 shrink-0 rounded-[10px] bg-raised px-3 text-[13px] whitespace-nowrap text-fg-2 shadow-faint transition-colors hover:bg-white/[0.06] hover:text-fg disabled:text-fg-5"
                >
                  {s}
                </motion.button>
              </li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>

      <div className="field-focus flex flex-col gap-2 rounded-[20px] bg-raised p-2 transition-shadow duration-200">
        <AnimatePresence initial={false}>
          {attachments.length > 0 && (
            <motion.ul {...chip} className="flex flex-wrap gap-1.5" aria-label="Attached">
              <AnimatePresence initial={false} mode="popLayout">
                {[...bundles].map(([label, list]) => (
                  <Bundle key={label} artifacts={list} onRemove={() => list.forEach((a) => onRemove(a.id))} />
                ))}
                {loose.map((a) => (
                  <Attachment key={a.id} artifact={a} onRemove={() => onRemove(a.id)} />
                ))}
              </AnimatePresence>
            </motion.ul>
          )}
        </AnimatePresence>
        <label className="sr-only" htmlFor="composer">
          Message
        </label>
        <textarea
          id="composer"
          ref={field}
          value={text}
          onChange={(e) => onText(e.target.value)}
          onKeyDown={onKeyDown}
          onPaste={(e) => {
            const files = [...e.clipboardData.files];
            if (files.length) {
              e.preventDefault();
              onFiles(files);
            }
          }}
          rows={1}
          placeholder="Ask anything, or drop in images and docs"
          className="field-sizing-content max-h-48 min-h-10 resize-none bg-transparent px-2 pt-1.5 text-[16px] leading-relaxed text-fg outline-none placeholder:text-fg-5 sm:text-[15px]"
        />
        <div className="flex items-center justify-between">
          <Popover
            side="top"
            menu
            label="Attach"
            trigger={({ toggle, open: _open, ...aria }) => (
              <motion.button
                type="button"
                whileTap={press}
                onClick={toggle}
                {...aria}
                className="focus-ring flex h-8 items-center gap-1.5 rounded-[10px] px-2 text-[13px] text-fg-4 hover:bg-white/[0.06] hover:text-fg aria-expanded:bg-white/[0.06] aria-expanded:text-fg"
              >
                <PaperclipIcon size={16} />
                Attach
              </motion.button>
            )}
          >
            {(close) => (
              <ul className="flex flex-col">
                {(
                  [
                    ["Files from this device", <PaperclipIcon key="i" size={16} />, () => picker.current?.click()],
                    ["A GitHub repository", <BranchIcon key="i" size={16} />, () => onSource("github")],
                    ["A web page", <GlobeIcon key="i" size={16} />, () => onSource("page")],
                  ] as const
                ).map(([label, icon, act]) => (
                  <li key={label}>
                    <button
                      type="button"
                      onClick={() => {
                        close();
                        act();
                      }}
                      className={`${MENU} ${rowPress}`}
                    >
                      <span className="text-fg-4">{icon}</span>
                      {label}
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </Popover>
          <input
            ref={picker}
            type="file"
            multiple
            accept={ACCEPT}
            className="hidden"
            onChange={(e) => {
              onFiles([...(e.target.files ?? [])]);
              e.target.value = "";
            }}
          />
          <motion.button
            type="button"
            whileTap={canSend ? press : undefined}
            onClick={() => submit()}
            disabled={!canSend}
            aria-label="Send"
            className="focus-ring flex size-8 items-center justify-center rounded-[10px] bg-accent text-accent-fg transition-colors duration-150 disabled:bg-control disabled:text-fg-5"
          >
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span key={busy ? "busy" : "send"} {...iconSwap} className="flex">
                {busy ? <span className="size-3.5 animate-spin rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none" /> : <ReturnIcon size={16} />}
              </motion.span>
            </AnimatePresence>
          </motion.button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { motion } from "motion/react";
import { easeOut, press } from "@/lib/motion";
import type { Conversation } from "@/lib/types";
import { Popover, Row } from "./popover";

/** Snap's context window as the brief gives it. One place, so it's easy to change. */
export const CONTEXT_BUDGET = 384_000;

const short = (n: number) => (n >= 1000 ? `${n >= 100_000 ? Math.round(n / 1000) : (n / 1000).toFixed(1)}k` : `${n}`);
const secs = (ms?: number) => (ms == null ? "not yet" : ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(1)}s`);

/**
 * How much Snap is holding: its own measured input from the last turn, or an estimate before the first.
 * Nothing is trimmed, so the number only grows.
 */
export function ContextMeter({ conv, tokens, measured }: { conv: Conversation; tokens: number; measured: boolean }) {
  const fill = Math.min(1, tokens / CONTEXT_BUDGET);
  const used = new Set(conv.messages.flatMap((m) => m.artifacts ?? []));
  const held = [...used].map((id) => conv.artifacts[id]).filter(Boolean);
  const last = [...conv.messages].reverse().find((m) => m.turn?.decision);

  return (
    <Popover
      align="end"
      label="Context"
      trigger={({ toggle, ...aria }) => (
        <motion.button
          type="button"
          onClick={toggle}
          whileTap={press}
          {...aria}
          className="focus-ring flex h-9 items-center gap-2.5 rounded-[12px] bg-control px-3 text-[13px] text-fg-3 tabular-nums hover:bg-control-hover"
        >
          <span className="hidden h-1 w-10 overflow-hidden rounded-full bg-white/[0.1] sm:block">
            <motion.span
              className="block h-full origin-left rounded-full bg-accent"
              initial={false}
              animate={{ scaleX: Math.max(fill, tokens ? 0.02 : 0) }}
              transition={{ duration: 0.5, ease: easeOut }}
            />
          </span>
          <span>
            <span className="text-fg">
              {measured ? "" : "~"}
              {short(tokens)}
            </span>
            <span className="text-fg-5"> / {short(CONTEXT_BUDGET)}</span>
          </span>
        </motion.button>
      )}
    >
      <div className="flex flex-col gap-3">
        <div className="flex flex-col gap-1">
          <Row label="In context" value={`${measured ? "" : "about "}${tokens.toLocaleString("en")} tokens`} />
          <Row label="Messages" value={conv.messages.length} />
          <Row label="Images" value={held.filter((a) => a.kind === "image").length} />
          <Row label="Documents" value={held.filter((a) => a.kind === "doc").length} />
          <Row label="Last decision" value={secs(last?.turn?.decision?.ms)} />
          <Row label="Last reply written in" value={secs(last?.turn?.writeMs)} />
        </div>
        <p className="border-t border-line pt-3 text-[12px] leading-snug text-pretty text-fg-4">
          Nothing is summarized or dropped. Snap reads the whole conversation, every document and the images that matter, every turn.
          {measured ? " Measured by Snap on the last turn." : " An estimate until Snap measures the first turn."}
        </p>
      </div>
    </Popover>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { useContext } from "react";
import { BoltIcon, NoteIcon, QuoteIcon } from "@/components/icons";
import { blockIds, blocks } from "@/lib/blocks";
import { easeOut, iconSwap, press } from "@/lib/motion";
import type { Decision } from "@/lib/types";
import { ArtifactsContext } from "./blocks/shared";
import { Popover, Row } from "./popover";
import { DocViewerContext } from "./viewer/doc-panel";

const DEPTHS = ["One line", "Short", "Detailed", "Thorough"];
const pct = (n: number) => `${Math.round(n * 100)}%`;
const short = (n: number) => (n >= 1000 ? `${n >= 100_000 ? Math.round(n / 1000) : (n / 1000).toFixed(1)}k` : `${n}`);
const base = (name: string) => name.split("/").pop() ?? name;
const secs = (ms: number) => (ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(1)}s`);

/** How sure Snap was: of its one component, or of the set when the reply shows several (their shares add up). */
const sureness = (d: Decision) =>
  d.extras?.length ? Math.min(1, [d.component, ...d.extras].reduce((sum, id) => sum + (d.probabilities[id] ?? 0), 0)) : d.confidence;

const swap = {
  initial: { opacity: 0, filter: "blur(4px)" },
  animate: { opacity: 1, filter: "blur(0px)", transition: { duration: 0.25, ease: easeOut } },
  exit: { opacity: 0, filter: "blur(4px)", transition: { duration: 0.12, ease: easeOut } },
};

/**
 * What Snap decided, above the reply: the component, how sure, how fast, and the earlier message it went back
 * to. Open it for the whole distribution: every component Snap weighed, not only the winner.
 */
export function DecisionLine({
  decision,
  recallNumber,
  onRecall,
  writer,
  writeMs,
}: {
  /** The model that wrote the reply and how long it took, credited in the breakdown. */
  writer?: string;
  writeMs?: number;
  decision?: Decision;
  recallNumber?: number;
  onRecall: () => void;
}) {
  const artifacts = useContext(ArtifactsContext);
  const viewer = useContext(DocViewerContext);
  // the documents Snap picked out of everything shared: the ones the writer was given
  const docs = (decision?.artifacts ?? []).map((id) => artifacts[id]).filter((a) => a?.kind === "doc");
  return (
    <div className="relative z-20 flex min-h-6 flex-wrap items-center gap-x-2 gap-y-1">
      <AnimatePresence mode="popLayout" initial={false}>
        {decision ? (
          <motion.div key="decided" {...swap} className="flex items-center gap-2">
            <Popover
              label="How Snap decided"
              trigger={({ toggle, ...aria }) => (
                <motion.button
                  type="button"
                  onClick={toggle}
                  whileTap={press}
                  {...aria}
                  className="focus-ring -mx-1.5 flex h-6 items-center gap-1.5 rounded-[6px] px-1.5 text-[12px] text-fg-4 tabular-nums hover:bg-white/[0.05]"
                >
                  <motion.span {...iconSwap} className="flex">
                    <BoltIcon size={14} className="text-fg" />
                  </motion.span>
                  <span className="font-medium text-fg">Snap</span>
                  <span aria-hidden className="text-fg-6">·</span>
                  <span>{[decision.component, ...(decision.extras ?? [])].map((id) => blocks[id].label).join(" + ")}</span>
                  <span aria-hidden className="text-fg-6">·</span>
                  <span>{pct(sureness(decision))}</span>
                  <span aria-hidden className="text-fg-6">·</span>
                  <span>{secs(decision.ms)}</span>
                  <span aria-hidden className="text-fg-6">·</span>
                  <span>{short(decision.inputTokens)} tokens read</span>
                </motion.button>
              )}
            >
              <Breakdown decision={decision} recallNumber={recallNumber} writer={writer} writeMs={writeMs} />
            </Popover>
            {recallNumber != null && (
              <motion.button
                type="button"
                onClick={onRecall}
                whileTap={press}
                className="focus-ring flex h-6 items-center gap-1 rounded-[6px] bg-control px-2 text-[12px] text-fg-3 tabular-nums hover:bg-control-hover"
              >
                <QuoteIcon size={13} />
                From message {recallNumber}
              </motion.button>
            )}
            {docs.length > 0 && (
              <motion.button
                type="button"
                onClick={() => viewer.open(docs[0].id)}
                whileTap={press}
                title={docs.map((d) => d.name).join(", ")}
                className="focus-ring flex h-6 max-w-[14rem] items-center gap-1 rounded-[6px] bg-control px-2 text-[12px] text-fg-3 tabular-nums hover:bg-control-hover"
              >
                <NoteIcon size={13} className="shrink-0" />
                <span className="truncate">{docs.length === 1 ? base(docs[0].name) : `${docs.length} files`}</span>
              </motion.button>
            )}
          </motion.div>
        ) : (
          <motion.div key="deciding" {...swap} className="flex h-6 items-center gap-1.5 text-[12px] text-fg-4" role="status">
            <BoltIcon size={14} className="animate-pulse text-fg-5 motion-reduce:animate-none" />
            Snap is deciding
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function Breakdown({ decision, recallNumber, writer, writeMs }: { decision: Decision; recallNumber?: number; writer?: string; writeMs?: number }) {
  const artifacts = useContext(ArtifactsContext);
  const shared = Object.keys(artifacts).length;
  const ranked = [...blockIds].sort((a, b) => (decision.probabilities[b] ?? 0) - (decision.probabilities[a] ?? 0));
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col gap-1.5">
        <span className="text-[12px] text-fg-4">Components Snap weighed</span>
        {ranked.map((id) => {
          const p = decision.probabilities[id] ?? 0;
          const chosen = id === decision.component;
          return (
            <div key={id} className="grid grid-cols-[5.5rem_1fr_2.5rem] items-center gap-2 text-[12px] tabular-nums">
              <span className={chosen ? "font-medium text-fg" : "text-fg-3"}>{blocks[id].label}</span>
              <div className="h-1 overflow-hidden rounded-full bg-white/[0.08]">
                <div
                  className={`h-full origin-left rounded-full ${chosen ? "bg-accent" : "bg-fg-5"}`}
                  style={{ transform: `scaleX(${p})` }}
                />
              </div>
              <span className="text-end text-fg-4">{pct(p)}</span>
            </div>
          );
        })}
      </div>
      <div className="flex flex-col gap-1 border-t border-line pt-3">
        {decision.extras?.length ? (
          <Row label="Also showing" value={decision.extras.map((id) => `${blocks[id].label} ${pct(decision.extraProbabilities?.[id] ?? 0)}`).join(", ")} />
        ) : null}
        <Row label="Went back to" value={recallNumber != null ? `message ${recallNumber}, ${pct(decision.recallConfidence)}` : "nothing earlier"} />
        <Row
          label={shared > 12 ? `Picked from ${shared} files` : "From context"}
          value={decision.artifacts.length ? decision.artifacts.map((id) => (artifacts[id] ? base(artifacts[id].name) : id)).join(", ") : "none"}
        />
        <Row label="Length" value={DEPTHS[decision.depth] ?? DEPTHS[1]} />
        <Row label="Images looked at" value={decision.images} />
        <Row label="Read" value={`${decision.inputTokens.toLocaleString("en")} tokens`} />
        <Row label="Decided in" value={secs(decision.ms)} />
        {writer && <Row label="Written by" value={`${writer}${writeMs ? `, ${secs(writeMs)}` : ""}`} />}
      </div>
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useState } from "react";
import { easeOut } from "@/lib/motion";

/** Drop files anywhere on the page. While a file is held over it, the page says so; nothing else moves. */
export function DropZone({ onFiles }: { onFiles: (files: File[]) => void }) {
  const [over, setOver] = useState(false);

  useEffect(() => {
    let depth = 0;
    const hasFiles = (e: DragEvent) => e.dataTransfer?.types.includes("Files");
    const enter = (e: DragEvent) => {
      if (!hasFiles(e)) return;
      depth++;
      setOver(true);
    };
    const leave = (e: DragEvent) => {
      if (!hasFiles(e)) return;
      depth = Math.max(0, depth - 1);
      if (!depth) setOver(false);
    };
    const overFn = (e: DragEvent) => {
      if (hasFiles(e)) e.preventDefault();
    };
    const drop = (e: DragEvent) => {
      if (!hasFiles(e)) return;
      e.preventDefault();
      depth = 0;
      setOver(false);
      const files = [...(e.dataTransfer?.files ?? [])];
      if (files.length) onFiles(files);
    };
    window.addEventListener("dragenter", enter);
    window.addEventListener("dragleave", leave);
    window.addEventListener("dragover", overFn);
    window.addEventListener("drop", drop);
    return () => {
      window.removeEventListener("dragenter", enter);
      window.removeEventListener("dragleave", leave);
      window.removeEventListener("dragover", overFn);
      window.removeEventListener("drop", drop);
    };
  }, [onFiles]);

  return (
    <AnimatePresence>
      {over && (
        <motion.div
          className="pointer-events-none fixed inset-0 z-50 flex items-center justify-center bg-background/90 p-4"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1, transition: { duration: 0.18, ease: easeOut } }}
          exit={{ opacity: 0, transition: { duration: 0.12, ease: easeOut } }}
        >
          <motion.div
            className="flex size-full items-center justify-center rounded-[24px] border-2 border-dashed border-line-strong"
            initial={{ scale: 0.98, filter: "blur(4px)" }}
            animate={{ scale: 1, filter: "blur(0px)", transition: { duration: 0.22, ease: easeOut } }}
          >
            <div className="flex flex-col items-center gap-1 text-center">
              <p className="text-[17px] font-medium text-fg">Drop to attach</p>
              <p className="text-[13px] text-fg-4">Images, PDF, Markdown, text, CSV or JSON. It all stays in context.</p>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import type { SVGProps } from "react";

// anishfn.ink icons, the subset this chat uses: 18px grid, puffy and round. Filled shapes are traced with a thick
// round-joined stroke of the same color, which inflates them and rounds every corner;
// line glyphs are 1.6px strokes with round caps. No sharp points. Single tone, currentColor.

type IconProps = Omit<SVGProps<SVGSVGElement>, "children"> & { size?: number };

function Icon({ size = 18, children, ...props }: IconProps & { children: React.ReactNode }) {
  return (
    <svg width={size} height={size} viewBox="0 0 18 18" fill="currentColor" aria-hidden {...props}>
      {children}
    </svg>
  );
}

