/* ---------- a GitHub repository ---------- */

const EXAMPLES = ["pmndrs/zustand", "sindresorhus/ky", "honojs/hono"];
/** Folders that are rarely what a question is about: the first to go when a repository doesn't fit. */
const RARELY = ["test", "tests", "__tests__", "e2e", "fixtures", "__fixtures__", "examples", "example", "benchmarks", "benchmark", "bench", "docs", "doc", "website", "www", "site", ".github", "scripts", "playground", "demo", "demos"];

/** Everything readable, less whole folders until it fits: the rarely-asked-about first, then the heaviest. */
function fit(files: RepoFile[], base: string, maxTokens: number, maxFiles: number) {
  const picked = new Set(files.map((f) => f.path));
  const size = new Map(files.map((f) => [f.path, f.size]));
  const left: string[] = [];
  const top = (p: string) => {
    const rel = p.slice(base.length);
    const i = rel.indexOf("/");
    return i < 0 ? null : rel.slice(0, i);
  };
  const total = () => tokensOf([...picked].reduce((n, p) => n + size.get(p)!, 0));
  while (picked.size > maxFiles || total() > maxTokens) {
    const dirs = new Map<string, number>();
    for (const p of picked) {
      const d = top(p);
      if (d) dirs.set(d, (dirs.get(d) ?? 0) + size.get(p)!);
    }
    const drop = RARELY.find((d) => dirs.has(d)) ?? [...dirs].sort((a, b) => b[1] - a[1])[0]?.[0];
    if (!drop) {
      // only loose files left: the biggest go
      const biggest = [...picked].sort((a, b) => size.get(b)! - size.get(a)!)[0];
      if (!biggest) break;
      picked.delete(biggest);
      continue;
    }
    for (const p of [...picked]) if (top(p) === drop) picked.delete(p);
    left.push(drop);
  }
  return { picked, left };
}

type Row = { name: string; path: string; dir: boolean; count: number; picked: number; tokens: number };

function RepoTab({ onAdd, freeTokens, freeFiles }: { onAdd: (i: Incoming) => void; freeTokens: number; freeFiles: number }) {
  const [query, setQuery] = useState("");
  const [state, setState] = useState<"idle" | "loading" | "ready" | "adding">("idle");
  const [error, setError] = useState("");
  const [repo, setRepo] = useState<RepoListing | null>(null);
  const [picked, setPicked] = useState<Set<string>>(new Set());
  const [left, setLeft] = useState<string[]>([]);
  /** The folder being looked at, as a path ending in "/" ("" is the top). */
  const [at, setAt] = useState("");
  const [fetched, setFetched] = useState(0);
  const abort = useRef<AbortController | null>(null);
  useEffect(() => () => abort.current?.abort(), []);

  const maxFiles = Math.max(0, Math.min(MAX_FILES, freeFiles));
  const base = repo?.path ? `${repo.path}/` : "";

  const lookup = async (value = query) => {
    if (!value.trim()) return;
    abort.current?.abort();
    const controller = (abort.current = new AbortController());
    setState("loading");
    setError("");
    try {
      const res = await fetch("/api/github/repo", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ repo: value }), signal: controller.signal });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error ?? "Couldn't reach GitHub.");
      const listing = body as RepoListing;
      const start = fit(listing.files, listing.path ? `${listing.path}/` : "", freeTokens, maxFiles);
      setRepo(listing);
      setPicked(start.picked);
      setLeft(start.left);
      setAt(listing.path ? `${listing.path}/` : "");
      setState("ready");
    } catch (e) {
      if (controller.signal.aborted) return;
      setRepo(null);
      setError(e instanceof Error ? e.message : "Couldn't reach GitHub.");
      setState("idle");
    }
  };

  const sizes = useMemo(() => new Map((repo?.files ?? []).map((f) => [f.path, f.size])), [repo]);
  const tokens = useMemo(() => tokensOf([...picked].reduce((n, p) => n + (sizes.get(p) ?? 0), 0)), [picked, sizes]);

  // what's in the folder being looked at: its folders first, then its files
  const rows = useMemo(() => {
    const map = new Map<string, Row>();
    for (const f of repo?.files ?? []) {
      if (!f.path.startsWith(at)) continue;
      const rest = f.path.slice(at.length);
      const i = rest.indexOf("/");
      const name = i < 0 ? rest : rest.slice(0, i);
      const row = map.get(name) ?? { name, path: at + name + (i < 0 ? "" : "/"), dir: i >= 0, count: 0, picked: 0, tokens: 0 };
      row.count++;
      if (picked.has(f.path)) {
        row.picked++;
        row.tokens += f.size;
      }
      map.set(name, row);
    }
    return [...map.values()].sort((a, b) => Number(b.dir) - Number(a.dir) || a.name.localeCompare(b.name));
  }, [repo, at, picked]);

  const toggle = (row: Row) => {
    const next = new Set(picked);
    const under = (repo?.files ?? []).filter((f) => (row.dir ? f.path.startsWith(row.path) : f.path === row.path));
    if (row.picked === row.count) under.forEach((f) => next.delete(f.path));
    else under.forEach((f) => next.add(f.path));
    setPicked(next);
  };

  const add = async () => {
    if (!repo) return;
    const controller = (abort.current = new AbortController());
    const paths = (repo.files ?? []).map((f) => f.path).filter((p) => picked.has(p));
    setState("adding");
    setFetched(0);
    setError("");
    const files: { name: string; text: string }[] = [];
    try {
      for (let i = 0; i < paths.length; i += 40) {
        const res = await fetch("/api/github/files", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ owner: repo.owner, repo: repo.repo, ref: repo.ref, paths: paths.slice(i, i + 40) }),
          signal: controller.signal,
        });
        const body = await res.json();
        if (!res.ok) throw new Error(body.error ?? "Couldn't reach GitHub.");
        for (const f of body.files as { path: string; text: string }[]) files.push({ name: f.path, text: f.text });
        setFetched(Math.min(paths.length, i + 40));
      }
      if (!files.length) throw new Error("None of those files could be read.");
      onAdd({ files, source: { kind: "github", label: `${repo.owner}/${repo.repo}`, url: `https://github.com/${repo.owner}/${repo.repo}/tree/${repo.ref}${repo.path ? `/${repo.path}` : ""}` } });
    } catch (e) {
      if (controller.signal.aborted) return;
      setError(e instanceof Error ? e.message : "Couldn't reach GitHub.");
      setState("ready");
    }
  };

  const over = tokens > freeTokens;
  const tooMany = picked.size > maxFiles;
  const crumbs = at.slice(base.length).split("/").filter(Boolean);
  const adding = state === "adding";

  return (
    <div className="flex flex-1 flex-col gap-3">
      <Lookup
        value={query}
        onValue={setQuery}
        onSubmit={() => lookup()}
        placeholder="owner/repo, or a github.com link"
        label="Repository"
        action="Look up"
        busy={state === "loading"}
        icon={<BranchIcon size={16} className="shrink-0" />}
      />
      {error && <Problem>{error}</Problem>}

      <AnimatePresence mode="popLayout" initial={false}>
        {state === "loading" ? (
          <motion.div key="loading" {...swap} className="flex flex-col gap-2.5 px-2 pt-1" role="status" aria-label="Looking up the repository">
            <div className="skeleton h-4 w-2/5 rounded-[6px]" />
            <div className="skeleton h-3 w-3/4 rounded-[6px]" />
            <div className="skeleton mt-2 h-1 w-full rounded-full" />
            {[72, 58, 64, 46, 60].map((w, i) => (
              <div key={i} className="flex items-center gap-2.5">
                <div className="skeleton size-[18px] rounded-[6px]" />
                <div className="skeleton h-3 rounded-[6px]" style={{ width: `${w}%` }} />
              </div>
            ))}
          </motion.div>
        ) : repo ? (
          <motion.div key={`${repo.owner}/${repo.repo}/${repo.ref}/${repo.path}`} {...swap} className="flex flex-1 flex-col gap-3">
            <div className="flex flex-col gap-1 px-2">
              <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5 text-[12px] text-fg-4 tabular-nums">
                <span className="text-[14px] font-medium text-fg">
                  {repo.owner}/{repo.repo}
                </span>
                <span className="flex items-center gap-1">
                  <StarIcon size={13} />
                  {k(repo.stars)}
                </span>
                <span className="flex items-center gap-1">
                  <BranchIcon size={13} />
                  {repo.ref}
                </span>
              </div>
              {repo.description && <p className="line-clamp-1 text-[13px] text-fg-3">{repo.description}</p>}
            </div>

            <div className="px-2">
              <Budget tokens={tokens} free={freeTokens} note={`${picked.size.toLocaleString("en")} of ${repo.files.length.toLocaleString("en")} files`} />
            </div>

            {over || tooMany ? (
              <Problem>
                {over ? `Over by ${k(tokens - freeTokens)} tokens.` : `Snap ranks up to ${maxFiles} files at once: ${picked.size - maxFiles} too many.`} Untick a folder to make room.
              </Problem>
            ) : left.length > 0 ? (
              <p className="px-2 text-[12px] leading-snug text-pretty text-fg-4">
                Left out so it fits: {left.slice(0, 5).join(", ")}
                {left.length > 5 ? ` and ${left.length - 5} more` : ""}. {left.length === 1 ? "Tick it back in if you need it." : "Tick them back in if you need them."}
              </p>
            ) : repo.truncated ? (
              <p className="px-2 text-[12px] leading-snug text-pretty text-fg-4">This repository is too big for GitHub to list whole. Paste a link to one of its folders to see all of that folder.</p>
            ) : null}

            <div className="flex min-h-0 flex-col rounded-[12px] bg-surface p-1 shadow-[inset_0_0_0_1px_var(--line)]">
              <nav className="no-scrollbar flex items-center gap-0.5 overflow-x-auto px-1 pt-0.5 pb-1 text-[12px]" aria-label="Folder">
                <Crumb label={base ? base.slice(0, -1) : `${repo.repo}`} current={!crumbs.length} onClick={() => setAt(base)} />
                {crumbs.map((c, i) => (
                  <span key={i} className="flex shrink-0 items-center gap-0.5">
                    <ChevronRightIcon size={12} className="text-fg-6" />
                    <Crumb label={c} current={i === crumbs.length - 1} onClick={() => setAt(`${base}${crumbs.slice(0, i + 1).join("/")}/`)} />
                  </span>
                ))}
              </nav>
              <ul className="flex max-h-[11.5rem] flex-col overflow-y-auto">
                {rows.map((row) => (
                  <li key={row.path} className="flex items-center">
                    <Check
                      state={row.picked === 0 ? "off" : row.picked === row.count ? "on" : "some"}
                      label={`${row.picked === row.count ? "Leave out" : "Include"} ${row.name}`}
                      onClick={() => toggle(row)}
                      disabled={adding}
                    />
                    {row.dir ? (
                      <button
                        type="button"
                        onClick={() => setAt(row.path)}
                        className={`focus-ring group flex h-8 min-w-0 flex-1 items-center gap-2 rounded-[8px] ps-1.5 pe-1.5 text-start text-[13px] hover:bg-white/[0.05] ${rowPress}`}
                      >
                        <FolderIcon size={15} className="shrink-0 text-fg-4" />
                        <span className={`min-w-0 flex-1 truncate transition-colors duration-200 ${row.picked ? "text-fg" : "text-fg-4"}`}>{row.name}</span>
                        <span className="shrink-0 text-[12px] text-fg-4 tabular-nums">
                          {row.picked === row.count ? plural(row.count, "file") : `${row.picked} of ${row.count}`}
                          {row.picked > 0 && ` · ${k(tokensOf(row.tokens))}`}
                        </span>
                        <ChevronRightIcon size={14} className="shrink-0 text-fg-5 transition-colors group-hover:text-fg-2" />
                      </button>
                    ) : (
                      <div className="flex h-8 min-w-0 flex-1 items-center gap-2 ps-1.5 pe-2 text-[13px]">
                        <NoteIcon size={15} className="shrink-0 text-fg-5" />
                        <span className={`min-w-0 flex-1 truncate transition-colors duration-200 ${row.picked ? "text-fg-2" : "text-fg-5"}`}>{row.name}</span>
                        <span className="shrink-0 text-[12px] text-fg-5 tabular-nums">{k(tokensOf(sizes.get(row.path) ?? 0))}</span>
                      </div>
                    )}
                  </li>
                ))}
              </ul>
            </div>

            <Footer
              note={
                adding ? (
                  <span className="tabular-nums">
                    Fetched {fetched} of {picked.size} files
                  </span>
                ) : (
                  "Snap reads all of it on every turn and picks the files each answer needs."
                )
              }
              action={adding ? "Adding" : `Add ${plural(picked.size, "file")}`}
              disabled={adding || over || tooMany || picked.size === 0}
              busy={adding}
              onAction={add}
            />
          </motion.div>
        ) : (
          <motion.div key="idle" {...swap} className="flex flex-1 flex-col gap-3 px-2 pt-1">
            <p className="text-[13px] leading-relaxed text-pretty text-fg-3">
              Paste a public repository and its code joins this chat as documents. You&apos;ll see how much fits before anything is added.
            </p>
            <div className="flex flex-wrap items-center gap-1.5 text-[12px] text-fg-4">
              Try
              {EXAMPLES.map((e) => (
                <motion.button
                  key={e}
                  type="button"
                  whileTap={press}
                  onClick={() => {
                    setQuery(e);
                    lookup(e);
                  }}
                  className="focus-ring h-7 rounded-[8px] bg-control px-2.5 text-fg-2 hover:bg-control-hover hover:text-fg"
                >
                  {e}
                </motion.button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function Crumb({ label, current, onClick }: { label: string; current: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-current={current ? "page" : undefined}
      className={`focus-ring h-6 shrink-0 rounded-[6px] px-1.5 transition-colors ${current ? "font-medium text-fg" : "text-fg-4 hover:bg-white/[0.06] hover:text-fg"}`}
    >
      {label}
    </button>
  );
}

/** A tick box with a third state, for a folder with only some of its files in. */
function Check({ state, label, onClick, disabled }: { state: "on" | "off" | "some"; label: string; onClick: () => void; disabled?: boolean }) {
  return (
    <motion.button
      type="button"
      role="checkbox"
      aria-checked={state === "on" ? true : state === "some" ? "mixed" : false}
      aria-label={label}
      disabled={disabled}
      whileTap={disabled ? undefined : tap}
      onClick={onClick}
      className="focus-ring flex size-8 shrink-0 items-center justify-center rounded-[8px]"
    >
      <span
        className={`flex size-[18px] items-center justify-center rounded-[6px] transition-[background-color,box-shadow] duration-150 ease-out ${
          state === "off" ? "shadow-[inset_0_0_0_1.5px_var(--line-strong)]" : "bg-accent text-accent-fg"
        }`}
      >
        <AnimatePresence mode="popLayout" initial={false}>
          {state !== "off" && (
            <motion.span
              key={state}
              className="flex"
              initial={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
              animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
              exit={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
              transition={{ type: "spring", duration: 0.3, bounce: 0 }}
            >
              {state === "on" ? <CheckIcon size={13} /> : <MinusIcon size={13} />}
            </motion.span>
          )}
        </AnimatePresence>
      </span>
    </motion.button>
  );
}

/* ---------- a web page ---------- */

function PageTab({ onAdd, freeTokens }: { onAdd: (i: Incoming) => void; freeTokens: number }) {
  const [url, setUrl] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [page, setPage] = useState<PageResult | null>(null);
  const abort = useRef<AbortController | null>(null);
  useEffect(() => () => abort.current?.abort(), []);

  const read = async () => {
    if (!url.trim()) return;
    abort.current?.abort();
    const controller = (abort.current = new AbortController());
    setBusy(true);
    setError("");
    try {
      const res = await fetch("/api/page", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ url }), signal: controller.signal });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error ?? "Couldn't read that page.");
      setPage(body as PageResult);
    } catch (e) {
      if (controller.signal.aborted) return;
      setPage(null);
      setError(e instanceof Error ? e.message : "Couldn't read that page.");
    } finally {
      if (!controller.signal.aborted) setBusy(false);
    }
  };

  // prose runs nearer four characters a token than code's three
  const tokens = page ? Math.round(page.text.length / 4) : 0;
  const host = page ? new URL(page.url).hostname.replace(/^www\./, "") : "";

  return (
    <div className="flex flex-1 flex-col gap-3">
      <Lookup value={url} onValue={setUrl} onSubmit={read} placeholder="Paste a link" label="Web address" action="Read" busy={busy} icon={<GlobeIcon size={16} className="shrink-0" />} />
      {error && <Problem>{error}</Problem>}
      <AnimatePresence mode="popLayout" initial={false}>
        {busy ? (
          <motion.div key="loading" {...swap} className="flex flex-col gap-2.5 px-2 pt-1" role="status" aria-label="Reading the page">
            <div className="skeleton h-4 w-3/5 rounded-[6px]" />
            <div className="skeleton h-3 w-1/4 rounded-[6px]" />
            <div className="skeleton mt-2 h-28 w-full rounded-[12px]" />
          </motion.div>
        ) : page ? (
          <motion.div key={page.url} {...swap} className="flex flex-1 flex-col gap-3">
            <div className="flex flex-col gap-0.5 px-2">
              <span className="line-clamp-2 text-[14px] font-medium text-pretty text-fg">{page.title}</span>
              <span className="text-[12px] text-fg-4">{host}</span>
            </div>
            <div className="px-2">
              <Budget tokens={tokens} free={freeTokens} note={`${page.text.length.toLocaleString("en")} characters`} />
            </div>
            {tokens > freeTokens && <Problem>Over by {k(tokens - freeTokens)} tokens. This page is too long for what&apos;s left in this chat.</Problem>}
            <p className="line-clamp-[8] rounded-[12px] bg-surface px-3 py-2.5 text-[13px] leading-relaxed whitespace-pre-line text-fg-3 shadow-[inset_0_0_0_1px_var(--line)]">{page.text.slice(0, 900).replace(/\n{2,}/g, "\n")}</p>
            <Footer
              note="Added as a document. Snap reads it on every turn."
              action="Add page"
              disabled={tokens > freeTokens}
              busy={false}
              onAction={() => onAdd({ files: [{ name: page.title, text: page.text }], source: { kind: "page", label: host, url: page.url } })}
            />
          </motion.div>
        ) : (
          <motion.p key="idle" {...swap} className="px-2 pt-1 text-[13px] leading-relaxed text-pretty text-fg-3">
            Paste a link to an article, a docs page or a README. Its text joins this chat as a document; pages that only appear after their scripts run can&apos;t be read.
          </motion.p>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { createContext, useCallback, useEffect, useId, useRef, useState } from "react";
import { Action, CopyAction, Swap } from "@/components/blocks/shared";
import { DownloadIcon, MinusIcon, NoteIcon, PlusIcon, XIcon } from "@/components/icons";
import { easeOut, glide } from "@/lib/motion";
import type { Artifact } from "@/lib/types";
import { PdfPages } from "./pdf-pages";
import { docKind, TextView } from "./text-view";

// Documents open in a panel on the right, the way other assistants do it: the chat narrows beside it on a wide
// screen, and on a phone it covers the chat. One document at a time; opening another swaps the contents. Drag the
// left edge to resize; Escape or × closes, and focus goes back to whatever opened it.

export const DocViewerContext = createContext<{ open: (id: string) => void; openId: string | null }>({ open: () => {}, openId: null });

export const PANEL_MIN = 380;
export const panelDefault = () => Math.round(Math.min(680, Math.max(PANEL_MIN, window.innerWidth * 0.44)));

const KIND_LABEL: Record<string, string> = { pdf: "PDF", markdown: "Markdown", csv: "CSV", tsv: "TSV", json: "JSON", xml: "XML", text: "Text" };
const ZOOMS = [0.5, 0.67, 0.8, 1, 1.25, 1.5, 2];

const size = (bytes: number) => (bytes >= 1e6 ? `${(bytes / 1e6).toFixed(1)} MB` : bytes >= 1e3 ? `${Math.round(bytes / 1e3)} KB` : `${bytes} B`);

function download(a: Artifact) {
  const blob = a.base64
    ? new Blob([Uint8Array.from(atob(a.base64), (c) => c.charCodeAt(0))], { type: a.mediaType })
    : new Blob([a.text ?? ""], { type: a.mediaType || "text/plain" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = a.name;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

export function DocPanel({
  artifact,
  wide,
  width,
  onWidth,
  onClose,
  onResizing,
}: {
  artifact: Artifact | null;
  wide: boolean;
  width: number;
  onWidth: (w: number) => void;
  onClose: () => void;
  /** While the edge is dragged, the chat follows it directly instead of easing after it. */
  onResizing: (on: boolean) => void;
}) {
  // On a phone the panel covers the chat: the chat behind it shouldn't scroll.
  const covering = !!artifact && !wide;
  useEffect(() => {
    if (!covering) return;
    const html = document.documentElement;
    const before = html.style.overflow;
    html.style.overflow = "hidden";
    return () => {
      html.style.overflow = before;
    };
  }, [covering]);

  return (
    <AnimatePresence>
      {artifact && (
        <motion.aside
          key="doc-panel"
          role="dialog"
          aria-label={artifact.name}
          aria-modal={!wide}
          className={`fixed inset-y-0 right-0 z-50 flex flex-col bg-sidebar ${wide ? "shadow-[inset_1px_0_0_var(--line)]" : "w-full"}`}
          style={wide ? { width } : undefined}
          initial={{ x: "100%" }}
          animate={{ x: 0, transition: { duration: 0.34, ease: easeOut } }}
          exit={{ x: "100%", transition: { duration: 0.22, ease: easeOut } }}
        >
          {wide && <ResizeEdge width={width} onWidth={onWidth} onResizing={onResizing} />}
          <Viewer artifact={artifact} onClose={onClose} />
        </motion.aside>
      )}
    </AnimatePresence>
  );
}

/** The panel's left edge: drag to resize, arrow keys too. A hairline that brightens when it's yours. */
function ResizeEdge({ width, onWidth, onResizing }: { width: number; onWidth: (w: number) => void; onResizing: (on: boolean) => void }) {
  const start = useRef<{ x: number; w: number } | null>(null);
  const clamp = (w: number) => Math.round(Math.max(PANEL_MIN, Math.min(w, window.innerWidth - 480)));
  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-label="Resize the document panel"
      aria-valuenow={width}
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "ArrowLeft") onWidth(clamp(width + 24));
        if (e.key === "ArrowRight") onWidth(clamp(width - 24));
      }}
      onPointerDown={(e) => {
        e.currentTarget.setPointerCapture(e.pointerId);
        start.current = { x: e.clientX, w: width };
        onResizing(true);
      }}
      onPointerMove={(e) => start.current && onWidth(clamp(start.current.w + (start.current.x - e.clientX)))}
      onPointerUp={() => {
        start.current = null;
        onResizing(false);
      }}
      className="group focus-ring absolute inset-y-0 -left-1.5 z-10 w-3 cursor-col-resize touch-none"
    >
      <span className="absolute inset-y-0 left-1.5 w-px bg-transparent transition-colors duration-150 group-hover:bg-line-strong group-active:bg-fg-4 group-focus-visible:bg-fg-4" />
    </div>
  );
}

function Viewer({ artifact: a, onClose }: { artifact: Artifact; onClose: () => void }) {
  const kind = docKind(a.mediaType, a.name);
  const isPdf = kind === "pdf" && !!a.base64;
  const [view, setView] = useState<"pages" | "text">("pages");
  const [zoom, setZoom] = useState(1);
  const [pages, setPages] = useState(0);
  const [page, setPage] = useState(1);
  const [pdfText, setPdfText] = useState("");
  const close = useRef<HTMLButtonElement>(null);
  const pill = useId();

  // A new document starts at the top, at fit, on its pages.
  const [shown, setShown] = useState(a.id);
  if (shown !== a.id) {
    setShown(a.id);
    setView("pages");
    setZoom(1);
    setPages(0);
    setPage(1);
    setPdfText("");
  }

  useEffect(() => {
    close.current?.focus({ preventScroll: true });
  }, [a.id]);

  useEffect(() => {
    const key = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      // an image viewer open on top takes Escape first
      const above = [...document.querySelectorAll('[role="dialog"][aria-modal="true"]')].some((d) => !d.contains(close.current));
      if (!above) onClose();
    };
    document.addEventListener("keydown", key);
    return () => document.removeEventListener("keydown", key);
  }, [onClose]);

  const onPage = useCallback((n: number) => setPage(n), []);
  const text = isPdf ? pdfText : (a.text ?? "");
  const zi = ZOOMS.indexOf(zoom);

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <header className="flex shrink-0 flex-col gap-2 border-b border-line px-4 pt-4 pb-3">
        <div className="flex items-start gap-3">
          <span className="flex size-9 shrink-0 items-center justify-center rounded-[10px] bg-surface text-fg-3">
            <NoteIcon size={17} />
          </span>
          <div className="flex min-w-0 flex-1 flex-col">
            <h2 className="truncate text-[14px] font-medium text-fg" title={a.name}>
              {a.name}
            </h2>
            <p className="text-[12px] text-fg-4 tabular-nums">
              {KIND_LABEL[kind] ?? "Document"}
              {a.bytes > 0 && ` · ${size(a.bytes)}`}
              {isPdf && pages > 0 && (
                <>
                  {" · "}
                  <Swap value={`${pages} ${pages === 1 ? "page" : "pages"}`} />
                </>
              )}
            </p>
          </div>
          <div className="-me-1.5 flex items-center gap-0.5">
            <CopyAction showLabel={false} label="Copy text" text={() => text} />
            <Action showLabel={false} label="Download" icon={<DownloadIcon size={15} />} onClick={() => download(a)} />
            <button
              ref={close}
              type="button"
              onClick={onClose}
              aria-label="Close"
              className="focus-ring flex size-7 items-center justify-center rounded-[8px] text-fg-4 transition-colors hover:bg-white/[0.06] hover:text-fg"
            >
              <XIcon size={16} />
            </button>
          </div>
        </div>
        {isPdf && (
          <div className="flex items-center justify-between gap-2">
            <div role="tablist" aria-label="View" className="flex gap-0.5 rounded-[10px] bg-surface p-0.5">
              {(["pages", "text"] as const).map((v) => (
                <button
                  key={v}
                  type="button"
                  role="tab"
                  aria-selected={view === v}
                  onClick={() => setView(v)}
                  className={`focus-ring relative h-6 rounded-[8px] px-2.5 text-[12px] capitalize transition-colors duration-200 ${view === v ? "text-fg" : "text-fg-4 hover:text-fg-2"}`}
                >
                  {view === v && <motion.span layoutId={`${pill}-v`} transition={glide} className="absolute inset-0 rounded-[8px] bg-control" />}
                  <span className="relative">{v}</span>
                </button>
              ))}
            </div>
            <AnimatePresence initial={false}>
              {view === "pages" && (
                <motion.div
                  className="flex items-center gap-1 text-[12px] text-fg-4 tabular-nums"
                  initial={{ opacity: 0, filter: "blur(4px)" }}
                  animate={{ opacity: 1, filter: "blur(0px)", transition: { duration: 0.18 } }}
                  exit={{ opacity: 0, transition: { duration: 0.1 } }}
                >
                  {pages > 0 && (
                    <span className="me-2" aria-live="polite">
                      <Swap value={page} /> / {pages}
                    </span>
                  )}
                  <Action showLabel={false} label="Zoom out" icon={<MinusIcon size={14} />} onClick={() => zi > 0 && setZoom(ZOOMS[zi - 1])} />
                  <button
                    type="button"
                    onClick={() => setZoom(1)}
                    className="focus-ring h-7 min-w-11 rounded-[8px] px-1 text-center transition-colors hover:bg-white/[0.06] hover:text-fg"
                    aria-label="Fit to width"
                  >
                    <Swap value={`${Math.round(zoom * 100)}%`} />
                  </button>
                  <Action showLabel={false} label="Zoom in" icon={<PlusIcon size={14} />} onClick={() => zi < ZOOMS.length - 1 && setZoom(ZOOMS[zi + 1])} />
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        )}
      </header>
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.div
          key={`${a.id}-${view}`}
          className="min-h-0 flex-1 overflow-auto overscroll-contain"
          initial={{ opacity: 0, filter: "blur(4px)" }}
          animate={{ opacity: 1, filter: "blur(0px)", transition: { duration: 0.22, ease: easeOut } }}
          exit={{ opacity: 0, transition: { duration: 0.1 } }}
        >
          {isPdf && view === "pages" ? (
            <PdfPages base64={a.base64!} zoom={zoom} onPages={setPages} onPage={onPage} onText={setPdfText} />
          ) : (
            <div className="mx-auto max-w-[72ch] px-5 py-5">
              {isPdf && !pdfText ? (
                <p className="text-[13px] text-fg-4">Reading the text…</p>
              ) : isPdf ? (
                <TextView text={pdfText} kind="text" />
              ) : (
                <TextView text={a.text ?? ""} kind={kind} />
              )}
            </div>
          )}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import type { PDFDocumentProxy } from "pdfjs-dist";
import { easeOut } from "@/lib/motion";

// A PDF drawn page by page with PDF.js (loaded only when a PDF is opened; its worker is served from /public).
// Pages are white sheets on the panel's dark ground, fitted to the panel's width times the zoom, drawn at the
// screen's pixel density, and only once they come near the viewport. The page most in view is reported up.

type Props = { base64: string; zoom: number; onPages: (n: number) => void; onPage: (n: number) => void; onText: (text: string) => void };

async function load(base64: string) {
  const pdfjs = await import("pdfjs-dist");
  pdfjs.GlobalWorkerOptions.workerSrc = "/pdf.worker.min.mjs";
  const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
  return pdfjs.getDocument({ data: bytes }).promise;
}

export function PdfPages({ base64, zoom, onPages, onPage, onText }: Props) {
  const [doc, setDoc] = useState<PDFDocumentProxy | null>(null);
  const [failed, setFailed] = useState(false);
  const [aspect, setAspect] = useState(1.414);
  const [width, setWidth] = useState(0);
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let live = true;
    let opened: PDFDocumentProxy | null = null;
    load(base64)
      .then(async (d) => {
        if (!live) return d.loadingTask.destroy();
        opened = d;
        const first = await d.getPage(1);
        const vp = first.getViewport({ scale: 1 });
        setAspect(vp.height / vp.width);
        setDoc(d);
        onPages(d.numPages);
        // The text, for Copy and the Text view, read in the background.
        const pages: string[] = [];
        for (let i = 1; i <= d.numPages; i++) {
          const content = await (await d.getPage(i)).getTextContent();
          pages.push(content.items.map((it) => ("str" in it ? it.str + (it.hasEOL ? "\n" : "") : "")).join(""));
        }
        if (live) onText(pages.map((p, i) => `[page ${i + 1}]\n${p.trim()}`).join("\n\n"));
      })
      .catch(() => live && setFailed(true));
    return () => {
      live = false;
      opened?.loadingTask.destroy();
    };
    // the callbacks are stable setters from the panel
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [base64]);

  useEffect(() => {
    const el = box.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => setWidth(Math.round(e.contentRect.width)));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // Which page is most in view.
  useEffect(() => {
    const el = box.current;
    if (!el || !doc) return;
    const seen = new Map<number, number>();
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) seen.set(Number((e.target as HTMLElement).dataset.page), e.intersectionRatio);
        const best = [...seen.entries()].sort((a, b) => b[1] - a[1])[0];
        if (best) onPage(best[0]);
      },
      { threshold: [0, 0.25, 0.5, 0.75, 1] },
    );
    el.querySelectorAll("[data-page]").forEach((p) => io.observe(p));
    return () => io.disconnect();
  }, [doc, onPage]);

  if (failed) return <p className="px-6 py-10 text-center text-[13px] text-fg-4">This PDF couldn&apos;t be opened. It may be damaged or protected.</p>;

  const pageW = Math.max(120, (width - 32) * zoom);
  return (
    <div ref={box} className="flex flex-col items-center gap-4 px-4 py-4">
      {doc
        ? Array.from({ length: doc.numPages }, (_, i) => <Page key={i} doc={doc} n={i + 1} width={pageW} aspect={aspect} />)
        : [0, 1].map((i) => <div key={i} className="skeleton w-full rounded-[4px]" style={{ aspectRatio: `1 / ${aspect}` }} />)}
    </div>
  );
}

/** One page: drawn when it nears the viewport, redrawn when the width changes, faded in once drawn. */
function Page({ doc, n, width, aspect }: { doc: PDFDocumentProxy; n: number; width: number; aspect: number }) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const holder = useRef<HTMLDivElement>(null);
  const [near, setNear] = useState(n <= 2);
  const [drawn, setDrawn] = useState(false);
  const [ratio, setRatio] = useState(aspect);

  useEffect(() => {
    const el = holder.current;
    if (!el || near) return;
    const io = new IntersectionObserver(([e]) => e.isIntersecting && setNear(true), { rootMargin: "800px 0px" });
    io.observe(el);
    return () => io.disconnect();
  }, [near]);

  useEffect(() => {
    if (!near || !canvas.current || width < 50) return;
    let cancelled = false;
    let task: { cancel: () => void; promise: Promise<void> } | null = null;
    (async () => {
      const page = await doc.getPage(n);
      if (cancelled || !canvas.current) return;
      const base = page.getViewport({ scale: 1 });
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const vp = page.getViewport({ scale: (width / base.width) * dpr });
      const c = canvas.current;
      c.width = Math.floor(vp.width);
      c.height = Math.floor(vp.height);
      setRatio(base.height / base.width);
      task = page.render({ canvas: c, viewport: vp });
      await task.promise.catch(() => {});
      if (!cancelled) setDrawn(true);
    })();
    return () => {
      cancelled = true;
      task?.cancel();
    };
  }, [doc, n, near, width]);

  return (
    <div ref={holder} data-page={n} className="relative w-full shrink-0" style={{ width, aspectRatio: `1 / ${ratio}` }}>
      <AnimatePresence initial={false}>
        {!drawn && (
          <motion.div className="skeleton absolute inset-0 rounded-[4px]" exit={{ opacity: 0, transition: { duration: 0.2, ease: easeOut } }} />
        )}
      </AnimatePresence>
      <canvas
        ref={canvas}
        aria-label={`Page ${n}`}
        className={`absolute inset-0 size-full rounded-[4px] bg-white shadow-surface transition-opacity duration-300 ease-out ${drawn ? "opacity-100" : "opacity-0"}`}
      />
    </div>
  );
}

"use client";

import { Fragment, type ReactNode } from "react";
import { highlight } from "@/components/blocks/simple";

// Text documents as people expect to read them: Markdown formatted, CSV and TSV as a table, JSON indented and
// coloured, anything else as plain text. Small hand-written parsers: nothing here executes the document.

/* ---------- Markdown ---------- */

function inlineMd(text: string): ReactNode[] {
  const out: ReactNode[] = [];
  const re = /(\*\*[^*]+\*\*|__[^_]+__|`[^`]+`|\[[^\]]+\]\([^)\s]+\)|\*[^*\s][^*]*\*|_[^_\s][^_]*_)/g;
  let last = 0;
  for (const m of text.matchAll(re)) {
    if (m.index > last) out.push(text.slice(last, m.index));
    const t = m[0];
    const k = m.index;
    if (t.startsWith("**") || t.startsWith("__")) out.push(<strong key={k} className="font-medium text-fg">{t.slice(2, -2)}</strong>);
    else if (t.startsWith("`")) out.push(<code key={k} className="rounded-[5px] bg-control px-1 py-0.5 font-mono text-[0.86em] text-fg">{t.slice(1, -1)}</code>);
    else if (t.startsWith("[")) {
      const [, label, href] = t.match(/^\[([^\]]+)\]\(([^)\s]+)\)$/) ?? [];
      const safe = /^(https?:|mailto:|#|\/)/.test(href ?? "");
      out.push(
        safe ? (
          <a key={k} href={href} target="_blank" rel="noreferrer" className="text-fg underline decoration-fg-6 underline-offset-2 hover:decoration-fg-3">
            {label}
          </a>
        ) : (
          label
        ),
      );
    } else out.push(<em key={k}>{t.slice(1, -1)}</em>);
    last = k + t.length;
  }
  out.push(text.slice(last));
  return out;
}

const cells = (row: string) => row.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());

function Markdown({ text }: { text: string }) {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const out: ReactNode[] = [];
  let i = 0;
  // front matter is metadata, not reading matter
  if (lines[0] === "---") {
    const end = lines.indexOf("---", 1);
    if (end > 0) i = end + 1;
  }
  while (i < lines.length) {
    const line = lines[i];
    const key = i;
    if (!line.trim()) {
      i++;
      continue;
    }
    const fence = line.match(/^```(\w*)/);
    if (fence) {
      const body: string[] = [];
      i++;
      while (i < lines.length && !lines[i].startsWith("```")) body.push(lines[i++]);
      i++;
      out.push(
        <pre key={key} className="overflow-x-auto rounded-[10px] bg-surface p-3 font-mono text-[12.5px] leading-relaxed text-fg-2">
          <code>{highlight(body.join("\n"), fence[1])}</code>
        </pre>,
      );
      continue;
    }
    const h = line.match(/^(#{1,6})\s+(.*)/);
    if (h) {
      const level = h[1].length;
      const size = ["text-[22px]", "text-[18px]", "text-[15px]", "text-[14px]", "text-[13px]", "text-[13px]"][level - 1];
      out.push(
        <p key={key} role="heading" aria-level={level} className={`${size} mt-3 leading-snug font-medium tracking-[-0.01em] text-balance text-fg first:mt-0`}>
          {inlineMd(h[2])}
        </p>,
      );
      i++;
      continue;
    }
    if (/^(-{3,}|\*{3,})\s*$/.test(line)) {
      out.push(<hr key={key} className="border-line" />);
      i++;
      continue;
    }
    if (line.startsWith("|") && lines[i + 1]?.match(/^\|?\s*:?-{2,}/)) {
      const head = cells(line);
      const rows: string[][] = [];
      i += 2;
      while (i < lines.length && lines[i].trim().startsWith("|")) rows.push(cells(lines[i++]));
      out.push(
        <div key={key} className="overflow-x-auto">
          <table className="w-full border-collapse text-[13px]">
            <thead>
              <tr>
                {head.map((c, j) => (
                  <th key={j} className="border-b border-line-strong px-2 py-1.5 text-start font-medium text-fg-3">
                    {inlineMd(c)}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((r, ri) => (
                <tr key={ri} className="border-b border-line">
                  {r.map((c, j) => (
                    <td key={j} className="px-2 py-1.5 align-top text-fg-2">
                      {inlineMd(c)}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>,
      );
      continue;
    }
    if (line.startsWith(">")) {
      const body: string[] = [];
      while (i < lines.length && lines[i].startsWith(">")) body.push(lines[i++].replace(/^>\s?/, ""));
      out.push(
        <blockquote key={key} className="border-s-2 border-line-strong ps-3 text-fg-3">
          {inlineMd(body.join(" "))}
        </blockquote>,
      );
      continue;
    }
    const bullet = /^(\s*)([-*+]|\d+[.)])\s+/;
    if (bullet.test(line)) {
      const ordered = /^\s*\d/.test(line);
      const items: { depth: number; text: string }[] = [];
      while (i < lines.length && bullet.test(lines[i])) {
        const m = lines[i].match(bullet)!;
        items.push({ depth: Math.min(3, Math.floor(m[1].length / 2)), text: lines[i].replace(bullet, "") });
        i++;
        // a wrapped line continues the item before it
        while (i < lines.length && lines[i].trim() && !bullet.test(lines[i]) && /^\s{2,}/.test(lines[i])) items[items.length - 1].text += " " + lines[i++].trim();
      }
      const List = ordered ? "ol" : "ul";
      out.push(
        <List key={key} className={`flex flex-col gap-1 ps-5 ${ordered ? "list-decimal" : "list-disc"} marker:text-fg-5`}>
          {items.map((it, j) => (
            <li key={j} style={{ marginInlineStart: it.depth * 16 }}>
              {inlineMd(it.text)}
            </li>
          ))}
        </List>,
      );
      continue;
    }
    const para: string[] = [];
    while (i < lines.length && lines[i].trim() && !/^(#{1,6}\s|```|>|\||\s*([-*+]|\d+[.)])\s)/.test(lines[i])) para.push(lines[i++]);
    if (!para.length) para.push(lines[i++]);
    out.push(<p key={key}>{inlineMd(para.join(" "))}</p>);
  }
  return <div className="flex flex-col gap-3 text-[14px] leading-[1.7] text-pretty text-fg-2">{out}</div>;
}

/* ---------- CSV / TSV ---------- */

function parseDelimited(text: string, sep: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let cell = "";
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"' && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (ch === '"') quoted = false;
      else cell += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === sep) {
      row.push(cell);
      cell = "";
    } else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && text[i + 1] === "\n") i++;
      row.push(cell);
      rows.push(row);
      row = [];
      cell = "";
    } else cell += ch;
  }
  if (cell || row.length) rows.push([...row, cell]);
  return rows.filter((r) => r.some((c) => c.trim()));
}

function Sheet({ text, sep }: { text: string; sep: string }) {
  const [head, ...rows] = parseDelimited(text, sep);
  const shown = rows.slice(0, 2000);
  return (
    <div className="flex flex-col gap-2">
      <div className="overflow-auto rounded-[10px] shadow-[inset_0_0_0_1px_var(--line)]">
        <table className="w-full border-collapse text-[12.5px]">
          <thead className="sticky top-0 bg-raised">
            <tr>
              <th className="w-10 border-b border-line-strong px-2 py-1.5 text-end font-normal text-fg-5 tabular-nums">#</th>
              {(head ?? []).map((c, j) => (
                <th key={j} className="border-b border-line-strong px-2 py-1.5 text-start font-medium whitespace-nowrap text-fg-3">
                  {c}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {shown.map((r, i) => (
              <tr key={i} className="border-b border-line hover:bg-white/[0.025]">
                <td className="px-2 py-1 text-end text-fg-6 tabular-nums">{i + 1}</td>
                {r.map((c, j) => (
                  <td key={j} className="px-2 py-1 whitespace-nowrap text-fg-2 tabular-nums">
                    {c}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="text-[12px] text-fg-5 tabular-nums">
        {rows.length.toLocaleString("en")} rows · {(head ?? []).length} columns{rows.length > shown.length ? ` · showing the first ${shown.length.toLocaleString("en")}` : ""}
      </p>
    </div>
  );
}

/* ---------- the switch ---------- */

export function docKind(mediaType: string, name: string) {
  const ext = name.split(".").pop()?.toLowerCase() ?? "";
  if (mediaType === "application/pdf" || ext === "pdf") return "pdf";
  if (mediaType === "text/markdown" || ext === "md" || ext === "markdown") return "markdown";
  if (mediaType === "text/csv" || ext === "csv") return "csv";
  if (mediaType === "text/tab-separated-values" || ext === "tsv") return "tsv";
  if (mediaType === "application/json" || ext === "json") return "json";
  if (/xml/.test(mediaType) || ext === "xml") return "xml";
  return "text";
}

export function TextView({ text, kind }: { text: string; kind: string }) {
  if (kind === "markdown") return <Markdown text={text} />;
  if (kind === "csv" || kind === "tsv") return <Sheet text={text} sep={kind === "csv" ? "," : "\t"} />;
  if (kind === "json" || kind === "xml") {
    let pretty = text;
    if (kind === "json") {
      try {
        pretty = JSON.stringify(JSON.parse(text), null, 2);
      } catch {}
    }
    return (
      <pre className="overflow-x-auto rounded-[10px] bg-surface p-3.5 font-mono text-[12.5px] leading-relaxed text-fg-2">
        <code>{highlight(pretty, kind === "json" ? "json" : "xml")}</code>
      </pre>
    );
  }
  return (
    <div className="text-[14px] leading-[1.7] whitespace-pre-wrap text-fg-2">
      {text.split("\n").map((l, i) => (
        <Fragment key={i}>
          {i > 0 && "\n"}
          {l}
        </Fragment>
      ))}
    </div>
  );
}

// The components Snap can choose from. Each has one line for Snap (what it's for), a JSON schema for the writer
// (what goes in it) and, where it matters, a rule for the writer (where the data may come from). Schemas follow
// SubQ's structured-output rules: every property required, additionalProperties false on every object.
// The descriptions are what Snap tells them apart by: when it picks wrong, sharpen these first.

type Schema = Record<string, unknown>;

const str = (description?: string): Schema => (description ? { type: "string", description } : { type: "string" });
const bool = (description: string): Schema => ({ type: "boolean", description });
const num = (description: string): Schema => ({ type: "number", description });
const int = (description: string): Schema => ({ type: "integer", description });
const oneOf = (values: string[], description?: string): Schema => ({ type: "string", enum: values, ...(description && { description }) });
const arr = (items: Schema, description?: string): Schema => ({ type: "array", items, ...(description && { description }) });
const obj = (properties: Record<string, Schema>): Schema => ({
  type: "object",
  properties,
  required: Object.keys(properties),
  additionalProperties: false,
});

const artifactRef = str('An artifact id from the conversation, like "a3", or "" when none fits.');

export const blocks = {
  text: {
    label: "Text",
    snap: "Plain prose. Conversation, explanations, opinions, short answers. The default when structure would not help.",
    schema: null,
  },
  comparison: {
    label: "Comparison",
    snap: "Choosing among several options, or picking a few of them: the candidates side by side with their images, points for and against, and which to pick.",
    schema: obj({
      options: arr(
        obj({
          title: str(),
          artifact: artifactRef,
          summary: str("One sentence."),
          points: arr(obj({ text: str("A few words."), good: bool("True for a point in favour.") })),
          picked: bool("True for the options you recommend."),
        }),
      ),
      footnote: str("One short line on how you chose, or \"\"."),
    }),
  },
  gallery: {
    label: "Gallery",
    snap: "Show images or files already shared in the conversation, each with a short caption.",
    schema: obj({
      items: arr(obj({ artifact: artifactRef, title: str(), caption: str("One short sentence.") })),
    }),
  },
  timeline: {
    label: "Timeline",
    snap: "Events in order over time: a history, how something evolved, a schedule.",
    schema: obj({
      events: arr(obj({ when: str("A short date or time label."), title: str(), detail: str("One sentence.") })),
    }),
  },
  checklist: {
    label: "Checklist",
    snap: "Tasks or requirements with done and not done: what's left, a launch list, a packing list.",
    schema: obj({
      title: str(),
      items: arr(obj({ text: str(), done: bool("True when the conversation says it's finished."), note: str('A few words, or "".') })),
    }),
  },
  decision: {
    label: "Decision",
    snap: "A yes or no answer to a single should-I question, with the reasons and a caveat. Not for choosing among several options.",
    schema: obj({
      question: str("The question, restated in a few words."),
      answer: oneOf(["yes", "no", "depends"], "The short answer."),
