import type { Artifact, Conversation } from "./types";

// Files as they come in: images are scaled down in the browser (requests stay small and Snap only needs to see
// them), text documents are read as text so Snap can read them too, PDFs travel as base64 for the writer.

const MAX_SIDE = 1280;
const MAX_DOC_BYTES = 3 * 1024 * 1024;

export const TEXT_TYPES: Record<string, string> = {
  md: "text/markdown",
  markdown: "text/markdown",
  txt: "text/plain",
  csv: "text/csv",
  tsv: "text/tab-separated-values",
  json: "application/json",
  xml: "application/xml",
};

export const ACCEPT = "image/png,image/jpeg,image/webp,image/gif,.pdf,.md,.markdown,.txt,.csv,.tsv,.json,.xml";

async function downscale(file: File): Promise<{ src: string; bytes: number }> {
  const bitmap = await createImageBitmap(file);
  const scale = Math.min(1, MAX_SIDE / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(bitmap.width * scale);
  canvas.height = Math.round(bitmap.height * scale);
  canvas.getContext("2d")!.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  bitmap.close();
  const blob = await new Promise<Blob>((resolve, reject) =>
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("encode"))), "image/webp", 0.85),
  );
  return { src: await dataUrl(blob), bytes: blob.size };
}

const dataUrl = (blob: Blob) =>
  new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });

/** Turns a dropped or picked file into an artifact, or explains why it can't. */
export async function readFile(file: File, id: string): Promise<Artifact | { error: string }> {
  const ext = file.name.split(".").pop()?.toLowerCase() ?? "";
  if (file.type.startsWith("image/")) {
    try {
      const { src, bytes } = await downscale(file);
      return { id, kind: "image", name: file.name, mediaType: "image/webp", src, bytes };
    } catch {
      return { error: `Couldn't read ${file.name} as an image.` };
    }
  }
  if (file.size > MAX_DOC_BYTES) return { error: `${file.name} is over 3 MB. Try a smaller file.` };
  if (ext in TEXT_TYPES) {
    return { id, kind: "doc", name: file.name, mediaType: TEXT_TYPES[ext], text: await file.text(), bytes: file.size };
  }
  if (ext === "pdf") {
    const url = await dataUrl(file);
    return { id, kind: "doc", name: file.name, mediaType: "application/pdf", base64: url.slice(url.indexOf(",") + 1), bytes: file.size };
  }
  return { error: `${file.name} isn't a file this chat reads. Images, PDF, Markdown, text, CSV and JSON work.` };
}

const base64Cache = new Map<string, string>();

/** Plain base64 without the data: prefix, the way Snap wants it. Public paths are fetched once. */
async function toBase64(src: string): Promise<string> {
  if (src.startsWith("data:")) return src.slice(src.indexOf(",") + 1);
  const cached = base64Cache.get(src);
  if (cached) return cached;
  const url = await dataUrl(await (await fetch(src)).blob());
  const b64 = url.slice(url.indexOf(",") + 1);
  base64Cache.set(src, b64);
  return b64;
}

export async function imagePayload(a: Artifact) {
  return { id: a.id, mediaType: a.mediaType, base64: await toBase64(a.src!) };
}

/**
 * Snap looks at up to four images a turn. The rest it knows by name, caption and tags. Pick the ones
 * attached right now, then the ones it chose last time, then the newest.
 */
export function pickImages(conv: Conversation, attached: string[]): Artifact[] {
  const isImage = (id: string) => conv.artifacts[id]?.kind === "image";
  const lastChosen = [...conv.messages].reverse().find((m) => m.turn?.decision?.artifacts.length)?.turn?.decision?.artifacts ?? [];
  const shared = conv.messages.flatMap((m) => m.artifacts ?? []).reverse();
  const order = [...attached, ...lastChosen, ...shared].filter(isImage);
  return [...new Set(order)].slice(0, 4).map((id) => conv.artifacts[id]);
}

/** A rough count for before Snap has measured anything: about four characters a token, ~200 per image. */
export function estimateTokens(conv: Conversation) {
  const used = new Set(conv.messages.flatMap((m) => m.artifacts ?? []));
  let chars = 0;
  for (const m of conv.messages) chars += m.text.length + (m.data ? JSON.stringify(m.data).length : 0);
  let tokens = Math.round(chars / 4);
  for (const id of used) {
    const a = conv.artifacts[id];
    if (!a) continue;
    tokens += a.kind === "image" ? 200 : Math.round((a.text?.length ?? a.bytes / 2) / 4);
  }
  return tokens;
}

import "server-only";
import type { RepoFile, RepoListing } from "./sources";

// Reading a public GitHub repository: one call for the repository, one for its whole tree, then the chosen files
// straight from raw.githubusercontent.com. No clone, no archive. GITHUB_TOKEN in .env.local is optional: it raises
// GitHub's limit of 60 listings an hour and lets the listing see private repositories.

const API = "https://api.github.com";

export class GithubError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

const headers = () => ({
  Accept: "application/vnd.github+json",
  "User-Agent": "snap-chat",
  ...(process.env.GITHUB_TOKEN && { Authorization: `Bearer ${process.env.GITHUB_TOKEN}` }),
});

/** "owner/repo", a github.com link, or a link into a branch or folder. */
export function parseRepo(input: string) {
  const clean = input
    .trim()
    .replace(/^git@github\.com:/, "")
    .replace(/^(https?:\/\/)?(www\.)?github\.com\//, "")
    .replace(/[?#].*$/, "")
    .replace(/\.git$/, "")
    .replace(/\/+$/, "");
  const [owner, repo, kind, ref, ...rest] = clean.split("/");
  const ok = /^[\w.-]+$/;
  if (!owner || !repo || !ok.test(owner) || !ok.test(repo)) return null;
  const deep = kind === "tree" || kind === "blob";
  return { owner, repo, ref: deep && ref ? ref : undefined, path: deep ? rest.join("/") : "" };
}

const TEXT = new Set(
  "ts tsx js jsx mjs cjs json jsonc md mdx txt rst css scss sass less html htm vue svelte astro py rb go rs java kt kts swift c h cc cpp hpp cs php sh bash zsh fish ps1 yml yaml toml ini cfg conf env sql graphql gql prisma proto tf lua dart ex exs erl hs ml scala clj r jl zig nim sol gradle cmake xml".split(
    " ",
  ),
);
const NAMES = new Set(["dockerfile", "makefile", "readme", "justfile", "procfile", "gemfile", "rakefile", "cmakelists.txt"]);
const SKIP_DIR = /(^|\/)(node_modules|\.git|dist|build|out|\.next|\.nuxt|\.turbo|vendor|coverage|__snapshots__|\.yarn|target|\.venv|venv|__pycache__|\.idea|\.vscode|bower_components|Pods)(\/|$)/;
const SKIP_FILE = /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|Cargo\.lock|poetry\.lock|composer\.lock|Gemfile\.lock|go\.sum|uv\.lock)$|\.(min\.(js|css)|map|snap|lock)$/;
/** A single file bigger than this is almost always data or generated. */
const MAX_FILE_BYTES = 150_000;

function readable(f: RepoFile) {
  if (f.size === 0 || f.size > MAX_FILE_BYTES || SKIP_DIR.test(f.path) || SKIP_FILE.test(f.path)) return false;
  const name = f.path.split("/").pop()!.toLowerCase();
  const ext = name.includes(".") ? name.split(".").pop()! : "";
  return ext ? TEXT.has(ext) : NAMES.has(name);
}

async function api<T>(path: string, signal?: AbortSignal): Promise<T> {
  const res = await fetch(API + path, { headers: headers(), signal });
  if (res.ok) return res.json() as Promise<T>;
  if (res.status === 404) throw new GithubError("Couldn't find that repository. Check the name; a private one needs GITHUB_TOKEN in .env.local.", 404);
  if (res.status === 403 || res.status === 429) {
    const reset = Number(res.headers.get("x-ratelimit-reset"));
    const mins = reset ? Math.max(1, Math.ceil((reset * 1000 - Date.now()) / 60000)) : 0;
    throw new GithubError(`GitHub's hourly limit is used up${mins ? `. Try again in ${mins} min` : ""}, or add GITHUB_TOKEN to .env.local.`, 429);
  }
  if (res.status === 409) throw new GithubError("That repository is empty.", 409);
  throw new GithubError(`GitHub returned ${res.status}.`, res.status);
}

export async function listRepo(input: string, signal?: AbortSignal): Promise<RepoListing> {
  const parsed = parseRepo(input);
  if (!parsed) throw new GithubError("That doesn't look like a repository. Try owner/name, or paste a github.com link.", 400);
  const { owner, repo } = parsed;
  const info = await api<{ default_branch: string; description: string | null; stargazers_count: number; full_name: string }>(`/repos/${owner}/${repo}`, signal);
  const ref = parsed.ref ?? info.default_branch;
  const tree = await api<{ tree: { path: string; type: string; size?: number }[]; truncated: boolean }>(
    `/repos/${owner}/${repo}/git/trees/${encodeURIComponent(ref)}?recursive=1`,
    signal,
  );
  const prefix = parsed.path ? `${parsed.path}/` : "";
  const blobs = tree.tree.filter((t) => t.type === "blob" && (!prefix || t.path.startsWith(prefix) || t.path === parsed.path)).map((t) => ({ path: t.path, size: t.size ?? 0 }));
  const files = blobs.filter(readable);
  const [realOwner, realRepo] = info.full_name.split("/");
  return {
    owner: realOwner,
    repo: realRepo,
    ref,
    path: parsed.path,
    description: info.description ?? "",
    stars: info.stargazers_count,
    files,
    skipped: blobs.length - files.length,
    truncated: tree.truncated,
  };
}

/** The text of the chosen files. One that can't be read (gone, binary after all) is simply left out. */
export async function fetchFiles(input: { owner: string; repo: string; ref: string; paths: string[] }, signal?: AbortSignal) {
  const ok = /^[\w.-]+$/;
  if (!ok.test(input.owner) || !ok.test(input.repo)) throw new GithubError("That doesn't look like a repository.", 400);
  const base = `https://raw.githubusercontent.com/${input.owner}/${input.repo}/${encodeURIComponent(input.ref)}/`;
  const got = await Promise.all(
    input.paths.slice(0, 60).map(async (path) => {
      try {
        const res = await fetch(base + path.split("/").map(encodeURIComponent).join("/"), {
          headers: process.env.GITHUB_TOKEN ? { Authorization: `Bearer ${process.env.GITHUB_TOKEN}` } : undefined,
          signal,
        });
        if (!res.ok) return null;
        const text = await res.text();
        return text.includes("\u0000") ? null : { path, text };
      } catch {
        return null;
      }
    }),
  );
  return got.filter((f): f is { path: string; text: string } => !!f);
}

// Shared motion language. Values come from Emil Kowalski's and Jakub Krehel's
// guidance; use these instead of inventing new curves or scales.

/** Strong ease-out for anything entering, exiting or responding to input. */
export const easeOut = [0.23, 1, 0.32, 1] as const;

/** Strong ease-in-out for elements moving on screen. */
export const easeInOut = [0.77, 0, 0.175, 1] as const;

/** Press feedback for every pressable element. Never below 0.95. */
export const press = { scale: 0.96 } as const;

/** Contextual icon swap: scale 0.25 → 1, blur 4px → 0, spring with no bounce. */
export const iconSwap = {
  initial: { opacity: 0, scale: 0.25, filter: "blur(4px)" },
  animate: { opacity: 1, scale: 1, filter: "blur(0px)" },
  exit: { opacity: 0, scale: 0.25, filter: "blur(4px)" },
  transition: { type: "spring", duration: 0.3, bounce: 0 },
} as const;

/**
 * A piece's own controls arriving (toolbars, captions, hints): up from 12px lower, out of a 6px blur, slowly.
 * Pass a delay to stagger the parts that arrive together.
 */
export const riseIn = (delay = 0) =>
  ({
    initial: { opacity: 0, y: 12, filter: "blur(6px)" },
    animate: { opacity: 1, y: 0, filter: "blur(0px)" },
    transition: { duration: 0.55, ease: easeOut, delay },
  }) as const;

/** `riseIn` as variants (hidden → shown), for an arrival that waits on a condition. The whole thing moves as one. */
export const rise = {
  hidden: { opacity: 0, y: 12, filter: "blur(6px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: 0.55, ease: easeOut } },
} as const;

/**
 * The same arrival for a bar whose items should come up one after another: put `riseGroup` on the bar
 * (initial="hidden", animate="shown") and `riseItem` on each item.
 */
export const riseGroup = {
  hidden: { opacity: 0, y: 12, filter: "blur(6px)" },
  shown: {
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: { duration: 0.55, ease: easeOut, staggerChildren: 0.04, delayChildren: 0.06 },
  },
} as const;

export const riseItem = {
  hidden: { opacity: 0, y: 10, filter: "blur(4px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: 0.5, ease: easeOut } },
} as const;

/**
 * Something already on screen moving to a new place: a tooltip following the pointer, a crosshair, rows settling
 * into a new order, a map recentring. A spring with no bounce, so it can be redirected mid-way without a jolt.
 */
export const glide = { type: "spring", duration: 0.3, bounce: 0 } as const;

/** Full-width rows don't scale on press (it reads as a bounce); they darken a touch while held instead. */
export const rowPress = "active:bg-white/[0.07] transition-colors duration-150";

/** A small control's press: slighter than `press`, for checks and dots. */
export const tap = { scale: 0.9 } as const;

import "server-only";
import type { PageResult } from "./sources";

// Reading a web page: fetched here on the server and boiled down to its words. No browser, no scripts run: a page
// that only exists after its JavaScript runs comes back nearly empty, and the dialog says so.

export class PageError extends Error {}

const MAX_CHARS = 400_000;

/** Only public web addresses: nothing on this machine or the local network. */
function allowed(url: URL) {
  if (url.protocol !== "http:" && url.protocol !== "https:") return false;
  const h = url.hostname.toLowerCase();
  if (h === "localhost" || h.endsWith(".local") || h.endsWith(".internal") || h === "[::1]") return false;
  if (/^(127\.|10\.|192\.168\.|169\.254\.|0\.)/.test(h) || /^172\.(1[6-9]|2\d|3[01])\./.test(h)) return false;
  return true;
}

const ENTITIES: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", mdash: ", ", ndash: "-", hellip: "...", rsquo: "'", lsquo: "'", rdquo: '"', ldquo: '"' };
const decode = (s: string) =>
  s
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&([a-z]+);/gi, (m, n) => ENTITIES[n.toLowerCase()] ?? m);

/** HTML down to readable text: headings and list items kept as Markdown, everything else as paragraphs. */
export function htmlToText(html: string) {
  const title = decode(html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]?.trim() ?? "");
  // the article or main part when the page marks one, so menus and footers stay out
  const body = html.match(/<(article|main)\b[\s\S]*<\/\1>/i)?.[0] ?? html.match(/<body\b[\s\S]*<\/body>/i)?.[0] ?? html;
  const text = decode(
    body
      .replace(/<!--[\s\S]*?-->/g, "")
      .replace(/<(script|style|noscript|svg|nav|footer|header|form|iframe|template)\b[\s\S]*?<\/\1>/gi, "")
      .replace(/<h([1-6])[^>]*>/gi, (_, n) => `\n\n${"#".repeat(Number(n))} `)
      .replace(/<li[^>]*>/gi, "\n- ")
      .replace(/<(br|hr)[^>]*>/gi, "\n")
      .replace(/<\/(p|div|section|article|tr|table|ul|ol|h[1-6]|pre|blockquote)>/gi, "\n\n")
      .replace(/<\/(td|th)>/gi, "  ")
      .replace(/<\/?[a-zA-Z][^>"']*(?:(?:"[^"]*"|'[^']*')[^>"']*)*>/g, ""),
  )
    .replace(/^[ \t]*-[ \t]*$/gm, "")
    .replace(/[ \t]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return { title, text };
}

export async function readPage(input: string, signal?: AbortSignal): Promise<PageResult> {
  let url: URL;
  try {
    url = new URL(/^https?:\/\//i.test(input.trim()) ? input.trim() : `https://${input.trim()}`);
  } catch {
    throw new PageError("That doesn't look like a web address.");
  }
  if (!allowed(url)) throw new PageError("Only public web pages can be read.");
  let res: Response;
  try {
    res = await fetch(url, { headers: { "User-Agent": "Mozilla/5.0 (compatible; snap-chat)", Accept: "text/html,text/plain,text/markdown;q=0.9,*/*;q=0.5" }, redirect: "follow", signal });
  } catch {
    throw new PageError("Couldn't reach that page.");
  }
  if (!res.ok) throw new PageError(`That page returned ${res.status}.`);
  const type = res.headers.get("content-type") ?? "";
  if (!/text\/|json|xml/.test(type)) throw new PageError("That address isn't a page of text.");
  const raw = (await res.text()).slice(0, 3_000_000);
  const { title, text } = /html/.test(type) ? htmlToText(raw) : { title: "", text: raw };
  if (text.length < 200) throw new PageError("That page has almost no text to read. It may need JavaScript to show anything.");
  return { url: res.url || url.href, title: title || url.hostname, text: text.slice(0, MAX_CHARS) };
}

import "server-only";
import { extractText, getDocumentProxy } from "unpdf";
import type { TurnRequest } from "./types";

// PDFs become text on the server, page by page, before Snap or the writer see them. Not every writer takes a PDF
// (the free OpenRouter model rejects one outright), and Snap only reads text, so this way the whole PDF is in
// context for both, the same as a Markdown file. Extracted once per file and kept while the server runs.

const MAX_CHARS = 600_000; // about 150k tokens: room left for the conversation in Snap's window
const cache = new Map<string, string>();

async function pdfText(base64: string): Promise<string> {
  const key = `${base64.length}:${base64.slice(0, 48)}:${base64.slice(-48)}`;
  const hit = cache.get(key);
  if (hit !== undefined) return hit;
  let text = "";
  try {
    const pdf = await getDocumentProxy(new Uint8Array(Buffer.from(base64, "base64")));
    const { text: pages } = await extractText(pdf, { mergePages: false });
    text = pages
      .map((p, i) => ({ p: p.trim(), i }))
      .filter(({ p }) => p)
      .map(({ p, i }) => `[page ${i + 1}]\n${p}`)
      .join("\n\n");
  } catch {
    text = "";
  }
  const out = text
    ? text.slice(0, MAX_CHARS)
    : "(This PDF has no text that can be read: it is probably a scan or images only. Say so if asked about its contents.)";
  cache.set(key, out);
  return out;
}

/** Fills in the text of every PDF in the turn that doesn't have it yet. */
export async function withPdfText(req: TurnRequest): Promise<TurnRequest> {
  const artifacts = await Promise.all(
    req.artifacts.map(async (a) =>
      a.kind === "doc" && a.mediaType === "application/pdf" && a.text == null && a.base64 ? { ...a, text: await pdfText(a.base64), base64: undefined } : a,
    ),
  );
  return { ...req, artifacts };
}

import "server-only";
import { blocks, writerRule } from "./blocks";
import type { ChatMessage, ContentPart, Writer } from "./subq";
import type { Decision, TurnRequest } from "./types";

// The writer gets the whole conversation as it happened and Snap's decision. Documents are different: Snap has
// read every one of them, and the writer gets only those Snap picked for this reply plus any attached to the newest
// message (file parts for SubQ, their text for the others). That is what lets a chat hold hundreds of thousands of
// tokens of files: the decision model reads them all, the writer reads the two that matter. A writer that can see
// also gets the images Snap looked at this turn; anything else reaches it as Snap's tags and any caption.

const DEPTH = [
  "one line",
  "two or three sentences",
  "a short paragraph or two",
  "as long as it needs, but no padding",
];

const IMAGE_KINDS: Record<string, string> = {
  ui_screenshot: "an interface screenshot",
  chart: "a chart",
  photo: "a photo",
  illustration: "an illustration or render",
  document: "a page or slide",
  diagram: "a diagram",
  other: "an image",
};

function describe(a: TurnRequest["artifacts"][number]) {
  if (a.kind === "doc") return `[the file "${a.name}" (id ${a.id}), attached]`;
  const parts = [`[${a.id}: image "${a.name}"`];
  if (a.caption) parts.push(a.caption);
  if (a.tags) {
    parts.push(
      `Snap says ${IMAGE_KINDS[a.tags.kind] ?? "an image"}, ${a.tags.dark > 0.5 ? "dark" : "light"}${a.tags.hasText > 0.5 ? ", with readable text" : ""}`,
    );
  }
  return `${parts.join(". ")}]`;
}

function base64(text: string) {
  return Buffer.from(text, "utf8").toString("base64");
}

function files(req: TurnRequest, ids: string[] | undefined, docs: Writer["docs"]): ContentPart[] {
  return (ids ?? []).flatMap((id): ContentPart[] => {
    const a = req.artifacts.find((x) => x.id === id);
    if (!a || a.kind !== "doc") return [];
    if (docs === "text") {
      if (a.text != null) return [{ type: "text", text: `The file "${a.name}" (id ${a.id}):\n\n${a.text}` }];
      // PDFs go in as inline data, which Gemini reads
      return a.base64 ? [{ type: "image_url", image_url: { url: `data:${a.mediaType};base64,${a.base64}` } }] : [];
    }
    const data = a.text != null ? base64(a.text) : a.base64;
    if (!data) return [];
    return [{ type: "file", filename: a.name, mime_type: a.mediaType, file_data: data }];
  });
}

export function writerMessages(req: TurnRequest, decision: Decision, w: Pick<Writer, "vision" | "docs">): ChatMessage[] {
  const block = blocks[decision.component];
  const recalled = decision.recall ? req.messages.find((m) => m.id === decision.recall) : undefined;
  const recalledNumber = recalled ? req.messages.indexOf(recalled) + 1 : 0;
  const picked = decision.artifacts.map((id) => req.artifacts.find((a) => a.id === id)).filter(Boolean);
  const extras = decision.extras ?? [];
  const newest = req.messages[req.messages.length - 1];
  // the documents the writer reads: the ones Snap picked, and the ones that just arrived
  const wanted = new Set([...decision.artifacts, ...(newest.artifacts ?? [])]);
  const isDoc = (id: string) => req.artifacts.find((a) => a.id === id)?.kind === "doc";

  const system = [
    "You write replies in a chat. A fast decision model, SubQ Snap, has already read the whole conversation and chosen how this reply is shown. Follow its choice.",
    `Snap chose: ${block.label}. ${block.snap}`,
    block.schema
      ? 'Reply with JSON: "text" is the prose shown above the component, "data" fills the component. Write "text" first.'
      : "Reply in plain prose.",
    writerRule(decision.component) ?? "",
    extras.length
      ? `The user asked for more than one kind of thing, so Snap chose ${extras.length === 1 ? "one more component" : `${extras.length} more components`} for the same reply, shown under the ${block.label}: ${extras
          .map((id) => `"${extraKey(id)}" fills a ${blocks[id].label} (${blocks[id].snap})`)
          .join("; ")}. Fill every one. Each shows a different part of the answer: don't put the same content in two of them, and keep each to what was asked for.`
      : "",
    ...extras.map((id) => writerRule(id) ?? ""),
    `Length of the prose: ${DEPTH[decision.depth] ?? DEPTH[1]}. When there is a component, the prose introduces it and does not repeat it, and every number or count in the prose must match the component's data exactly.`,
    recalled
      ? `Snap found that this reply may depend on message ${recalledNumber}, from the ${recalled.role}: "${recalled.text}". Respect it. Mention it only when it changes the answer, and then say plainly that you're going by it.`
      : "",
    picked.length
      ? `Snap picked these artifacts for this reply, most relevant first: ${picked.map((a) => describe(a!)).join(" ")}. Use their ids exactly where the component asks for an artifact.`
      : "",
    w.vision && req.images.length
      ? `You can see the images attached to the newest message: ${req.images.map((i) => i.id).join(", ")}, each labelled with its id. Describe only what you can actually see in them.`
      : "",
    "In your prose, call a file by its name (src/lib/x.ts), never by its id and never as \"document a21\": ids are only for component fields that ask for an artifact.",
    "When the user asks for a number of things (three questions, five ideas), give exactly that many.",
    "Write plainly: no hype, no em dashes, no headings. Markdown is limited to **bold**, `code` and simple - lists.",
  ]
    .filter(Boolean)
    .join("\n\n");

  const history: ChatMessage[] = req.messages.map((m, i) => {
    const notes = (m.artifacts ?? [])
      .map((id) => req.artifacts.find((a) => a.id === id))
      .filter((a) => a?.kind === "image")
      .map((a) => describe(a!));
    const shown =
      (m.component && m.component !== "text" ? `\n\n(Shown as ${blocks[m.component].label}: ${JSON.stringify(m.data)})` : "") +
      (m.extras ?? []).map((e) => `\n\n(Also shown as ${blocks[e.component].label}: ${JSON.stringify(e.data)})`).join("");
    const docs = (m.artifacts ?? []).filter(isDoc);
    const skipped = docs.filter((id) => !wanted.has(id));
    // What wasn't attached is still named, so the writer knows what exists (a repository's layout, say).
    const names = skipped.map((id) => req.artifacts.find((a) => a.id === id)!.name);
    const listed = names.join(", ").length <= 9000 ? names.join(", ") : `${names.slice(0, 250).join(", ")} and ${names.length - 250} more`;
    const unread = skipped.length
      ? `\n\n(${skipped.length === docs.length ? "" : "Also "}shared here but not attached, because Snap read ${skipped.length === 1 ? "it" : "them"} and judged this reply doesn't need the contents: ${listed}.)`
      : "";
    const text = `${m.text}${notes.length ? `\n\n${notes.join("\n")}` : ""}${unread}${shown}`;
    const attached: ContentPart[] = m.role === "user" ? files(req, m.artifacts?.filter((id) => wanted.has(id)), w.docs) : [];
    // The newest message carries the images Snap looked at, for a writer that can see.
    if (w.vision && i === req.messages.length - 1) {
      for (const img of req.images) {
        attached.push({ type: "text", text: `Image ${img.id}:` }, { type: "image_url", image_url: { url: `data:${img.mediaType};base64,${img.base64}` } });
      }
    }
    const label = `[message ${i + 1}] `;
    return attached.length
      ? { role: m.role, content: [{ type: "text", text: label + text }, ...attached] }
      : { role: m.role, content: m.role === "user" ? label + text : text };
  });

  return [{ role: "system", content: system }, ...history];
}

/** Where an extra component's data goes in the writer's JSON. */
export const extraKey = (id: string) => `data_${id}`;

export function replySchema(decision: Decision) {
  const schema = blocks[decision.component].schema;
  if (!schema) return undefined;
  const extras = (decision.extras ?? []).filter((id) => blocks[id].schema);
  return {
    type: "object",
    properties: { text: { type: "string" }, data: schema, ...Object.fromEntries(extras.map((id) => [extraKey(id), blocks[id].schema])) },
    required: ["text", "data", ...extras.map(extraKey)],
    additionalProperties: false,
  };
}

