// What can be brought into a chat from outside it, and what fits. Shared by the server (which fetches) and the
// dialog (which shows the numbers before anything is added).

/** One file in a repository's listing: its path and its size in bytes. */
export type RepoFile = { path: string; size: number };

export type RepoListing = {
  owner: string;
  repo: string;
  ref: string;
  /** The folder the link pointed into, if it did. */
  path: string;
  description: string;
  stars: number;
  /** The files this chat can read: text and code, small enough, not generated. */
  files: RepoFile[];
  /** Files left out: binaries, lockfiles, build output, anything too big. */
  skipped: number;
  /** GitHub cut the listing short (a very large repository). */
  truncated: boolean;
};

export type PageResult = { url: string; title: string; text: string };

/** Snap ranks at most this many files in one choice. */
export const MAX_FILES = 250;
/** Code runs about three characters a token (measured: this app's source, 412k characters, 137k tokens). */
export const CHARS_PER_TOKEN = 3;
export const tokensOf = (chars: number) => Math.round(chars / CHARS_PER_TOKEN);

import "server-only";

// The two models, over plain fetch. Snap lives on SubQ's Decisions API (its own typed contract). The writer speaks
// OpenAI-compatible Chat Completions: Gemini while subq-preview is in early access (it sees images too), or
// subq-preview itself with WRITER=subq. Docs: https://docs.subq.ai, https://ai.google.dev/gemini-api/docs/openai

// SUBQ_BASE_URL is only for pointing at a local stand-in while testing.
const BASE = process.env.SUBQ_BASE_URL ?? "https://api.subq.ai/v1";
export const SNAP = "subq-snap-preview";

/** Who writes the reply, and what it can take in. */
export type Writer = {
  name: "openrouter" | "gemini" | "subq";
  label: string;
  base: string;
  model: string;
  /** Models to fall back to, in order, when the first is busy (OpenRouter routes these itself). */
  fallbacks?: string[];
  envKey: string;
  vision: boolean;
  docs: "file" | "text";
};

export function writer(): Writer {
  const choice =
    process.env.WRITER ?? (process.env.OPENROUTER_API_KEY ? "openrouter" : process.env.GEMINI_API_KEY ? "gemini" : "subq");
  if (choice === "openrouter") {
    return {
      name: "openrouter",
      label: "OpenRouter",
      base: "https://openrouter.ai/api/v1",
      // Free models with JSON-schema output, measured on the 30k-token demo's launch checklist: dots 3 note was
      // right (3 of 6 done) in 5s and takes images; Nemotron 3 Super answered in 6.5s but only listed what was left.
      model: process.env.OPENROUTER_MODEL ?? "dots-studio/dots-3-note-preview:free",
      fallbacks: ["nvidia/nemotron-3-super-120b-a12b:free"],
      envKey: "OPENROUTER_API_KEY",
      vision: true,
      docs: "text",
    };
  }
  if (choice === "gemini") {
    return {
      name: "gemini",
      label: "Gemini",
      base: "https://generativelanguage.googleapis.com/v1beta/openai",
      // 3.6 flash: measured 4 to 5s on the 30k-token demo; 3.7 and 3.8 took 45 to 53s for the same reply.
      model: process.env.GEMINI_MODEL ?? "gemini-3.6-flash",
      envKey: "GEMINI_API_KEY",
      vision: true,
      docs: "text",
    };
  }
  return { name: "subq", label: "SubQ", base: BASE, model: "subq-preview", envKey: "SUBQ_API_KEY", vision: false, docs: "file" };
}

export class SubqError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

function key(env = "SUBQ_API_KEY") {
  const k = process.env[env];
  if (!k) throw new SubqError(`Add ${env} to .env.local, then restart the server.`, 0);
  return k;
}

const headers = (env?: string) => ({ Authorization: `Bearer ${key(env)}`, "Content-Type": "application/json" });

/** The useful part of a provider's raw error, which is often JSON inside a string. */
function providerReason(raw: unknown): string {
  if (typeof raw !== "string") return "";
  try {
    const j = JSON.parse(raw);
    const m = j?.error?.message ?? j?.message ?? j?.detail ?? "";
    return typeof m === "string" ? m.slice(0, 220) : "";
  } catch {
    return raw.slice(0, 220);
  }
}

/** One plain sentence per failure, with what to do about it. */
async function fail(res: Response, model: string, who: { label: string; envKey: string } = { label: "SubQ", envKey: "SUBQ_API_KEY" }): Promise<never> {
  let detail = "";
  try {
    const body = await res.json();
    detail = body?.detail?.message ?? body?.error?.message ?? body?.[0]?.error?.message ?? "";
    // OpenRouter wraps the provider's own reason in metadata.raw; "Provider returned error" alone says nothing.
    const raw = body?.error?.metadata?.raw;
    if (raw) detail = providerReason(raw) || detail;
  } catch {}
  const message =
    {
      401: `${who.label} didn't accept the API key. Check ${who.envKey} in .env.local.`,
      402: `The ${who.label} account is out of credits.`,
      403:
        who.label === "SubQ"
          ? `This key can't use ${model} yet.${model === "subq-preview" ? " It's in early access: request it at console.subq.ai." : ""}`
          : `${who.label} didn't allow this key to use ${model}. Check ${who.envKey}.`,
      429:
        who.label === "OpenRouter"
          ? "OpenRouter's free models are busy, or the free daily limit is used up. Try again shortly, or add credits at openrouter.ai."
          : `${who.label} is rate limiting. Try again in a moment.`,
      503: `${who.label} is briefly unavailable. Try again in a moment.`,
    }[res.status] ?? (detail ? `${who.label} said: ${detail}` : `${who.label} returned ${res.status}.`);
  throw new SubqError(message, res.status);
}

/* ---------- Snap: decisions ---------- */

export type Question =
  | { type: "noul"; instructions: string; criteria?: { true: string; false: string } }
  | { type: "choice"; instructions: string; criteria: Record<string, string | null> }
  | { type: "score"; instructions: string; criteria: string[] };

export type Answer =
  | { type: "noul"; noul: number }
  | { type: "choice"; choice: string; probabilities: Record<string, number>; confidence: number }
  | { type: "score"; score: number; legend: Record<string, string>; probabilities: Record<string, number>; confidence: number };

export type DecideResult = { answers: Record<string, Answer>; usage: { input_tokens: number; output_tokens: number }; ms: number };

export async function decide(input: {
  state: unknown;
  questions: Record<string, Question>;
  images?: { mediaType: string; base64: string }[];
  signal?: AbortSignal;
}): Promise<DecideResult> {
  const started = performance.now();
  const res = await fetch(`${BASE}/systemone`, {
    method: "POST",
    headers: headers(),
    body: JSON.stringify({
      model: SNAP,
      state: input.state,
      questions: input.questions,
      ...(input.images?.length && { images: input.images }),
    }),
    signal: input.signal,
  });
  if (!res.ok) await fail(res, SNAP);
  const body = await res.json();
  return { answers: body.answers, usage: body.usage, ms: Math.round(performance.now() - started) };
}

/* ---------- Writer: chat completions ---------- */

export type ContentPart =
  | { type: "text"; text: string }
  | { type: "file"; filename: string; mime_type: string; file_data: string }
  | { type: "image_url"; image_url: { url: string } };

export type ChatMessage = { role: "system" | "user" | "assistant"; content: string | ContentPart[] };

/**
 * Streams the writer's reply, calling `onText` with everything so far. With a schema, the reply is JSON.
 * If SubQ won't stream a schema-constrained reply, it asks once more without streaming.
 */
export async function write(input: {
  messages: ChatMessage[];
  schema?: Record<string, unknown>;
  onText: (soFar: string) => void;
  signal?: AbortSignal;
}): Promise<string> {
  const w = writer();
  const body = (stream: boolean) =>
    JSON.stringify({
      model: w.model,
      messages: input.messages,
      stream,
      ...(w.name === "openrouter"
        ? { models: [w.model, ...(w.fallbacks ?? [])], reasoning: { effort: "low" } }
        : // No bounded default: leaving this out lets the model reason at length before a single word arrives.
          { reasoning_effort: "low" }),
      ...(input.schema && {
        response_format: { type: "json_schema", json_schema: { name: "reply", strict: true, schema: input.schema } },
      }),
    });
  const post = (stream: boolean) =>
    fetch(`${w.base}/chat/completions`, {
      method: "POST",
      headers: { ...headers(w.envKey), ...(w.name === "openrouter" && { "X-Title": "chat" }) },
      body: body(stream),
      signal: input.signal,
    });

  let res = await post(true);
  // A momentary "busy" from the provider is retried once, quietly, before anyone sees it.
  if (res.status === 503 || res.status === 429) {
    await new Promise((r) => setTimeout(r, 1200));
    res = await post(true);
  }

  if (res.status === 400 && input.schema) {
    res = await post(false);
    if (!res.ok) await fail(res, w.model, w);
    const json = await res.json();
    const content: string = json.choices?.[0]?.message?.content ?? "";
    if (!content) throw new SubqError("The writer used its whole budget thinking and wrote nothing. Try again.", 200);
    input.onText(content);
    return content;
  }
  if (!res.ok || !res.body) await fail(res, w.model, w);

  let text = "";
  let finish: string | null = null;
  let buffer = "";
  const decoder = new TextDecoder();
  const reader = res.body!.getReader();
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";
    for (const line of lines) {
      if (!line.startsWith("data:")) continue;
      const data = line.slice(5).trim();
      if (!data || data === "[DONE]") continue;
      const event = JSON.parse(data);
      if (event.error) {
        const why = providerReason(event.error.metadata?.raw) || event.error.message || "the stream failed";
        throw new SubqError(`${w.label} said: ${why}`, Number(event.error.code) || 500);
      }
      const choice = event.choices?.[0];
      const delta: string | undefined = choice?.delta?.content;
      if (choice?.finish_reason) finish = choice.finish_reason;
      if (delta) {
        text += delta;
        input.onText(text);
      }
    }
  }
  if (!text && finish === "length") {
    throw new SubqError("The writer used its whole budget thinking and wrote nothing. Try again.", 200);
  }
  return text;
}

import type { BlockId } from "./blocks";

/** What Snap said about an image when it arrived: it can't caption, so it answers typed questions instead. */
export type ImageTags = {
  kind: string;
  dark: number;
  hasText: number;
  ms: number;
};

export type Artifact = {
  id: string;
  kind: "image" | "doc";
  name: string;
  mediaType: string;
  /** Images: a data URL or a public path. */
  src?: string;
  /** Written by hand for the demo; uploads only get Snap's tags. */
  caption?: string;
  tags?: ImageTags;
  /** Where it was brought in from, when not from this device: files from one repository share a label. */
  source?: { kind: "github" | "page"; label: string; url: string };
  /** Text documents (md, txt, csv, json): the text itself, so Snap sees it too. */
  text?: string;
  /** Binary documents (pdf): base64 for the writer. */
  base64?: string;
  bytes: number;
};

export type Decision = {
  component: BlockId;
  confidence: number;
  probabilities: Record<string, number>;
  /** Components Snap wants beside the main one, because the question asked for more than one kind of thing. */
  extras?: BlockId[];
  /** Snap's answer to "what else?", over every component and "none". */
  extraProbabilities?: Record<string, number>;
  /** The earlier message Snap says the reply depends on, or null. */
  recall: string | null;
  recallConfidence: number;
  /** Artifacts Snap wants shown or used, most likely first. */
  artifacts: string[];
  depth: number;
  ms: number;
  inputTokens: number;
  images: number;
};

export type Turn = {
  status: "deciding" | "writing" | "done" | "error";
  decision?: Decision;
  /** The component's data, filled in as it streams. */
  data?: unknown;
  error?: string;
  writeMs?: number;
  /** The model that wrote the reply, credited in "How Snap decided". */
  writer?: string;
};

export type Message = {
  id: string;
  role: "user" | "assistant";
  text: string;
  at: number;
  artifacts?: string[];
  /** Live assistant turns. Seeded demo replies have a component but no turn: Snap didn't make them. */
  turn?: Turn;
  component?: BlockId;
  data?: unknown;
  /** More components in the same reply, under the main one. */
  extras?: { component: BlockId; data?: unknown }[];
  seeded?: boolean;
};

export type Conversation = {
  /** Empty until the first message, so a blank new chat never lands in the history. */
  id: string;
  updatedAt: number;
  title: string;
  messages: Message[];
  artifacts: Record<string, Artifact>;
  /** Snap's last measured input, the honest number for the meter. */
  lastInputTokens?: number;
  /** Questions to try, offered above the composer (the demos set these). */
  suggestions?: string[];
};

/** A conversation as the sidebar lists it. */
export type Summary = { id: string; title: string; updatedAt: number; demo?: boolean };

/** What the browser sends for a turn. Images travel only when Snap will look at them. */
export type TurnRequest = {
  messages: Pick<Message, "id" | "role" | "text" | "at" | "artifacts" | "component" | "data" | "extras">[];
  artifacts: Omit<Artifact, "src">[];
  images: { id: string; mediaType: string; base64: string }[];
};

export type TurnEvent =
  | { type: "decision"; decision: Decision }
  | { type: "partial"; text: string; data?: unknown; extras?: unknown[] }
  | { type: "done"; text: string; data?: unknown; extras?: unknown[]; writeMs: number; writer?: string }
  | { type: "error"; message: string; stage: "decide" | "write" };

"use client";

import { del, get, set } from "idb-keyval";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";
import { estimateTokens, imagePayload, pickImages } from "./files";
import type { Artifact, Conversation, Decision, ImageTags, Message, Summary, TurnEvent, TurnRequest } from "./types";

// Every conversation is kept whole in IndexedDB under its own key; a small index lists them for the sidebar
// and remembers which one was open.

const INDEX_KEY = "snap-chat:index";
const convKey = (id: string) => `snap-chat:conv:${id}`;

type Index = { active: string | null; list: Summary[] };

export const empty = (): Conversation => ({ id: "", updatedAt: 0, title: "New conversation", messages: [], artifacts: {} });

type Action =
  | { type: "replace"; conv: Conversation }
  | { type: "attach"; artifact: Artifact }
  | { type: "detach"; id: string }
  | { type: "tag"; id: string; tags: ImageTags }
  | { type: "ask"; user: Message; assistant: Message; convId: string }
  | { type: "decision"; id: string; decision: Decision }
  | { type: "partial"; id: string; text: string; data?: unknown; extras?: unknown[] }
  | { type: "done"; id: string; text: string; data?: unknown; extras?: unknown[]; writeMs: number; writer?: string }
  | { type: "error"; id: string; message: string }
  | { type: "retry"; id: string }
  | { type: "data"; id: string; data: unknown; extra?: number };

/** The extra components' data as it streams in, each keeping what it had until more arrives. */
const fill = (m: Message, extras?: unknown[]) => m.extras?.map((e, i) => ({ ...e, data: extras?.[i] ?? e.data }));

function update(conv: Conversation, id: string, fn: (m: Message) => Message): Conversation {
  return { ...conv, messages: conv.messages.map((m) => (m.id === id ? fn(m) : m)) };
}

function reducer(conv: Conversation, action: Action): Conversation {
  switch (action.type) {
    case "replace":
      return action.conv;
    case "attach":
      return { ...conv, artifacts: { ...conv.artifacts, [action.artifact.id]: action.artifact } };
    case "detach": {
      const { [action.id]: _, ...rest } = conv.artifacts;
      return { ...conv, artifacts: rest };
    }
    case "tag": {
      const a = conv.artifacts[action.id];
      return a ? { ...conv, artifacts: { ...conv.artifacts, [a.id]: { ...a, tags: action.tags } } } : conv;
    }
    case "ask":
      return {
        ...conv,
        id: conv.id || action.convId,
        updatedAt: action.user.at,
        title: conv.messages.length ? conv.title : titleFrom(action.user.text),
        messages: [...conv.messages, action.user, action.assistant],
      };
    case "decision":
      return {
        ...update(conv, action.id, (m) => ({
          ...m,
          component: action.decision.component,
          ...(action.decision.extras?.length && { extras: action.decision.extras.map((component) => ({ component })) }),
          turn: { ...m.turn, status: "writing", decision: action.decision },
        })),
        lastInputTokens: action.decision.inputTokens,
      };
    case "partial":
      return update(conv, action.id, (m) => ({ ...m, text: action.text, data: action.data ?? m.data, extras: fill(m, action.extras) }));
    case "done":
      return update(conv, action.id, (m) => ({
        ...m,
        text: action.text,
        data: action.data ?? m.data,
        extras: fill(m, action.extras),
        turn: { ...m.turn, status: "done", writeMs: action.writeMs, writer: action.writer },
      }));
    case "error":
      return update(conv, action.id, (m) => ({ ...m, turn: { ...m.turn, status: "error", error: action.message } }));
    case "data":
      return update(conv, action.id, (m) =>
        action.extra == null ? { ...m, data: action.data } : { ...m, extras: m.extras?.map((e, i) => (i === action.extra ? { ...e, data: action.data } : e)) },
      );
    case "retry":
      return update(conv, action.id, (m) => ({ ...m, text: "", data: undefined, component: undefined, extras: undefined, turn: { status: "deciding" } }));
  }
}

/** The first line of the first message, cut at a word near 40 characters. */
function titleFrom(text: string) {
  const line = text.trim().split("\n")[0] || "Images and files";
  if (line.length <= 42) return line;
  const cut = line.slice(0, 42);
  return `${cut.slice(0, cut.lastIndexOf(" ") > 20 ? cut.lastIndexOf(" ") : 42).trimEnd()}…`;
}

const nextId = (prefix: string, taken: Iterable<string>) => {
  let n = 0;
  for (const id of taken) n = Math.max(n, Number(id.slice(prefix.length)) || 0);
  return `${prefix}${n + 1}`;
};

/** A turn cut off by a reload or a switch can't resume: settle it as an error. */
const settle = (conv: Conversation): Conversation => ({
  ...conv,
  messages: conv.messages.map((m) =>
    m.turn && (m.turn.status === "deciding" || m.turn.status === "writing")
      ? { ...m, turn: { ...m.turn, status: "error" as const, error: "Stopped before it finished." } }
      : m,
  ),
});

export function useChat() {
  const [conv, dispatch] = useReducer(reducer, undefined, empty);
  const [list, setList] = useState<Summary[]>([]);
  const [loaded, setLoaded] = useState(false);
  const abort = useRef<AbortController | null>(null);

  // Restore the history and the conversation that was open.
  useEffect(() => {
    let live = true;
    (async () => {
      try {
        const index = await get<Index>(INDEX_KEY);
        if (!live || !index) return;
        setList(index.list);
        const saved = index.active ? await get<Conversation>(convKey(index.active)) : undefined;
        if (live && saved) dispatch({ type: "replace", conv: settle(saved) });
      } catch {}
    })().finally(() => live && setLoaded(true));
    return () => {
      live = false;
    };
  }, []);

  // Keep the open conversation saved and its line in the history current.
  useEffect(() => {
    if (!loaded || !conv.id || !conv.messages.length) return;
    const t = setTimeout(() => {
      set(convKey(conv.id), conv).catch(() => {});
      setList((l) => {
        const entry: Summary = { id: conv.id, title: conv.title, updatedAt: conv.updatedAt, demo: conv.messages.some((m) => m.seeded) };
        const same = l.find((x) => x.id === conv.id);
        if (same && same.title === entry.title && same.updatedAt === entry.updatedAt) return l;
        return [entry, ...l.filter((x) => x.id !== conv.id)];
      });
    }, 300);
    return () => clearTimeout(t);
  }, [conv, loaded]);

  useEffect(() => {
    if (!loaded) return;
    set(INDEX_KEY, { active: conv.id || null, list } satisfies Index).catch(() => {});
  }, [list, conv.id, loaded]);

  const busy = conv.messages.some((m) => m.turn && (m.turn.status === "deciding" || m.turn.status === "writing"));

  const replace = useCallback((next: Conversation) => {
    abort.current?.abort();
    dispatch({ type: "replace", conv: next });
  }, []);

  /** Opens a conversation from the history. */
  const open = useCallback(
    async (id: string) => {
      const saved = await get<Conversation>(convKey(id)).catch(() => undefined);
      if (saved) replace(settle(saved));
      else setList((l) => l.filter((x) => x.id !== id));
    },
    [replace],
  );

  /** Deletes a conversation for good. Deleting the open one starts a new chat. */
  const remove = useCallback(
    (id: string) => {
      del(convKey(id)).catch(() => {});
      setList((l) => l.filter((x) => x.id !== id));
      if (id === conv.id) replace(empty());
    },
    [conv.id, replace],
  );

  const attach = useCallback(
    async (artifact: Artifact, note: string) => {
      dispatch({ type: "attach", artifact });
      if (artifact.kind !== "image") return;
      try {
        const res = await fetch("/api/describe", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ name: artifact.name, note, ...(await imagePayload(artifact)) }),
        });
        if (res.ok) dispatch({ type: "tag", id: artifact.id, tags: await res.json() });
      } catch {}
    },
    [],
  );

  const detach = useCallback((id: string) => dispatch({ type: "detach", id }), []);

  /** Keeps what the reader did inside a block (ticks, answers, edits) with the conversation. */
  const setData = useCallback((id: string, data: unknown, extra?: number) => dispatch({ type: "data", id, data, extra }), []);

  const artifactId = () => nextId("a", Object.keys(conv.artifacts));

  function send(text: string, attached: string[]) {
    const ids = conv.messages.map((m) => m.id);
    const user: Message = { id: nextId("m", ids), role: "user", text, at: Date.now(), ...(attached.length && { artifacts: attached }) };
    const assistant: Message = { id: nextId("m", [...ids, user.id]), role: "assistant", text: "", at: Date.now(), turn: { status: "deciding" } };
    dispatch({ type: "ask", user, assistant, convId: conv.id || crypto.randomUUID() });
    run(conv.messages, user, assistant.id);
  }

  /** Runs a failed turn again in place. */
  function retry(assistantId: string) {
    const i = conv.messages.findIndex((m) => m.id === assistantId);
    const user = conv.messages[i - 1];
    if (i < 1 || user.role !== "user") return;
    dispatch({ type: "retry", id: assistantId });
    run(conv.messages.slice(0, i - 1), user, assistantId);
  }

  async function run(before: Message[], user: Message, assistantId: string) {
    // Failed or unfinished turns stay on screen but out of the context.
    const messages = [...before.filter((m) => !m.turn || m.turn.status === "done"), user];
    const referenced = new Set(messages.flatMap((m) => m.artifacts ?? []));
    const artifacts = Object.values(conv.artifacts)
      .filter((a) => referenced.has(a.id))
      .map(({ src: _, ...a }) => a);

    abort.current?.abort();
    const controller = new AbortController();
    abort.current = controller;
    const fail = (message: string) => dispatch({ type: "error", id: assistantId, message });

    try {
      const images = await Promise.all(pickImages(conv, user.artifacts ?? []).map(imagePayload));
      const body: TurnRequest = {
        messages: messages.map(({ id, role, text, at, artifacts, component, data, extras }) => ({ id, role, text, at, artifacts, component, data, extras })),
        artifacts,
        images,
      };
      const res = await fetch("/api/turn", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
      if (!res.ok || !res.body) {
        fail(res.status === 413 ? "That's more than one request can carry. Try fewer or smaller files." : `The app's server returned ${res.status}.`);
        return;
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let finished = false;
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";
        for (const line of lines) {
          if (!line) continue;
          const event = JSON.parse(line) as TurnEvent;
          if (event.type === "decision") dispatch({ type: "decision", id: assistantId, decision: event.decision });
          else if (event.type === "partial") dispatch({ type: "partial", id: assistantId, text: event.text, data: event.data, extras: event.extras });
          else if (event.type === "done") {
            finished = true;
            dispatch({ type: "done", id: assistantId, text: event.text, data: event.data, extras: event.extras, writeMs: event.writeMs, writer: event.writer });
          } else if (event.type === "error") {
            finished = true;
            fail(event.message);
          }
        }
      }
      if (!finished) fail("The reply stopped partway. Try again.");
    } catch {
      if (!controller.signal.aborted) fail("Couldn't reach the app's server. Check that it's running.");
    }
  }

  const tokens = conv.lastInputTokens ?? estimateTokens(conv);
  const measured = conv.lastInputTokens != null;

  return { conv, list, loaded, busy, send, retry, attach, detach, setData, replace, open, remove, artifactId, tokens, measured };
}
